INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd27d89f-a7ac-4693-8cac-3e936c03bafd', '送隱者一絕', '送隐者一絕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["無媒徑路草蕭蕭，自古雲林遠市朝。","公道世間唯白髮，貴人頭上不曾饒。"]', '["無媒徑路草蕭蕭，自古云林远市朝。","公道世间唯白髮，貴人头上不曾饒。"]', '诗', 'shi', '', NULL, '送隱者一絕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a84b81f-8f14-4a52-bade-76474f4a4265', '題張處士山莊一絕', '題張处士山莊一絕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["好鳥疑敲磬，風蟬認軋箏。","修篁與嘉樹，偏倚半巖生。"]', '["好鸟疑敲磬，风蟬認軋箏。","修篁與嘉樹，偏倚半巖生。"]', '诗', 'shi', '', NULL, '題張處士山莊一絕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52afa82d-db98-41bc-95b0-638668f4b3a0', '有懷重送斛斯判官', '有懷重送斛斯判官', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蒼蒼烟月滿川亭，我有勞歌一爲聽。","將取離魂隨白騎，三台星裏拜文星。"]', '["蒼蒼烟月满川亭，我有勞歌一爲听。","將取離魂隨白騎，三台星裏拜文星。"]', '诗', 'shi', '', NULL, '有懷重送斛斯判官 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54008cd0-f9bf-424f-bc55-f15c1e9025f3', '贈別二首 一', '贈別二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["娉娉褭褭十三餘，豆蔻梢頭二月初。","春風十里揚州路，卷上珠簾總不如。"]', '["娉娉褭褭十三餘，豆蔻梢头二月初。","春风十里揚州路，卷上珠簾總不如。"]', '诗', 'shi', '', NULL, '贈別二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7f425de-143b-493d-bb51-13e27c68e871', '贈別二首 二', '贈別二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["多情却似總無情，唯覺尊前笑不成。","蠟燭有心還惜別，替人垂淚到天明。"]', '["多情却似總無情，唯覺尊前笑不成。","蠟燭有心還惜別，替人垂泪到天明。"]', '诗', 'shi', '', NULL, '贈別二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6486bc-d78c-4da4-b6e4-d44b964ca41c', '寄遠', '寄远', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["前山極遠碧雲合，清夜一聲白雪微。","欲寄相思千里月，溪邊殘照雨霏霏。"]', '["前山極远碧云合，清夜一声白雪微。","欲寄相思千里月，溪邊殘照雨霏霏。"]', '诗', 'shi', '', NULL, '寄遠 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b10941a1-5365-4dee-b4dc-01bf00d10b32', '少年行', '少年行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["官爲駿馬監，職帥羽林兒。","兩綬藏不見，落花何處期？","獵敲白玉鐙，怒袖紫金鎚。","田竇長留醉，蘇辛曲讓岐。","豪持出塞節，笑別遠山眉。","捷報雲臺賀，公卿拜壽巵。"]', '["官爲駿马監，職帥羽林兒。","兩綬藏不见，落花何处期？","獵敲白玉鐙，怒袖紫金鎚。","田竇长留醉，蘇辛曲讓岐。","豪持出塞節，笑別远山眉。","捷報云台賀，公卿拜壽巵。"]', '诗', 'shi', '', NULL, '少年行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624504f6-79e1-4ff4-85ef-38fb864fce36', '盆池', '盆池', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["鑿破蒼苔地，偷他一片天。","白雲生鏡裏，明月落堦前。"]', '["鑿破蒼苔地，偷他一片天。","白云生镜裏，明月落堦前。"]', '诗', 'shi', '', NULL, '盆池 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a624d90-4a1d-4319-bbdd-e470fd96914b', '有寄', '有寄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雲闊煙深樹，江澄水浴秋。","美人何處在，明月萬山頭。"]', '["云闊煙深樹，江澄水浴秋。","美人何处在，明月万山头。"]', '诗', 'shi', '', NULL, '有寄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045c7c1e-9eee-40a0-b81d-6431e8ba457f', '斑竹筒簟', '斑竹筒簟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["血染斑斑成錦紋，昔年遺恨至今存。","分明知是湘妃泣，何忍將身臥淚痕。"]', '["血染斑斑成錦紋，昔年遺恨至今存。","分明知是湘妃泣，何忍將身臥泪痕。"]', '诗', 'shi', '', NULL, '斑竹筒簟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd29e7b-b762-43ed-978c-ad693c7ec708', '和嚴惲秀才落花', '和嚴惲秀才落花', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["共惜流年留不得，且環流水醉流杯。","無情紅豔年年盛，不恨凋零却恨開。"]', '["共惜流年留不得，且环流水醉流杯。","無情紅豔年年盛，不恨凋零却恨开。"]', '诗', 'shi', '', NULL, '和嚴惲秀才落花 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f5e16e-dc85-4a1d-8668-de42da2b9853', '倡樓戲贈', '倡楼戲贈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["細柳橋邊深半春，纈衣簾裏動香塵。","無端有寄閑消息，背插金釵笑向人。"]', '["細柳橋邊深半春，纈衣簾裏动香塵。","無端有寄闲消息，背插金釵笑向人。"]', '诗', 'shi', '', NULL, '倡樓戲贈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfd18bd7-27b8-4502-9d4e-756edc9da381', '初上船留寄', '初上船留寄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["烟水本好尚，親交何慘悽。","況爲珠履客，即泊錦帆堤。","沙鴈同船去，田鵶遶岸啼。","此時還有味，必臥日從西。"]', '["烟水本好尚，親交何慘悽。","況爲珠履客，即泊錦帆堤。","沙鴈同船去，田鵶遶岸啼。","此时還有味，必臥日從西。"]', '诗', 'shi', '', NULL, '初上船留寄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03fbb30a-6407-405e-aa6a-2ac07781217e', '秋岸', '秋岸', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["河岸微退落，柳影微彫疎。","船上聽呼穉，堤南趁漉魚。","數帆旗去疾，一艇箭迴初。","曾入相思夢，因憑附遠書。"]', '["河岸微退落，柳影微彫疎。","船上听呼穉，堤南趁漉鱼。","數帆旗去疾，一艇箭迴初。","曾入相思梦，因憑附远书。"]', '诗', 'shi', '', NULL, '秋岸 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e14ccb-0e74-4d14-a441-7ea4c600b3b7', '過大梁聞河亭方讌贈孫子端', '過大梁闻河亭方讌贈孫子端', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["梁園縱翫歸應少，賦雪搜才去必頻。","板落豈緣無罰酒，不教客右更添人。"]', '["梁园縱翫归應少，賦雪搜才去必頻。","板落豈緣無罰酒，不教客右更添人。"]', '诗', 'shi', '', NULL, '過大梁聞河亭方讌贈孫子端 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00832388-93b3-4e79-bc30-5ab2ce6d5ee3', '題吳興消暑樓十二韻', '題吳兴消暑楼十二韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["晴日登攀好，危樓物象饒。","一溪通四境，萬岫饒層霄。","鳥翼舒華屋，魚鱗棹短橈。","浪花機乍織，雲葉匠新雕。","臺榭羅嘉卉，城池敞麗譙。","蟾蜍來作鑑，螮蝀引成橋。","燕任隨秋葉，人空集早潮。","楚鴻行盡直，沙鷺立偏翹。","暮角淒遊旅，清歌慘泬寥。","景牽遊目困，愁託酒腸銷。","遠吹流松韻，殘陽渡柳橋。","時陪庾公賞，還悟脫煩囂。"]', '["晴日登攀好，危楼物象饒。","一溪通四境，万岫饒層霄。","鸟翼舒华屋，鱼鱗棹短橈。","浪花機乍织，云葉匠新雕。","台榭羅嘉卉，城池敞丽譙。","蟾蜍来作鑑，螮蝀引成橋。","燕任隨秋葉，人空集早潮。","楚鴻行尽直，沙鷺立偏翹。","暮角淒游旅，清歌慘泬寥。","景牽游目困，愁託酒腸銷。","远吹流松韻，殘陽渡柳橋。","时陪庾公賞，還悟脫煩囂。"]', '诗', 'shi', '', NULL, '題吳興消暑樓十二韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1647238-0c30-4e36-a495-f906bf968b6e', '奉送中丞姊夫儔自大理卿出鎮江西敘事書懷因成十二韻', '奉送中丞姊夫儔自大理卿出鎮江西敘事书懷因成十二韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["惟帝憂南紀，搜賢與大藩。","梅仙調步驟，庾亮拂橐鞬。","一室何勞掃，三章自不冤。","精明如定國，孤峻似陳蕃。","灞岸秋猶嫩，藍橋水始喧。","紅旓罣石壁，黑矟斷雲根。","滕閣丹霄倚，章江碧玉奔。","一聲仙妓唱，千里暮江痕。","私好初童稚，官榮見子孫。","流年休挂念，萬事至無言。","玉輦君頻過，馮唐將未論。","庸書醻萬債，竹塢問樊村。"]', '["惟帝憂南紀，搜賢與大藩。","梅仙調步驟，庾亮拂橐鞬。","一室何勞掃，三章自不冤。","精明如定国，孤峻似陳蕃。","灞岸秋猶嫩，藍橋水始喧。","紅旓罣石壁，黑矟斷云根。","滕閣丹霄倚，章江碧玉奔。","一声仙妓唱，千里暮江痕。","私好初童稚，官榮见子孫。","流年休挂念，万事至無言。","玉輦君頻過，馮唐將未論。","庸书醻万債，竹塢问樊村。"]', '诗', 'shi', '', NULL, '奉送中丞姊夫儔自大理卿出鎮江西敘事書懷因成十二韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3505ad96-c84a-4b98-a39f-14ba342b75c1', '中丞業深韜畧志在功名再奉長句一篇兼有諮勸', '中丞業深韜畧志在功名再奉长句一篇兼有諮勸', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["檣似鄧林江拍天，越香巴錦萬千千。","滕王閣上柘枝鼓，徐孺亭西鐵軸船。","八部元侯非不貴，萬人師長豈無權。","要君嚴重疎歡樂，猶有河湟可下鞭。"]', '["檣似鄧林江拍天，越香巴錦万千千。","滕王閣上柘枝鼓，徐孺亭西鐵軸船。","八部元侯非不貴，万人師长豈無權。","要君嚴重疎歡乐，猶有河湟可下鞭。"]', '诗', 'shi', '', NULL, '中丞業深韜畧志在功名再奉長句一篇兼有諮勸 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f2cae42-5acf-4da1-a61f-72419368e255', '和裴傑秀才新櫻桃', '和裴傑秀才新櫻桃', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["新果真瓊液，人應宴紫蘭。","圓疑竊龍頷，色已奪雞冠。","遠火微微辨，繁星歷歷看。","茂先知味好，曼倩恨偷難。","忍用烹酥酪，從將翫玉盤。","流年如可駐，何必九華丹。"]', '["新果真瓊液，人應宴紫蘭。","圓疑竊龙頷，色已奪雞冠。","远火微微辨，繁星歷歷看。","茂先知味好，曼倩恨偷难。","忍用烹酥酪，從將翫玉盤。","流年如可駐，何必九华丹。"]', '诗', 'shi', '', NULL, '和裴傑秀才新櫻桃 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fdcd0fa-27a4-482b-bf8a-eaab0bc8bc42', '春思', '春思', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["豈君心的的，嗟我淚涓涓。","綿羽啼來久，錦鱗書未傳。","獸壚凝冷焰，羅暮蔽晴煙。","自是求佳夢，何須訝畫眠。"]', '["豈君心的的，嗟我泪涓涓。","綿羽啼来久，錦鱗书未傳。","獸壚凝冷焰，羅暮蔽晴煙。","自是求佳梦，何須訝畫眠。"]', '诗', 'shi', '', NULL, '春思 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94a19824-e433-4e6a-8f87-4c5a9cfe0ff9', '代人作', '代人作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["樓高春日早，屏束麝煙堆。","盼眄凝魂別，依稀夢雨來。","綠鬟羞妥麼，紅頰思天偎。","鬬草憐香蕙，簪花間雪梅。","戌遼雖咽切，遊蜀亦遲迴。","錦字梭懸壁，琴心月滿臺。","笑筵凝貝啓，眠箔曉珠開。","臘破征車動，袍襟對淚裁。"]', '["楼高春日早，屏束麝煙堆。","盼眄凝魂別，依稀梦雨来。","綠鬟羞妥麼，紅頰思天偎。","鬬草怜香蕙，簪花间雪梅。","戌遼雖咽切，游蜀亦遲迴。","錦字梭懸壁，琴心月满台。","笑筵凝貝啓，眠箔晓珠开。","臘破征车动，袍襟对泪裁。"]', '诗', 'shi', '', NULL, '代人作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('365b3c04-4d11-4731-82cc-d76e6c171c09', '偶題二首 一', '偶題二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["勞勞千里身，襟袂滿行塵。","深夜懸雙淚，短亭思遠人。","蒼江程未息，黑水夢何頻。","明月輕橈去，唯應釣赤鱗。"]', '["勞勞千里身，襟袂满行塵。","深夜懸雙泪，短亭思远人。","蒼江程未息，黑水梦何頻。","明月轻橈去，唯應釣赤鱗。"]', '诗', 'shi', '', NULL, '偶題二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b30699f-57ee-4173-b04f-68440e5ac8bd', '偶題二首 二', '偶題二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["有恨秋來極，無端別後知。","夜闌終耿耿，明發竟遲遲。","信已憑鴻去，歸唯與燕期。","只因明月見，千里兩相思。"]', '["有恨秋来極，無端別後知。","夜闌終耿耿，明發竟遲遲。","信已憑鴻去，归唯與燕期。","只因明月见，千里兩相思。"]', '诗', 'shi', '', NULL, '偶題二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887b1c4c-7031-43ee-9bfa-b296ea65e694', '冬至日遇京使發寄舍弟', '冬至日遇京使發寄舍弟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["遠信初憑雙鯉去，他鄉正遇一陽生。","尊前豈解愁家國，輦下唯能憶弟兄。","旅館夜憂姜被冷，暮江寒覺晏裘輕。","竹門風過還惆悵，疑是松窗雪打聲。"]', '["远信初憑雙鯉去，他乡正遇一陽生。","尊前豈解愁家国，輦下唯能憶弟兄。","旅館夜憂姜被冷，暮江寒覺晏裘轻。","竹门风過還惆悵，疑是松窗雪打声。"]', '诗', 'shi', '', NULL, '冬至日遇京使發寄舍弟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ff67319-1420-431b-8919-47d3ce3dc52e', '洛下送張曼容赴上黨召', '洛下送張曼容赴上黨召', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["歌闋罇殘恨却偏，憑君不用設離筵。","未趍雉尾隨元老，且驀羊腸過少年。","七葉漢貂真密近，一枝詵桂亦徒然。","羽書正急徵兵地，須遣頭風處處痊。"]', '["歌闋罇殘恨却偏，憑君不用設離筵。","未趍雉尾隨元老，且驀羊腸過少年。","七葉漢貂真密近，一枝詵桂亦徒然。","羽书正急徵兵地，須遣头风处处痊。"]', '诗', 'shi', '', NULL, '洛下送張曼容赴上黨召 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afef2ebf-09f0-4382-bd61-6fd6d976c5c4', '宣州留贈', '宣州留贈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["紅鉛濕盡半羅裙，洞府人間手欲分。","滿面風流雖似玉，四年夫婿恰如雲。","當春離恨盃長滿，倚柱關情日漸曛。","爲報眼波須穩當，五陵遊宕莫知聞。"]', '["紅鉛濕尽半羅裙，洞府人间手欲分。","满面风流雖似玉，四年夫婿恰如云。","當春離恨盃长满，倚柱关情日漸曛。","爲報眼波須穩當，五陵游宕莫知闻。"]', '诗', 'shi', '', NULL, '宣州留贈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('591996f4-bf22-4cdc-9b10-d0e4d76a08e3', '寄題宣州開元寺', '寄題宣州开元寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["松寺曾同一鶴棲，夜深臺殿月高低。","何人爲倚東樓柱，正是千山雪漲溪。"]', '["松寺曾同一鹤棲，夜深台殿月高低。","何人爲倚东楼柱，正是千山雪漲溪。"]', '诗', 'shi', '', NULL, '寄題宣州開元寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1ed5a7-7e08-4763-9b30-022940f7873c', '贈張祜', '贈張祜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["詩韻一逢君，平生稱所聞。","粉毫唯畫月，瓊尺只裁雲。","鯨陣人人懾，秋星歷歷分。","數篇留別我，羞殺李將軍。"]', '["诗韻一逢君，平生稱所闻。","粉毫唯畫月，瓊尺只裁云。","鯨陣人人懾，秋星歷歷分。","數篇留別我，羞殺李將軍。"]', '诗', 'shi', '', NULL, '贈張祜 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2b0867f-6c2d-459d-be41-e134ab5980c5', '殘春獨來南亭因寄張祜', '殘春独来南亭因寄張祜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["暖雲如粉草如茵，獨步長堤不見人。","一嶺桃花紅錦黦，半溪山水碧羅新。","高枝百舌猶欺鳥，帶葉梨花獨送春。","仲蔚欲知何處在，苦吟林下拂詩塵。"]', '["暖云如粉草如茵，独步长堤不见人。","一嶺桃花紅錦黦，半溪山水碧羅新。","高枝百舌猶欺鸟，带葉梨花独送春。","仲蔚欲知何处在，苦吟林下拂诗塵。"]', '诗', 'shi', '', NULL, '殘春獨來南亭因寄張祜 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40cc2a73-237a-486c-814d-7ee4b5ebc40f', '宣州開元寺南樓', '宣州开元寺南楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["小樓纔受一牀橫，終日看山酒滿傾。","可惜和風夜來雨，醉中虛度打窗聲。"]', '["小楼纔受一牀橫，終日看山酒满傾。","可惜和风夜来雨，醉中虛度打窗声。"]', '诗', 'shi', '', NULL, '宣州開元寺南樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4aa94ca-3755-45ec-9498-c06bb0f3a0dc', '寄遠人', '寄远人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["終日求人卜，迴迴道好音。","那時離別後，入夢到如今。"]', '["終日求人卜，迴迴道好音。","那时離別後，入梦到如今。"]', '诗', 'shi', '', NULL, '寄遠人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a303de-5b86-4c01-8ce8-a1dbf72c1809', '別沈處士', '別沈处士', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["舊事參差夢，新程邐迤秋。","故人如見憶，時到寺東樓。"]', '["旧事參差梦，新程邐迤秋。","故人如见憶，时到寺东楼。"]', '诗', 'shi', '', NULL, '別沈處士 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bacd210b-0cda-4410-abe0-ab047244236f', '留贈', '留贈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["舞靴應任閑人看，笑臉還須待我開。","不用鏡前空有淚，薔薇花謝即歸來。"]', '["舞靴應任闲人看，笑臉還須待我开。","不用镜前空有泪，薔薇花謝即归来。"]', '诗', 'shi', '', NULL, '留贈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c024c8e8-e428-4e6d-9745-3c2f3d18a0dd', '奉和僕射相公春澤稍愆聖君軫慮嘉雪忽降品彙昭蘇即事書成四韻', '奉和僕射相公春澤稍愆聖君軫慮嘉雪忽降品彙昭蘇即事书成四韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["飄來雞樹鳳池邊，漸壓瓊枝凍碧漣。","銀闕雙高銀漢裏，玉山橫列玉墀前。","昭陽殿下風迴急，承露盤中月彩圓。","上相抽毫歌帝德，一篇風雅美豐年。"]', '["飄来雞樹鳳池邊，漸壓瓊枝凍碧漣。","銀闕雙高銀漢裏，玉山橫列玉墀前。","昭陽殿下风迴急，承露盤中月彩圓。","上相抽毫歌帝德，一篇风雅美豐年。"]', '诗', 'shi', '', NULL, '奉和僕射相公春澤稍愆聖君軫慮嘉雪忽降品彙昭蘇即事書成四韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38191316-4846-4ca6-8ae5-dd6f045c10a1', '寄李播評事', '寄李播評事', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["子列光殊價，明時忍自高。","寧無好舟檝，不泛惡風濤。","大翼終難戢，奇鋒且自韜。","春來煙渚上，幾淨雪霜毫。"]', '["子列光殊價，明时忍自高。","寧無好舟檝，不泛惡风濤。","大翼終难戢，奇鋒且自韜。","春来煙渚上，幾淨雪霜毫。"]', '诗', 'shi', '', NULL, '寄李播評事 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c055fb2-6053-4b98-81b3-2d67d66a622e', '送牛相出鎮襄州', '送牛相出鎮襄州', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["盛時常注意，南雍暫分茅。","紫殿辭明主，巖廊別舊交。","危幢侵碧霧，寒斾獵紅旓。","德業懸秦鏡，威聲隱楚郊。","拜塵先灑淚，成廈昔容巢。","遙仰沈碑會，鴛鴦玉佩敲。"]', '["盛时常注意，南雍暫分茅。","紫殿辞明主，巖廊別旧交。","危幢侵碧霧，寒斾獵紅旓。","德業懸秦镜，威声隐楚郊。","拜塵先灑泪，成廈昔容巢。","遙仰沈碑會，鴛鴦玉佩敲。"]', '诗', 'shi', '', NULL, '送牛相出鎮襄州 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42edbc6-fb78-402d-93eb-b8ecaa8f2e97', '送薛邽二首 一', '送薛邽二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["可憐走馬騎驢漢，豈有風光肯占伊。","只有三張最惆悵，下山迴馬尚遲遲。"]', '["可怜走马騎驢漢，豈有风光肯占伊。","只有三張最惆悵，下山迴马尚遲遲。"]', '诗', 'shi', '', NULL, '送薛邽二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd29207-6187-45f2-a2ad-f79c03d0f46c', '送薛邽二首 二', '送薛邽二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["小捷風流已俊才，便將紅粉作金臺。","明年未去池陽郡，更乞春時却重來。"]', '["小捷风流已俊才，便將紅粉作金台。","明年未去池陽郡，更乞春时却重来。"]', '诗', 'shi', '', NULL, '送薛邽二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935bd7bc-a138-4dfb-8b26-f0fb92d6c05d', '見穆三十宅中庭海榴花謝', '见穆三十宅中庭海榴花謝', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["矜紅掩素似多才，不待櫻桃不逐梅。","春到未曾逢宴賞，雨餘爭解免低徊。","巧窮南國千般豔，趁得春風二月開。","堪恨王孫浪遊去，落英狼籍始歸來。"]', '["矜紅掩素似多才，不待櫻桃不逐梅。","春到未曾逢宴賞，雨餘爭解免低徊。","巧窮南国千般豔，趁得春风二月开。","堪恨王孫浪游去，落英狼籍始归来。"]', '诗', 'shi', '', NULL, '見穆三十宅中庭海榴花謝 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744e9a24-dd66-49db-98ca-e4bc6fc9000e', '留誨曹師等詩', '留誨曹師等诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["萬物有醜好，各一姿狀分。","唯人即不爾，學與不學論。","學非探其花，要自撥其根。","孝友與誠實，而不忘爾言。","根本既深實，柯葉自滋繁。","念爾無忽此，期以慶吾門。"]', '["万物有醜好，各一姿狀分。","唯人即不爾，学與不学論。","学非探其花，要自撥其根。","孝友與誠實，而不忘爾言。","根本既深實，柯葉自滋繁。","念爾無忽此，期以慶吾门。"]', '诗', 'shi', '', NULL, '留誨曹師等詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde1f648-3c9a-4cf0-bfed-a6d332e68971', '洛陽', '洛陽', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["文爭武戰就神功，時似開元天寶中。","已建玄戈收相土，應迴翠帽過離宮。","侯門草滿宜寒兔，洛浦沙深下塞鴻。","疑有女娥西望處，上陽煙樹正秋風。"]', '["文爭武戰就神功，时似开元天寶中。","已建玄戈收相土，應迴翠帽過離宮。","侯门草满宜寒兔，洛浦沙深下塞鴻。","疑有女娥西望处，上陽煙樹正秋风。"]', '诗', 'shi', '', NULL, '洛陽 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44df66a3-8658-4efd-82d8-1c81fa8e17c1', '寄唐州李玭尚書', '寄唐州李玭尚书', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["累代功勳照世光，奚胡聞道死心降。","書功筆禿三千管，領節門排十六雙。","先揖耿弇聲寂寂，今看黃霸事摐摐。","時人欲識胸襟否，彭蠡秋連萬里江。"]', '["累代功勳照世光，奚胡闻道死心降。","书功笔禿三千管，領節门排十六雙。","先揖耿弇声寂寂，今看黄霸事摐摐。","时人欲識胸襟否，彭蠡秋連万里江。"]', '诗', 'shi', '', NULL, '寄唐州李玭尚書 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1baa48c-1fe5-4baf-ad05-ef892110b9cf', '南陵道中', '南陵道中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["南陵水面漫悠悠，風緊雲輕欲變秋。","正是客心孤迴處，誰家紅袖凭江樓。"]', '["南陵水面漫悠悠，风緊云轻欲变秋。","正是客心孤迴处，誰家紅袖凭江楼。"]', '诗', 'shi', '', NULL, '南陵道中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('856d779c-f973-4f04-89a1-35d661850f18', '登九峰樓', '登九峰楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["晴江灩灩含淺沙，高低遶郭滯秋花。","牛歌魚笛山月上，鷺渚鶖梁溪日斜。","爲郡異鄉徒泥酒，杜陵芳草豈無家。"]', '["晴江灩灩含淺沙，高低遶郭滯秋花。","牛歌鱼笛山月上，鷺渚鶖梁溪日斜。","爲郡異乡徒泥酒，杜陵芳草豈無家。"]', '诗', 'shi', '', NULL, '登九峰樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccb7b70-88c7-4456-bfc4-a311163907b7', '別家', '別家', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["初歲嬌兒未識爺，別爺不拜手吒叉。","拊頭一別三千里，何日迎門却到家。"]', '["初歲嬌兒未識爺，別爺不拜手吒叉。","拊头一別三千里，何日迎门却到家。"]', '诗', 'shi', '', NULL, '別家 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1045aa50-9dce-4ad7-98a5-685b20577d2e', '歸家', '归家', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["穉子牽衣問，歸來何太遲。","共誰爭歲月，贏得鬢邊絲。"]', '["穉子牽衣问，归来何太遲。","共誰爭歲月，贏得鬢邊絲。"]', '诗', 'shi', '', NULL, '歸家 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af2e6182-d775-47aa-b4d9-9782276dab41', '雨', '雨', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["連雲接塞添迢遞，灑幕侵燈送寂寥。","一夜不眠孤客耳，主人牕外有芭蕉。"]', '["連云接塞添迢遞，灑幕侵灯送寂寥。","一夜不眠孤客耳，主人牕外有芭蕉。"]', '诗', 'shi', '', NULL, '雨 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34be7e6b-2b22-4dde-9f70-4c4c353a499d', '送人', '送人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["鴛鴦帳裏暖芙蓉，低泣關山幾萬重。","明鏡半邊釵一股，此生何處不相逢。"]', '["鴛鴦帳裏暖芙蓉，低泣关山幾万重。","明镜半邊釵一股，此生何处不相逢。"]', '诗', 'shi', '', NULL, '送人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('355ca8d1-8156-405f-bf92-306300aa2950', '遣懷', '遣懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["道泰時還泰，時來命不來。","何當離城市，高臥博山隈。"]', '["道泰时還泰，时来命不来。","何當離城市，高臥博山隈。"]', '诗', 'shi', '', NULL, '遣懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cc2085a-c6d6-47cf-b318-d0b7b5f0f03c', '醉贈薛道封', '醉贈薛道封', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["飲酒論文四百刻，水分雲隔二三年。","男兒事業知公有，賣與明君直幾錢。"]', '["饮酒論文四百刻，水分云隔二三年。","男兒事業知公有，賣與明君直幾錢。"]', '诗', 'shi', '', NULL, '醉贈薛道封 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bcbe47d-5f86-486f-9331-b5767bd2bdc1', '歙州盧中丞見惠名醖', '歙州盧中丞见惠名醖', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["誰憐賤子啓窮途，太守封來酒一壺。","攻破是非渾似夢，削平身世有如無。","醺醺若借嵇康懶，兀兀仍添甯武愚。","猶念悲秋更分賜，夾溪紅蓼映風蒲。"]', '["誰怜賤子啓窮途，太守封来酒一壺。","攻破是非渾似梦，削平身世有如無。","醺醺若借嵇康懶，兀兀仍添甯武愚。","猶念悲秋更分賜，夾溪紅蓼映风蒲。"]', '诗', 'shi', '', NULL, '歙州盧中丞見惠名醖 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6e4d4dd-6e8a-430a-b2ba-7cbf27dae7be', '詠襪', '詠襪', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["鈿尺裁量減四分，纖纖玉笋裹輕雲。","五陵年少欺他醉，笑把花前出畫裙。"]', '["鈿尺裁量減四分，纖纖玉笋裹轻云。","五陵年少欺他醉，笑把花前出畫裙。"]', '诗', 'shi', '', NULL, '詠襪 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3031ec06-0355-494d-92cc-3a8e59c14c0c', '宮詞二首 一', '宮词二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蟬翼輕綃傅體紅，玉膚如醉向春風。","深宮鎖閉猶疑惑，更取丹沙試辟宮。"]', '["蟬翼轻綃傅體紅，玉膚如醉向春风。","深宮鎖閉猶疑惑，更取丹沙試辟宮。"]', '诗', 'shi', '', NULL, '宮詞二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e64a32c-3280-4976-ba88-d1a228252032', '宮詞二首 二', '宮词二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["監宮引出暫開門，隨例須朝不是恩。","銀鑰却收金鎖合，月明花落又黃昏。"]', '["監宮引出暫开门，隨例須朝不是恩。","銀鑰却收金鎖合，月明花落又黄昏。"]', '诗', 'shi', '', NULL, '宮詞二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba9a9be-713d-490f-beeb-ed5207561d49', '月', '月', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["三十六宮秋夜深，昭陽歌斷信沈沈。","唯應獨伴陳皇后，照見長門望幸心。"]', '["三十六宮秋夜深，昭陽歌斷信沈沈。","唯應独伴陳皇后，照见长门望幸心。"]', '诗', 'shi', '', NULL, '月 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ec79f1-061f-44ef-97f0-3ffaa3e1b3d8', '忍死留別獻監鐵裴相公二十叔', '忍死留別獻監鐵裴相公二十叔', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["賢相輔明主，蒼生壽域開。","青春辭白日，幽壤作黃埃。","豈是無多士，偏蒙不棄才。","孤墳三尺土，誰可爲培栽。"]', '["賢相輔明主，蒼生壽域开。","青春辞白日，幽壤作黄埃。","豈是無多士，偏蒙不棄才。","孤墳三尺土，誰可爲培栽。"]', '诗', 'shi', '', NULL, '忍死留別獻監鐵裴相公二十叔 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13456be7-bc92-41c9-ae31-991f5fe92bb5', '悲吳王城', '悲吳王城', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["二月春風江上來，水精波動碎樓臺。","吳王宮殿柳含翠，蘇小宅房花正開。","解舞細腰何處往，能歌姹女逐誰迴。","千秋萬古無消息，國作荒原人作灰。"]', '["二月春风江上来，水精波动碎楼台。","吳王宮殿柳含翠，蘇小宅房花正开。","解舞細腰何处往，能歌姹女逐誰迴。","千秋万古無消息，国作荒原人作灰。"]', '诗', 'shi', '', NULL, '悲吳王城 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dab2d47-1373-43bb-99b0-06b6d5129945', '閨情代作', '閨情代作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["梧桐葉落鴈初歸，迢遞無因寄遠衣。","月照石泉金點冷，鳳酣簫管玉聲微。","佳人刀杵秋風外，蕩子從征夢寐希。","遙望戌樓天欲曉，滿城鼕鼓白雲飛。"]', '["梧桐葉落鴈初归，迢遞無因寄远衣。","月照石泉金点冷，鳳酣簫管玉声微。","佳人刀杵秋风外，蕩子從征梦寐希。","遙望戌楼天欲晓，满城鼕鼓白云飞。"]', '诗', 'shi', '', NULL, '閨情代作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8d3ec3e-a9de-48b3-bbf9-0def81e3e1c6', '寄沈褒秀才', '寄沈褒秀才', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["晴河萬里色如刀，處處浮雲臥碧桃。","仙桂茂時金鏡曉，洛波飛處玉容高。","雄如寶劒衝牛斗，麗似鴛鴦養羽毛。","他日憶君何處望，九天香滿碧蕭騷。"]', '["晴河万里色如刀，处处浮云臥碧桃。","仙桂茂时金镜晓，洛波飞处玉容高。","雄如寶劒衝牛斗，丽似鴛鴦養羽毛。","他日憶君何处望，九天香满碧蕭騷。"]', '诗', 'shi', '', NULL, '寄沈褒秀才 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23c0686-ed4f-49fe-bef0-87d3f0208bc9', '入關', '入关', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["東西南北數衢通，曾取江西徑過東。","今日更尋南去路，未秋應有北歸鴻。"]', '["东西南北數衢通，曾取江西徑過东。","今日更尋南去路，未秋應有北归鴻。"]', '诗', 'shi', '', NULL, '入關 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70b17f7-1b78-4f15-a342-a42d3ff8835f', '及第後寄長安故人', '及第後寄长安故人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["東都放牓未花開，三十三人走馬迴。","秦地少年多釀酒，已將春色入關來。"]', '["东都放牓未花开，三十三人走马迴。","秦地少年多釀酒，已將春色入关来。"]', '诗', 'shi', '', NULL, '及第後寄長安故人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c063c6-ca9b-416b-9bfc-2c86bbb99f15', '偶作', '偶作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["才子風流詠曉霞，倚樓吟住日初斜。","驚殺東隣繡牀女，錯將黃暈壓檀花。"]', '["才子风流詠晓霞，倚楼吟住日初斜。","驚殺东隣繡牀女，錯將黄暈壓檀花。"]', '诗', 'shi', '', NULL, '偶作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('146a9f1c-7fc6-47b5-be72-f668cfc8373b', '贈終南蘭若僧', '贈終南蘭若僧', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["北闕南山是故鄉，兩枝仙桂一時芳。","休公都不知名姓，始覺禪門氣味長。"]', '["北闕南山是故乡，兩枝仙桂一时芳。","休公都不知名姓，始覺禪门氣味长。"]', '诗', 'shi', '', NULL, '贈終南蘭若僧 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ae04dc-89af-45d6-9e31-204a01df801d', '遣懷', '遣懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["落魄江南載酒行，楚腰腸斷掌中輕。","十年一覺揚州夢，贏得青樓薄倖名。"]', '["落魄江南載酒行，楚腰腸斷掌中轻。","十年一覺揚州梦，贏得青楼薄倖名。"]', '诗', 'shi', '', NULL, '遣懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e6c0b0-c1d7-4f12-9dd9-f96a10b81550', '秋感', '秋感', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["金風萬里思何盡，玉樹一窓秋影寒。","獨掩柴門明月下，淚流香袂倚闌干。"]', '["金风万里思何尽，玉樹一窓秋影寒。","独掩柴门明月下，泪流香袂倚闌干。"]', '诗', 'shi', '', NULL, '秋感 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9b9e25-0e0d-4eca-83c6-43d1b4fa241f', '贈漁父', '贈漁父', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蘆花深澤靜垂綸，月夕煙朝幾十春。","自說孤舟寒水畔，不曾逢著獨醒人。"]', '["蘆花深澤静垂綸，月夕煙朝幾十春。","自说孤舟寒水畔，不曾逢著独醒人。"]', '诗', 'shi', '', NULL, '贈漁父 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffc847e7-2310-4a97-94e1-0ae702802599', '歎花', '歎花', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["自恨尋芳到已遲，往年曾見未開時。","如今風擺花狼籍，綠葉成陰子滿枝。"]', '["自恨尋芳到已遲，往年曾见未开时。","如今风擺花狼籍，綠葉成陰子满枝。"]', '诗', 'shi', '', NULL, '歎花 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddc766a7-d68e-4866-8605-c629e84ac134', '題劉秀才新竹', '題劉秀才新竹', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["數莖幽玉色，曉夕翠煙分。","聲破寒窗夢，根穿綠蘚紋。","漸籠當檻日，欲礙入簾雲。","不是山陰客，何人愛此君。"]', '["數莖幽玉色，晓夕翠煙分。","声破寒窗梦，根穿綠蘚紋。","漸籠當檻日，欲礙入簾云。","不是山陰客，何人愛此君。"]', '诗', 'shi', '', NULL, '題劉秀才新竹 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56da3304-439a-400b-b283-16de3add74ce', '山行', '山行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["遠上寒山石徑斜，白雲生處有人家。","停車坐愛楓林晚，霜葉紅於二月花。"]', '["远上寒山石徑斜，白云生处有人家。","停车坐愛楓林晚，霜葉紅於二月花。"]', '诗', 'shi', '', NULL, '山行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea52e3d8-e8b5-4acd-a85f-74d13d22048a', '書懷', '书懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["滿眼青山未得過，鏡中無那鬢絲何。","秖言旋老轉無事，欲到中年事更多。"]', '["满眼青山未得過，镜中無那鬢絲何。","秖言旋老轉無事，欲到中年事更多。"]', '诗', 'shi', '', NULL, '書懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc1af10-9062-47ef-aedb-ff11013997c4', '紫薇花', '紫薇花', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["曉迎秋露一枝新，不占園中最上春。","桃李無言又何在，向風偏笑豔陽人。"]', '["晓迎秋露一枝新，不占园中最上春。","桃李無言又何在，向风偏笑豔陽人。"]', '诗', 'shi', '', NULL, '紫薇花 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7162d8b-3d05-4385-a92a-0a6ddf32e7d0', '醉後呈崔大夫', '醉後呈崔大夫', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["謝傅秋涼閱管弦，徒教賤子侍華筵。","溪頭正雨歸不得，辜負東窓一覺眠。"]', '["謝傅秋涼閱管弦，徒教賤子侍华筵。","溪头正雨归不得，辜負东窓一覺眠。"]', '诗', 'shi', '', NULL, '醉後呈崔大夫 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6980e261-1fc5-4972-9b07-650f312434b0', '和宣州沈大夫登北樓書懷', '和宣州沈大夫登北楼书懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["兵符嚴重辭金馬，星劒光芒射斗牛。","筆落青山飄古韻，帳開紅斾照高秋。","香連日彩浮綃幕，溪逐歌聲遶畫樓。","可惜登臨佳麗地，羽儀須去鳳池遊。"]', '["兵符嚴重辞金马，星劒光芒射斗牛。","笔落青山飄古韻，帳开紅斾照高秋。","香連日彩浮綃幕，溪逐歌声遶畫楼。","可惜登臨佳丽地，羽儀須去鳳池游。"]', '诗', 'shi', '', NULL, '和宣州沈大夫登北樓書懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dbd4fda-b163-459c-be32-d8a68f109ea0', '夜雨', '夜雨', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["九月三十日，雨聲如別秋。","無端滿階葉，共白幾人頭。","點滴侵寒夢，蕭騷著淡愁。","漁歌聽不唱，蓑濕棹迴舟。"]', '["九月三十日，雨声如別秋。","無端满階葉，共白幾人头。","点滴侵寒梦，蕭騷著淡愁。","漁歌听不唱，蓑濕棹迴舟。"]', '诗', 'shi', '', NULL, '夜雨 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f227dee2-18e9-4d48-8e35-f1334c178d14', '方響', '方响', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["數條秋水挂琅玕，玉手丁當怕夜寒。","曲盡連敲三四下，恐驚珠淚落金盤。"]', '["數條秋水挂琅玕，玉手丁當怕夜寒。","曲尽連敲三四下，恐驚珠泪落金盤。"]', '诗', 'shi', '', NULL, '方響 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c7187b-f03e-4d9f-b214-4eb888efe7b3', '將出關宿層峰驛却寄李諫議', '將出关宿層峰驛却寄李諫議', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["孤驛在重阻，雲根掩柴扉。","數聲暮禽切，萬壑秋意歸。","心馳碧泉澗，目斷青瑣闈。","明日武關外，夢魂勞遠飛。"]', '["孤驛在重阻，云根掩柴扉。","數声暮禽切，万壑秋意归。","心驰碧泉澗，目斷青瑣闈。","明日武关外，梦魂勞远飞。"]', '诗', 'shi', '', NULL, '將出關宿層峰驛却寄李諫議 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0b64169-685b-4a85-b9fa-5d45bb30b487', '使回枉唐州崔司馬書兼寄四韻因和', '使回枉唐州崔司马书兼寄四韻因和', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["清晨候吏把書來，十載離憂得暫開。","癡叔去時還讀易，仲容多興索銜杯。","人心計日殷勤望，馬首隨雲早晚迴。","莫爲霜臺愁歲暮，潛龍須待一聲雷。"]', '["清晨候吏把书来，十載離憂得暫开。","癡叔去时還读易，仲容多兴索銜杯。","人心計日殷勤望，马首隨云早晚迴。","莫爲霜台愁歲暮，潛龙須待一声雷。"]', '诗', 'shi', '', NULL, '使回枉唐州崔司馬書兼寄四韻因和 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29031e87-be6f-46b1-9387-e2a9d9083231', '郡齋秋夜即事寄斛斯處士許秀才', '郡斋秋夜即事寄斛斯处士許秀才', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["有客誰人肯夜過，獨憐風景奈愁何。","邊鴻怨處迷霜久，庭樹空來見月多。","故國杳無千里信，綵弦時伴一聲歌。","馳心秖待城烏曉，幾對虛簷望白河。"]', '["有客誰人肯夜過，独怜风景奈愁何。","邊鴻怨处迷霜久，庭樹空来见月多。","故国杳無千里信，綵弦时伴一声歌。","驰心秖待城烏晓，幾对虛簷望白河。"]', '诗', 'shi', '', NULL, '郡齋秋夜即事寄斛斯處士許秀才 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353c08bf-bf93-41e2-8c1e-826514703eab', '早春題真上人院', '早春題真上人院', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["清羸已近百年身，古寺風煙又一春。","寰海自成戎馬地，唯師曾是太平人。"]', '["清羸已近百年身，古寺风煙又一春。","寰海自成戎马地，唯師曾是太平人。"]', '诗', 'shi', '', NULL, '早春題真上人院 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d883cb-709d-4742-89fe-d98489e24baf', '對花微疾不飲呈坐中諸公', '对花微疾不饮呈坐中諸公', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["花前雖病亦提壺，數調持觴興有無。","盡日臨風羨人醉，雪香空伴白髭鬚。"]', '["花前雖病亦提壺，數調持觴兴有無。","尽日臨风羨人醉，雪香空伴白髭鬚。"]', '诗', 'shi', '', NULL, '對花微疾不飲呈坐中諸公 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53dc5577-4c52-4f22-bf67-05d23d2be2a8', '酬王秀才桃花園見寄', '酬王秀才桃花园见寄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["桃滿西園淑景催，幾多紅豔淺深開。","此花不逐溪流出，晉客無因入洞來。"]', '["桃满西园淑景催，幾多紅豔淺深开。","此花不逐溪流出，晉客無因入洞来。"]', '诗', 'shi', '', NULL, '酬王秀才桃花園見寄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0aaa787-f317-4f0c-9f55-9b9dc8463f0c', '走筆送杜十三歸京', '走笔送杜十三归京', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["煙鴻上漢聲聲遠，逸驥尋雲步步高。","應笑內兄年六十，郡城閑坐養霜毛。"]', '["煙鴻上漢声声远，逸驥尋云步步高。","應笑內兄年六十，郡城闲坐養霜毛。"]', '诗', 'shi', '', NULL, '走筆送杜十三歸京 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a1d27e-cb12-4271-8a72-8b6502fee9d9', '送王十至褒中因寄尚書', '送王十至褒中因寄尚书', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["闕下經年別，人間兩地情。","壇場新漢將，煙月古隋城。","鴈去梁山遠，雲高楚岫明。","君家荷藕好，緘恨寄遙程。"]', '["闕下經年別，人间兩地情。","壇場新漢將，煙月古隋城。","鴈去梁山远，云高楚岫明。","君家荷藕好，緘恨寄遙程。"]', '诗', 'shi', '', NULL, '送王十至褒中因寄尚書 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76fd16e7-c7d2-4fc6-8c62-6e8b218b800c', '後池泛舟送王十', '後池泛舟送王十', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["相送西郊暮景和，青蒼竹外遶寒波。","爲君蘸甲十分飲，應見離心一倍多。"]', '["相送西郊暮景和，青蒼竹外遶寒波。","爲君蘸甲十分饮，應见離心一倍多。"]', '诗', 'shi', '', NULL, '後池泛舟送王十 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33602a34-aa2e-4929-8a79-11e06a21da22', '重送王十', '重送王十', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["執袂還應立馬看，向來離思始知難。","鴈飛不見行塵滅，景下山遙極目寒。"]', '["執袂還應立马看，向来離思始知难。","鴈飞不见行塵滅，景下山遙極目寒。"]', '诗', 'shi', '', NULL, '重送王十 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfad7953-8549-4d8d-a571-1e1aa1feda0f', '洛陽秋夕', '洛陽秋夕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["泠泠寒水帶霜風，更在天橋夜景中。","清禁漏閑煙樹寂，月輪移在上陽宮。"]', '["泠泠寒水带霜风，更在天橋夜景中。","清禁漏闲煙樹寂，月輪移在上陽宮。"]', '诗', 'shi', '', NULL, '洛陽秋夕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ffa9bea-4f65-4901-b0a4-601d88e106b9', '贈獵騎', '贈獵騎', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["已落雙鵰血尚新，鳴鞭走馬又翻身。","憑君莫射南來鴈，恐有家書寄遠人。"]', '["已落雙鵰血尚新，鳴鞭走马又翻身。","憑君莫射南来鴈，恐有家书寄远人。"]', '诗', 'shi', '', NULL, '贈獵騎 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f2eb708-7679-453d-91d0-55c84debc2ad', '懷吳中馮秀才', '懷吳中馮秀才', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["長洲苑外草蕭蕭，却筭遊程歲月遙。","唯有別時今不忘，暮煙秋雨過楓橋。"]', '["长洲苑外草蕭蕭，却筭游程歲月遙。","唯有別时今不忘，暮煙秋雨過楓橋。"]', '诗', 'shi', '', NULL, '懷吳中馮秀才 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a4d2fe-dd84-472e-8b48-222754dcd330', '寄東塔僧', '寄东塔僧', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["初月微明漏白煙，碧松梢外挂青天。","西風靜起傳深夜，應送愁吟入夜禪。"]', '["初月微明漏白煙，碧松梢外挂青天。","西风静起傳深夜，應送愁吟入夜禪。"]', '诗', 'shi', '', NULL, '寄東塔僧 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d12edd29-d467-4b19-b3f5-533fa5c8d56a', '秋夕', '秋夕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["紅燭秋光冷畫屏，輕羅小扇撲流螢。","天階夜色涼如水，坐看牽牛織女星。"]', '["紅燭秋光冷畫屏，轻羅小扇撲流螢。","天階夜色涼如水，坐看牽牛织女星。"]', '诗', 'shi', '', NULL, '秋夕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8be77ff-dde3-4aa7-808f-66ff1bfbd378', '瑤瑟', '瑤瑟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["玉仙瑤瑟夜珊珊，月過樓西桂燭殘。","風景人間不如此，動搖湘水徹明寒。"]', '["玉仙瑤瑟夜珊珊，月過楼西桂燭殘。","风景人间不如此，动搖湘水徹明寒。"]', '诗', 'shi', '', NULL, '瑤瑟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e926c44-9848-4678-ac14-0ea84a50559f', '送故人歸山', '送故人归山', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["三清洞裏無端別，又拂塵衣欲臥雲。","看著挂冠迷處所，北山蘿月在移文。"]', '["三清洞裏無端別，又拂塵衣欲臥云。","看著挂冠迷处所，北山蘿月在移文。"]', '诗', 'shi', '', NULL, '送故人歸山 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4e9bb7-d960-4805-a2a5-a743c48bd9f5', '聞角', '闻角', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["曉樓煙檻出雲霄，景下林塘已寂寥。","城角爲秋悲更遠，護霜雲破海天遙。"]', '["晓楼煙檻出云霄，景下林塘已寂寥。","城角爲秋悲更远，護霜云破海天遙。"]', '诗', 'shi', '', NULL, '聞角 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976afd1d-415d-4389-8678-87707fc981e7', '押兵甲發谷口寄諸公', '押兵甲發谷口寄諸公', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["曉澗青青桂色孤，楚人隨玉上天衢。","水辭谷口山寒少，今日風頭校暖無。"]', '["晓澗青青桂色孤，楚人隨玉上天衢。","水辞谷口山寒少，今日风头校暖無。"]', '诗', 'shi', '', NULL, '押兵甲發谷口寄諸公 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9b1618-e32a-40c0-abee-7ffc7ed21123', '和令狐侍御賞蕙草', '和令狐侍御賞蕙草', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["尋常詩思巧如春，又喜幽亭蕙草新。","本是馨香比君子，遶欄今更爲何人。"]', '["尋常诗思巧如春，又喜幽亭蕙草新。","本是馨香比君子，遶欄今更爲何人。"]', '诗', 'shi', '', NULL, '和令狐侍御賞蕙草 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41835e6-0f1a-4bde-8ff7-f657f5a93d9c', '偶題', '偶題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["道在人間或可傳，小還輕變已多年。","今來海上昇高望，不到蓬萊不是仙。"]', '["道在人间或可傳，小還轻变已多年。","今来海上昇高望，不到蓬萊不是仙。"]', '诗', 'shi', '', NULL, '偶題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7b8a30-a906-4697-9fda-433d36fd829a', '三川驛伏覽座主舍人留題', '三川驛伏覽座主舍人留題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["舊跡依然已十秋，雪山當面照銀鉤。","懷恩淚盡霜天曉，一片餘霞映驛樓。"]', '["旧跡依然已十秋，雪山當面照銀鉤。","懷恩泪尽霜天晓，一片餘霞映驛楼。"]', '诗', 'shi', '', NULL, '三川驛伏覽座主舍人留題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b74318ae-8c3e-44cd-9743-c51b02789e0b', '陝州醉贈裴四同年', '陝州醉贈裴四同年', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["淒風洛下同羈思，遲日棠陰得醉歌。","自笑與君三歲別，頭銜依舊鬢絲多。"]', '["淒风洛下同羈思，遲日棠陰得醉歌。","自笑與君三歲別，头銜依旧鬢絲多。"]', '诗', 'shi', '', NULL, '陝州醉贈裴四同年 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('049f3daf-df10-4f32-b819-604f5642c64b', '破鏡', '破镜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["佳人失手鏡初分，何日團圓再會君。","今朝萬里秋風起，山北山南一片雲。"]', '["佳人失手镜初分，何日團圓再會君。","今朝万里秋风起，山北山南一片云。"]', '诗', 'shi', '', NULL, '破鏡 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f25016b2-eeed-483c-9f4d-a3c093c77f0f', '長安雪後', '长安雪後', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["秦陵漢苑參差雪，北闕南山次第春。","車馬滿城原上去，豈知惆悵有閑人。"]', '["秦陵漢苑參差雪，北闕南山次第春。","车马满城原上去，豈知惆悵有闲人。"]', '诗', 'shi', '', NULL, '長安雪後 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06d59c41-8301-473d-9239-c4a3be3a561a', '華清宮', '华清宮', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["零葉飜紅萬樹霜，玉蓮開蘂暖泉香。","行雲不下朝元閣，一曲淋鈴淚數行。"]', '["零葉飜紅万樹霜，玉蓮开蘂暖泉香。","行云不下朝元閣，一曲淋鈴泪數行。"]', '诗', 'shi', '', NULL, '華清宮 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceb63d3c-a86e-45b6-b0dc-e51878c64fe1', '冬日題智門寺北樓', '冬日題智门寺北楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["滿懷多少是恩酬，未見功名已白頭。","不爲尋山試筋力，豈能寒上背雲樓。"]', '["满懷多少是恩酬，未见功名已白头。","不爲尋山試筋力，豈能寒上背云楼。"]', '诗', 'shi', '', NULL, '冬日題智門寺北樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ec6cfe-5d91-4324-8fd0-2b4cfc2e19cd', '別王十後遣京使累路附書', '別王十後遣京使累路附书', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["重關曉度宿雲寒，羸馬緣知步步難。","此信的應中路見，亂山何處拆書看。"]', '["重关晓度宿云寒，羸马緣知步步难。","此信的應中路见，亂山何处拆书看。"]', '诗', 'shi', '', NULL, '別王十後遣京使累路附書 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024a43fd-2ce0-44dd-bef9-545e6cf9aafc', '許秀才至辱李蘄州絕句問斷酒之情因寄', '許秀才至辱李蘄州絕句问斷酒之情因寄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["有客南來話所思，故人遙枉醉中詩。","暫因微疾須防酒，不是歡情減舊時。"]', '["有客南来話所思，故人遙枉醉中诗。","暫因微疾須防酒，不是歡情減旧时。"]', '诗', 'shi', '', NULL, '許秀才至辱李蘄州絕句問斷酒之情因寄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd406b9-476e-4ce6-9af9-a0e29ae94a9f', '送張判官歸兼謁鄂州大夫', '送張判官归兼謁鄂州大夫', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["處士聞名早，遊秦獻疏迴。","腹中書萬卷，身外酒千盃。","江雨春波闊，園林客夢催。","今君拜旌戟，凜凜近霜臺。"]', '["处士闻名早，游秦獻疏迴。","腹中书万卷，身外酒千盃。","江雨春波闊，园林客梦催。","今君拜旌戟，凜凜近霜台。"]', '诗', 'shi', '', NULL, '送張判官歸兼謁鄂州大夫 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0040d15-939e-413c-bb1c-4f7414739294', '宿長慶寺', '宿长慶寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["南行步步遠浮塵，更近青山昨夜隣。","高鐸數聲秋撼玉，霽河千里曉橫銀。","紅蕖影落前池淨，綠稻香來野逕頻。","終日官閑無一事，不妨長醉是遊人。"]', '["南行步步远浮塵，更近青山昨夜隣。","高鐸數声秋撼玉，霽河千里晓橫銀。","紅蕖影落前池淨，綠稻香来野逕頻。","終日官闲無一事，不妨长醉是游人。"]', '诗', 'shi', '', NULL, '宿長慶寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ffb9229-778c-4658-a3f2-3647f2c78658', '望少華三首 一', '望少华三首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["身隨白日看將老，心與青雲自有期。","今對晴峰無十里，世緣多累暗生悲。"]', '["身隨白日看將老，心與青云自有期。","今对晴峰無十里，世緣多累暗生悲。"]', '诗', 'shi', '', NULL, '望少華三首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5167f16f-2433-4946-9838-33fe3aaa5737', '望少華三首 二', '望少华三首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["文字波中去不還，物情初雨是非閑。","時名竟是無端事，羞對靈山道愛山。"]', '["文字波中去不還，物情初雨是非闲。","时名竟是無端事，羞对靈山道愛山。"]', '诗', 'shi', '', NULL, '望少華三首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63f59cc5-72e0-49bf-b420-13d2bbfa6d0f', '望少華三首 三', '望少华三首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["眼看雲鶴不相隨，何況塵中事作爲。","好伴羽人深洞去，月前秋聽玉參差。"]', '["眼看云鹤不相隨，何況塵中事作爲。","好伴羽人深洞去，月前秋听玉參差。"]', '诗', 'shi', '', NULL, '望少華三首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec610ff7-9b53-4b32-a1ba-3be555613e3d', '登澧州驛樓寄京兆韋尹', '登澧州驛楼寄京兆韋尹', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一話涔陽舊使君，郡人迴首望青雲。","政聲長與江聲在，自到津樓日夜聞。"]', '["一話涔陽旧使君，郡人迴首望青云。","政声长與江声在，自到津楼日夜闻。"]', '诗', 'shi', '', NULL, '登澧州驛樓寄京兆韋尹 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5597111-7112-45e8-8586-4faecb01f022', '長安晴望', '长安晴望', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["翠屏山對鳳城開，碧落搖光霽後來。","廻識六龍巡幸處，飛煙閑遶望春臺。"]', '["翠屏山对鳳城开，碧落搖光霽後来。","廻識六龙巡幸处，飞煙闲遶望春台。"]', '诗', 'shi', '', NULL, '長安晴望 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40fdde29-bf45-4fa7-a789-92fd327974e0', '歲旦朝回口號', '歲旦朝回口號', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["星河猶在整朝衣，遠望天門再拜歸。","笑向春風初五十，敢言知命且知非。"]', '["星河猶在整朝衣，远望天门再拜归。","笑向春风初五十，敢言知命且知非。"]', '诗', 'shi', '', NULL, '歲旦朝回口號 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd45230-903a-405d-bb6a-4640a6c18040', '驌驦駿', '驌驦駿', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["瑤池罷遊宴，良樂委塵沙。","遭遇不遭遇，鹽車與鼓車。"]', '["瑤池罷游宴，良乐委塵沙。","遭遇不遭遇，鹽车與鼓车。"]', '诗', 'shi', '', NULL, '驌驦駿 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad6ca7c-09f5-4e83-9448-179f08519125', '龍丘途中二首 一', '龙丘途中二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["漢苑殘花別，吳江盛夏來。","唯看萬樹合，不見一枝開。"]', '["漢苑殘花別，吳江盛夏来。","唯看万樹合，不见一枝开。"]', '诗', 'shi', '', NULL, '龍丘途中二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8f958fb-19a3-4f73-a257-c2b3888fe227', '龍丘途中二首 二', '龙丘途中二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["水色饒湘浦，灘聲怯建溪。","淚流迴月上，可得更猿啼。"]', '["水色饒湘浦，灘声怯建溪。","泪流迴月上，可得更猿啼。"]', '诗', 'shi', '', NULL, '龍丘途中二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a7af025-d3cc-48aa-a889-d4760fa64e76', '宮人塚', '宮人塚', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["盡是離宮院中女，苑牆城外塚纍纍。","少年入內教歌舞，不識君王到老時。"]', '["尽是離宮院中女，苑牆城外塚纍纍。","少年入內教歌舞，不識君王到老时。"]', '诗', 'shi', '', NULL, '宮人塚 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca25064-fdc9-4fb1-8dae-b888e246550b', '寄浙西李判官', '寄浙西李判官', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["燕臺上客意[何如]，四五年來漸漸疎。","直道莫拋男子業，遭時還與故人書。","青雲滿眼應驕我，白髮渾頭少恨渠。","唯念賢哉崔大讓，可憐無事不歌魚。"]', '["燕台上客意[何如]，四五年来漸漸疎。","直道莫拋男子業，遭时還與故人书。","青云满眼應驕我，白髮渾头少恨渠。","唯念賢哉崔大讓，可怜無事不歌鱼。"]', '诗', 'shi', '', NULL, '寄浙西李判官 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f83dce-4881-4fcf-b272-d4e8e1384ee9', '寄杜子二首 一', '寄杜子二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["不識長楊事北胡，且教紅袖醉來扶。","狂風烈燄雖千尺，豁得平生俊氣無。"]', '["不識长楊事北胡，且教紅袖醉来扶。","狂风烈燄雖千尺，豁得平生俊氣無。"]', '诗', 'shi', '', NULL, '寄杜子二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1262cfeb-1081-4b6d-8996-fde8d1ef31d8', '寄杜子二首 二', '寄杜子二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["武牢關吏應相笑，箇裏年年往復來。","若問使君何處去，爲言相憶首長迴。"]', '["武牢关吏應相笑，箇裏年年往复来。","若问使君何处去，爲言相憶首长迴。"]', '诗', 'shi', '', NULL, '寄杜子二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54ec5857-33f0-42fb-8b62-dfbf80a7d77a', '盧秀才將出王屋高步名場江南相逢贈別', '盧秀才將出王屋高步名場江南相逢贈別', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["王屋山人有古文，欲攀青桂弄氛氳。","將攜健筆干明主，莫向仙壇問白雲。","馳逐寧教爭處讓，是非偏忌衆人分。","交遊話我憑君道，除却鱸魚更不聞。"]', '["王屋山人有古文，欲攀青桂弄氛氳。","將携健笔干明主，莫向仙壇问白云。","驰逐寧教爭处讓，是非偏忌衆人分。","交游話我憑君道，除却鱸鱼更不闻。"]', '诗', 'shi', '', NULL, '盧秀才將出王屋高步名場江南相逢贈別 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1acab59d-a894-46c8-94e8-0a256c34df65', '送劉三復郎中赴闕', '送劉三复郎中赴闕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["橫溪辭寂寞，金馬去追遊。","好是鴛鴦侶，正逢霄漢秋。","玉珂聲瑣瑣，錦帳夢悠悠。","微笑知今是，因風謝釣舟。"]', '["橫溪辞寂寞，金马去追游。","好是鴛鴦侶，正逢霄漢秋。","玉珂声瑣瑣，錦帳梦悠悠。","微笑知今是，因风謝釣舟。"]', '诗', 'shi', '', NULL, '送劉三復郎中赴闕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb36dbd4-9bc4-4d36-8373-962f7b63451c', '羊欄浦夜陪宴會', '羊欄浦夜陪宴會', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["戈檻營中夜未央，雨沾雲惹侍襄王。","毬來香袖依稀暖，酒凸斛心汎灩光。","紅弦高緊聲聲急，珠唱鋪圓褭褭長。"]', '["戈檻營中夜未央，雨沾云惹侍襄王。","毬来香袖依稀暖，酒凸斛心汎灩光。","紅弦高緊声声急，珠唱鋪圓褭褭长。"]', '诗', 'shi', '', NULL, '羊欄浦夜陪宴會 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be6c51dd-d0bb-4030-b9ba-eb4d4a165f76', '送杜顗赴潤州幕', '送杜顗赴潤州幕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["少年才俊赴知音，丞相門欄不覺深。","直道事人男子業，異鄉加飯弟兄心。","還須整理韋弦佩，莫獨矜誇玳瑁簪。","若去上元懷古去，謝安墳下與沈吟。"]', '["少年才俊赴知音，丞相门欄不覺深。","直道事人男子業，異乡加飯弟兄心。","還須整理韋弦佩，莫独矜誇玳瑁簪。","若去上元懷古去，謝安墳下與沈吟。"]', '诗', 'shi', '', NULL, '送杜顗赴潤州幕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037f8e37-1da9-47b7-a350-126a07b33385', '有感', '有感', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["宛溪垂柳最長枝，曾被春風盡日吹。","不堪攀折猶堪看，陌上少年來自遲。"]', '["宛溪垂柳最长枝，曾被春风尽日吹。","不堪攀折猶堪看，陌上少年来自遲。"]', '诗', 'shi', '', NULL, '有感 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6fb2d1-46dd-4732-a5de-d542f35083f0', '書懷寄盧州', '书懷寄盧州', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["謝山南畔州，風物最宜秋。","太守懸金印，佳人敞畫樓。","凝缸暗醉夕，殘月上汀州。","可惜當年鬢，朱門不得遊。"]', '["謝山南畔州，风物最宜秋。","太守懸金印，佳人敞畫楼。","凝缸暗醉夕，殘月上汀州。","可惜當年鬢，朱门不得游。"]', '诗', 'shi', '', NULL, '書懷寄盧州 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de5b7bd-c485-4b42-96bf-076a90b33e76', '賀崔大夫崔正字', '賀崔大夫崔正字', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["內舉無慚古所難，燕臺遙想拂塵冠。","登龍有路水不峻，一鴈背飛天正寒。","別夜酒餘紅燭短，映山帆滿碧霞殘。","謝公樓下潺湲響，離恨詩情添幾般。"]', '["內舉無慚古所难，燕台遙想拂塵冠。","登龙有路水不峻，一鴈背飞天正寒。","別夜酒餘紅燭短，映山帆满碧霞殘。","謝公楼下潺湲响，離恨诗情添幾般。"]', '诗', 'shi', '', NULL, '賀崔大夫崔正字 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5286e89-da5f-4544-8a12-e49f9bb2fbff', '江南送左師', '江南送左師', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["江南爲客正悲秋，更送吾師古渡頭。","惆悵不同塵土別，水雲蹤跡去悠悠。"]', '["江南爲客正悲秋，更送吾師古渡头。","惆悵不同塵土別，水云蹤跡去悠悠。"]', '诗', 'shi', '', NULL, '江南送左師 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a19bca-cdc4-4b5b-872c-07ed61be29e5', '寢夜', '寢夜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蛩唱如波咽，更深似水寒。","露華驚弊褐，燈影挂塵冠。","故國初離夢，前溪更下灘。","紛紛毫髪事，多少宦遊難。"]', '["蛩唱如波咽，更深似水寒。","露华驚弊褐，灯影挂塵冠。","故国初離梦，前溪更下灘。","紛紛毫髪事，多少宦游难。"]', '诗', 'shi', '', NULL, '寢夜 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeafd492-7902-44b5-a3dc-a18dfc350df7', '十九兄郡樓有宴病不赴', '十九兄郡楼有宴病不赴', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["十二層樓敞畫簷，連雲歌盡草纖纖。","空堂病怯階前月，燕子嗔垂一竹簾。"]', '["十二層楼敞畫簷，連云歌尽草纖纖。","空堂病怯階前月，燕子嗔垂一竹簾。"]', '诗', 'shi', '', NULL, '十九兄郡樓有宴病不赴 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd7fae5-8491-429f-aef4-2ba1b9bcbabf', '愁', '愁', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["聚散竟無形，迴腸自結成。","古今留不得，離別又潛生。","降虜將軍思，窮秋遠客情。","何人更憔悴，落第泣秦京。"]', '["聚散竟無形，迴腸自結成。","古今留不得，離別又潛生。","降虜將軍思，窮秋远客情。","何人更憔悴，落第泣秦京。"]', '诗', 'shi', '', NULL, '愁 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae02ce20-de19-4c23-9c6c-f782859a773b', '隋苑', '隋苑', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["紅霞一抹廣陵春，定子當筵睡臉新。","却笑喫虧隋煬帝，破家亡國爲誰人。"]', '["紅霞一抹廣陵春，定子當筵睡臉新。","却笑喫虧隋煬帝，破家亡国爲誰人。"]', '诗', 'shi', '', NULL, '隋苑 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3135c2ee-00f2-4225-9eba-bbf494faad73', '芭蕉', '芭蕉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["芭蕉爲雨移，故向窓前種。","憐渠點滴聲，留得歸鄉夢。","夢遠莫歸鄉，覺來一翻動。"]', '["芭蕉爲雨移，故向窓前種。","怜渠点滴声，留得归乡梦。","梦远莫归乡，覺来一翻动。"]', '诗', 'shi', '', NULL, '芭蕉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68957cfc-69fd-4e1c-b185-84c78c02d4c3', '汴人舟行荅張祜', '汴人舟行荅張祜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["千萬長河共使船，聽君詩句倍愴然。","春風野岸名花發，一道帆檣畫柳煙。"]', '["千万长河共使船，听君诗句倍愴然。","春风野岸名花發，一道帆檣畫柳煙。"]', '诗', 'shi', '', NULL, '汴人舟行荅張祜 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe3bbaf-2f8b-4bf1-a2d1-79f5a6bef477', '牧陪昭應盧郎中在江西宣州佐今吏部沈公幕罷府周歲公宰昭應牧在淮南縻職敘舊成二十二韻用以投寄', '牧陪昭應盧郎中在江西宣州佐今吏部沈公幕罷府周歲公宰昭應牧在淮南縻職敘旧成二十二韻用以投寄', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["燕鴈下揚州，涼風柳陌愁。","可憐千里夢，還是一年秋。","宛水環朱檻，章江敞碧流。","謬陪吾益友，祗事我賢侯。","印組縈光馬，鋒鋩看解牛。","井閭安樂易，冠蓋愜依投。","政簡稀開閣，功成每運籌。","送春經野塢，遲日上高樓。","玉裂歌聲斷，霞飄舞帶收。","泥情斜拂印，別臉小低頭。","日晚花枝爛，釭凝粉彩稠。","未曾孤酩酊，剩肯隻淹留。","重德俄徵寵，諸生苦宦遊。","分途之絕國，灑淚拜行輈。","聚散真漂梗，光陰急轉郵。","銘心徒歷歷，屈指盡悠悠。","君作烹鮮用，誰膺仄席求。","卷懷能憤悱，卒歲且優遊。","去矣時難遇，沽哉價莫酬。","滿枝爲鼓吹，衷甲避戈矛。","隋帝宮荒草，秦王土一丘。","相逢好大笑，除此總雲浮。"]', '["燕鴈下揚州，涼风柳陌愁。","可怜千里梦，還是一年秋。","宛水环朱檻，章江敞碧流。","謬陪吾益友，祗事我賢侯。","印組縈光马，鋒鋩看解牛。","井閭安乐易，冠蓋愜依投。","政簡稀开閣，功成每運籌。","送春經野塢，遲日上高楼。","玉裂歌声斷，霞飄舞带收。","泥情斜拂印，別臉小低头。","日晚花枝爛，釭凝粉彩稠。","未曾孤酩酊，剩肯隻淹留。","重德俄徵寵，諸生苦宦游。","分途之絕国，灑泪拜行輈。","聚散真漂梗，光陰急轉郵。","銘心徒歷歷，屈指尽悠悠。","君作烹鲜用，誰膺仄席求。","卷懷能憤悱，卒歲且優游。","去矣时难遇，沽哉價莫酬。","满枝爲鼓吹，衷甲避戈矛。","隋帝宮荒草，秦王土一丘。","相逢好大笑，除此總云浮。"]', '诗', 'shi', '', NULL, '牧陪昭應盧郎中在江西宣州佐今吏部沈公幕罷府周歲公宰昭應牧在淮南縻職敘舊成二十二韻用以投寄 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68167dff-23be-4876-a742-f75d80307d9c', '寓言', '寓言', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["暖風遲日柳初含，顧影看身又自慙。","何事明朝獨惆悵，杏花時節在江南。"]', '["暖风遲日柳初含，顧影看身又自慙。","何事明朝独惆悵，杏花时節在江南。"]', '诗', 'shi', '', NULL, '寓言 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52a599ad-0b63-410e-b38f-2109e636673f', '猿', '猿', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["月白煙青水暗流，孤猿銜恨叫中秋。","三聲欲斷疑腸斷，饒是少年今白頭。"]', '["月白煙青水暗流，孤猿銜恨叫中秋。","三声欲斷疑腸斷，饒是少年今白头。"]', '诗', 'shi', '', NULL, '猿 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc074254-7e82-4c23-b798-3609e747bec4', '懷歸', '懷归', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["塵埃終日滿牕前，水態雲容思浩然。","爭得便歸湘浦去，却持竿上釣魚船。"]', '["塵埃終日满牕前，水態云容思浩然。","爭得便归湘浦去，却持竿上釣鱼船。"]', '诗', 'shi', '', NULL, '懷歸 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a20b27d3-d785-4d73-8dd9-12b65ffd2e00', '邊上晚秋', '邊上晚秋', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["黑山南面更無州，馬放平沙夜不收。","風送孤城臨晚角，一聲聲入客心愁。"]', '["黑山南面更無州，马放平沙夜不收。","风送孤城臨晚角，一声声入客心愁。"]', '诗', 'shi', '', NULL, '邊上晚秋 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e28d87d-576b-4af0-8a43-63d28c15f811', '傷友人悼吹簫妓', '傷友人悼吹簫妓', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["玉簫聲斷沒流年，滿目春愁隴樹煙。","豔質已隨雲雨散，鳳樓空鎖月明天。"]', '["玉簫声斷沒流年，满目春愁隴樹煙。","豔質已隨云雨散，鳳楼空鎖月明天。"]', '诗', 'shi', '', NULL, '傷友人悼吹簫妓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308eb1a8-b305-4809-ae8b-4a13cb09bff8', '訪許顏', '訪許顏', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["門近寒溪牕近山，枕山流水日潺潺。","長嫌世上浮雲客，老向塵中不解顏。"]', '["门近寒溪牕近山，枕山流水日潺潺。","长嫌世上浮云客，老向塵中不解顏。"]', '诗', 'shi', '', NULL, '訪許顏 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fdb35a-5a08-41ba-b6be-996087bf2843', '春日古道傍作', '春日古道傍作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["萬古榮華旦暮齊，樓臺春盡草萋萋。","君看陌上何人墓，旋化紅塵送馬蹏。"]', '["万古榮华旦暮齊，楼台春尽草萋萋。","君看陌上何人墓，旋化紅塵送马蹏。"]', '诗', 'shi', '', NULL, '春日古道傍作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('304aa711-54e3-4550-b2ab-ec17b1e24a76', '青塚', '青塚', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["青塚前頭隴水流，燕支山上暮雲秋。","蛾眉一墜窮泉路，夜夜孤魂月下愁。"]', '["青塚前头隴水流，燕支山上暮云秋。","蛾眉一墜窮泉路，夜夜孤魂月下愁。"]', '诗', 'shi', '', NULL, '青塚 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb217f10-edb0-45b7-8e49-47585cc6c8b9', '大夢上人自廬峰回', '大梦上人自廬峰回', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["行脚尋常到寺稀，一枝藜杖一禪衣。","開門滿院空秋色，新向廬峰過夏歸。"]', '["行脚尋常到寺稀，一枝藜杖一禪衣。","开门满院空秋色，新向廬峰過夏归。"]', '诗', 'shi', '', NULL, '大夢上人自廬峰回 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b459de7-7741-4711-9302-d65394318cc5', '洛中二首 一', '洛中二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["柳動晴風拂路塵，年年宮闕鎖濃春。","一從翠輦無巡幸，老却蛾眉幾許人。"]', '["柳动晴风拂路塵，年年宮闕鎖濃春。","一從翠輦無巡幸，老却蛾眉幾許人。"]', '诗', 'shi', '', NULL, '洛中二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a39a296-cc21-44b4-84c9-a660196a4e61', '洛中二首 二', '洛中二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["風吹柳帶搖晴綠，蝶遶花枝戀暖香。","多把芳菲泛春酒，直教愁色對愁腸。"]', '["风吹柳带搖晴綠，蝶遶花枝戀暖香。","多把芳菲泛春酒，直教愁色对愁腸。"]', '诗', 'shi', '', NULL, '洛中二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f464abe-9a19-49a5-b026-450807a7661f', '邊上聞笳三首 一', '邊上闻笳三首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["何處吹笳薄暮天，塞垣高鳥沒狼煙。","遊人一聽頭堪白，蘇武爭禁十九年。"]', '["何处吹笳薄暮天，塞垣高鸟沒狼煙。","游人一听头堪白，蘇武爭禁十九年。"]', '诗', 'shi', '', NULL, '邊上聞笳三首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4350de2f-0914-4bdb-b9ce-713bcd97e2f4', '邊上聞笳三首 二', '邊上闻笳三首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["海路無塵邊草新，榮枯不見綠楊春。","白沙日暮愁雲起，獨感離鄉萬里人。"]', '["海路無塵邊草新，榮枯不见綠楊春。","白沙日暮愁云起，独感離乡万里人。"]', '诗', 'shi', '', NULL, '邊上聞笳三首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1927803a-61ed-4f62-a93c-5f498b286c5a', '邊上聞笳三首 三', '邊上闻笳三首 三', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["胡雛吹笛上高臺，寒雁驚飛去不回。","盡日春風吹不散，只應分付客愁來。"]', '["胡雛吹笛上高台，寒雁驚飞去不回。","尽日春风吹不散，只應分付客愁来。"]', '诗', 'shi', '', NULL, '邊上聞笳三首 三 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0f6ffa-7149-40b9-a8e3-a7579d77259d', '春日寄許渾先輩', '春日寄許渾先輩', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["薊北雁初去，湘南春又歸。","水流滄海急，人到白頭稀。","塞路盡何處，我愁當落暉。","終須接鴛鷺，霄漢共高飛。"]', '["薊北雁初去，湘南春又归。","水流滄海急，人到白头稀。","塞路尽何处，我愁當落暉。","終須接鴛鷺，霄漢共高飞。"]', '诗', 'shi', '', NULL, '春日寄許渾先輩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b5a42d1-285e-4955-b55a-1917f61167b2', '經闔閭城', '經闔閭城', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["遺蹤委衰草，行客思悠悠。","昔日人何處，終年水自流。","孤煙邨戌遠，亂雨海門秋。","吟罷獨歸去，煙雲盡慘愁。"]', '["遺蹤委衰草，行客思悠悠。","昔日人何处，終年水自流。","孤煙邨戌远，亂雨海门秋。","吟罷独归去，煙云尽慘愁。"]', '诗', 'shi', '', NULL, '經闔閭城 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5120bb-738e-4b1f-b212-869ed20e2c48', '幷州道中', '幷州道中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["行役我方倦，苦吟誰復聞。","戌樓春帶雪，邊角暮吹雲。","極目無人迹，回頭送鴈羣。","如何遣公子，高臥醉醺醺。"]', '["行役我方倦，苦吟誰复闻。","戌楼春带雪，邊角暮吹云。","極目無人迹，回头送鴈羣。","如何遣公子，高臥醉醺醺。"]', '诗', 'shi', '', NULL, '幷州道中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58912283-2b9a-42fe-be12-744cc183543f', '別懷', '別懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["相別徒成泣，經過總是空。","勞生慣離別，夜夢苦西東。","去路三湘浪，歸程一片風。","他年寄消息，書在鯉魚中。"]', '["相別徒成泣，經過總是空。","勞生慣離別，夜梦苦西东。","去路三湘浪，归程一片风。","他年寄消息，书在鯉鱼中。"]', '诗', 'shi', '', NULL, '別懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dae0963-7101-4cf3-a045-1c0607adc419', '漁父', '漁父', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["白髮滄浪上，全忘是與非。","秋潭垂釣去，夜月叩船歸。","煙影侵蘆岸，潮痕在竹扉。","終年狎鷗鳥，來去且無機。"]', '["白髮滄浪上，全忘是與非。","秋潭垂釣去，夜月叩船归。","煙影侵蘆岸，潮痕在竹扉。","終年狎鷗鸟，来去且無機。"]', '诗', 'shi', '', NULL, '漁父 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8aedfad-1722-4af7-8212-a5aec92fd87a', '秋夢', '秋梦', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["寒空動高吹，月色滿清砧。","殘夢夜魂斷，美人邊思深。","孤鴻秋出塞，一葉暗辭林。","又寄征衣去，迢迢天外心。"]', '["寒空动高吹，月色满清砧。","殘梦夜魂斷，美人邊思深。","孤鴻秋出塞，一葉暗辞林。","又寄征衣去，迢迢天外心。"]', '诗', 'shi', '', NULL, '秋夢 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408b44e4-92fd-41f5-a073-6559f58e51e1', '早秋客舍', '早秋客舍', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["風吹一片葉，萬物已驚秋。","獨夜他鄉淚，年年爲客愁。","別離何處盡，搖落幾時休。","不及磻溪叟，身閑長自由。"]', '["风吹一片葉，万物已驚秋。","独夜他乡泪，年年爲客愁。","別離何处尽，搖落幾时休。","不及磻溪叟，身闲长自由。"]', '诗', 'shi', '', NULL, '早秋客舍 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e57dc35-56b8-4e3d-ab51-25d6c4bd1fab', '逢故人', '逢故人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["故交相見稀，相見倍依依。","塵路事不盡，雲巖閑好歸。","投人銷壯志，徇俗變真機。","又落他鄉淚，風前一滿衣。"]', '["故交相见稀，相见倍依依。","塵路事不尽，云巖闲好归。","投人銷壯志，徇俗变真機。","又落他乡泪，风前一满衣。"]', '诗', 'shi', '', NULL, '逢故人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51ef42d5-7ee1-4f03-abd0-082156116f1c', '秋晚江上遣懷', '秋晚江上遣懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["孤舟天際外，去路望中賒。","貧病遠行客，夢魂多在家。","蟬吟秋色樹，鴉噪夕陽沙。","不擬徹雙鬢，他方擲歲華。"]', '["孤舟天際外，去路望中賒。","貧病远行客，梦魂多在家。","蟬吟秋色樹，鴉噪夕陽沙。","不擬徹雙鬢，他方擲歲华。"]', '诗', 'shi', '', NULL, '秋晚江上遣懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8b805ad-170d-4d5b-a213-7fa8a9267ef3', '長安夜月', '长安夜月', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["寒光垂靜夜，皓彩滿重城。","萬國盡分照，誰家無此明。","古槐疎影薄，仙桂動秋聲。","獨有長門裏，蛾眉對曉晴。"]', '["寒光垂静夜，皓彩满重城。","万国尽分照，誰家無此明。","古槐疎影薄，仙桂动秋声。","独有长门裏，蛾眉对晓晴。"]', '诗', 'shi', '', NULL, '長安夜月 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28433d8d-5936-45da-ade8-19c96e9b7882', '雲', '云', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["東西那有礙，出處豈虛心。","曉入洞庭闊，暮歸巫峽深。","渡江隨鳥影，擁樹隔猿吟。","莫隱高唐去，枯苗待作霖。"]', '["东西那有礙，出处豈虛心。","晓入洞庭闊，暮归巫峽深。","渡江隨鸟影，擁樹隔猿吟。","莫隐高唐去，枯苗待作霖。"]', '诗', 'shi', '', NULL, '雲 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524e074f-6a93-407d-860f-6aedbcafb736', '春懷', '春懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["年光何太急，倏忽又青春。","明月誰爲主，江山暗換人。","鶯花潛運老，榮樂漸成塵。","遙憶朱門柳，別離應更頻。"]', '["年光何太急，倏忽又青春。","明月誰爲主，江山暗換人。","鶯花潛運老，榮乐漸成塵。","遙憶朱门柳，別離應更頻。"]', '诗', 'shi', '', NULL, '春懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916b8772-417b-4c41-8444-cc5cf7653df1', '逢故人', '逢故人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["年年不相見，相見却成悲。","教我淚如霰，嗟君髪似絲。","正傷攜手處，況值落花時。","莫惜今宵醉，人間忽忽期。"]', '["年年不相见，相见却成悲。","教我泪如霰，嗟君髪似絲。","正傷携手处，況值落花时。","莫惜今宵醉，人间忽忽期。"]', '诗', 'shi', '', NULL, '逢故人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3e549f-176c-48b3-bf3e-c713f218bea3', '閑題', '闲題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["男兒所在即爲家，百鎰黃金一朵花。","借問春風何處好，綠楊深巷馬頭斜。"]', '["男兒所在即爲家，百鎰黄金一朵花。","借问春风何处好，綠楊深巷马头斜。"]', '诗', 'shi', '', NULL, '閑題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80159919-0b66-4956-a563-ef9bcf6a05c0', '金谷園', '金谷园', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["繁華事散逐香塵，流水無情草自春。","日暮東風怨啼鳥，落花猶似墮樓人。"]', '["繁华事散逐香塵，流水無情草自春。","日暮东风怨啼鸟，落花猶似墮楼人。"]', '诗', 'shi', '', NULL, '金谷園 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2029f78f-5712-4d96-ac73-6400df8b6f61', '重登科', '重登科', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["星漢離宮月出輪，滿街含笑綺羅春。","花前每被青蛾問，何事重來只一人。"]', '["星漢離宮月出輪，满街含笑綺羅春。","花前每被青蛾问，何事重来只一人。"]', '诗', 'shi', '', NULL, '重登科 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28799a12-e0c3-48ef-a28a-5524333f8f4a', '遊邊', '游邊', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["黃沙連海路無塵，邊草長枯不見春。","日暮拂雲堆下過，馬前逢著射鵰人。"]', '["黄沙連海路無塵，邊草长枯不见春。","日暮拂云堆下過，马前逢著射鵰人。"]', '诗', 'shi', '', NULL, '遊邊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092a87b0-7174-4349-aa8e-66e55664ce16', '將赴池州道中作', '將赴池州道中作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["青陽雲水去年尋，黃絹歌詩出翰林。","投轄暫停留酒客，絳帷斜繫滿松陰。","妖人笑我不相問，道者應知歸路心。","南去南來盡鄉國，月明秋水只沈沈。"]', '["青陽云水去年尋，黄絹歌诗出翰林。","投轄暫停留酒客，絳帷斜繫满松陰。","妖人笑我不相问，道者應知归路心。","南去南来尽乡国，月明秋水只沈沈。"]', '诗', 'shi', '', NULL, '將赴池州道中作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c96d8cbe-15b2-4741-8223-cdf24c7d0b3c', '隋宮春', '隋宮春', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["龍舟東下事成空，蔓草萋萋滿故宮。","亡國亡家爲顏色，露桃猶自恨春風。"]', '["龙舟东下事成空，蔓草萋萋满故宮。","亡国亡家爲顏色，露桃猶自恨春风。"]', '诗', 'shi', '', NULL, '隋宮春 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18046e74-6340-4797-808e-aaf0a557caee', '蠻中醉', '蠻中醉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["瘴塞蠻江入洞流，人家多在竹棚頭。","青山海上無城郭，唯見松牌出象州。"]', '["瘴塞蠻江入洞流，人家多在竹棚头。","青山海上無城郭，唯见松牌出象州。"]', '诗', 'shi', '', NULL, '蠻中醉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc1f4baf-4d3d-4694-8e1e-2e6a3c06f737', '寓題', '寓題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["把酒直須判酩酊，逢花莫惜暫淹留。","假如三萬六千日，半是悲哀半是愁。"]', '["把酒直須判酩酊，逢花莫惜暫淹留。","假如三万六千日，半是悲哀半是愁。"]', '诗', 'shi', '', NULL, '寓題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fc932b9-69e4-4562-b3b9-bf4bfeae9e54', '送趙十二赴舉', '送趙十二赴舉', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["省事却因多事力，無心翻似有心來。","秋風郡閣殘花在，別後何人更一杯。"]', '["省事却因多事力，無心翻似有心来。","秋风郡閣殘花在，別後何人更一杯。"]', '诗', 'shi', '', NULL, '送趙十二赴舉 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62506da7-05c5-4c55-878a-0b86b2ab50fe', '偶呈鄭先輩', '偶呈鄭先輩', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["不語亭亭儼薄粧，畫裙雙鳳鬱金香。","西京才子旁看取，何似喬家郍窈娘。"]', '["不語亭亭儼薄粧，畫裙雙鳳鬱金香。","西京才子旁看取，何似喬家郍窈娘。"]', '诗', 'shi', '', NULL, '偶呈鄭先輩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93b8de9-bb98-4e94-ac57-56fb66930975', '子規', '子規', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蜀地曾聞子規鳥，宣城又見杜鵑花。","一呌一回腸一斷，三春三月憶三巴。"]', '["蜀地曾闻子規鸟，宣城又见杜鵑花。","一呌一回腸一斷，三春三月憶三巴。"]', '诗', 'shi', '', NULL, '子規 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d95e279-c674-4b69-a5e9-1b8585ff0f21', '江樓', '江楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["獨酌芳春酒，登樓已半醺。","誰驚一行雁，衝斷過江雲。"]', '["独酌芳春酒，登楼已半醺。","誰驚一行雁，衝斷過江云。"]', '诗', 'shi', '', NULL, '江樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('200fe9fa-0221-4123-86de-4d63ce9d3daf', '旅宿', '旅宿', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["旅館無良伴，凝情自悄然。","寒燈思舊事，斷鴈警愁眠。","遠夢歸侵曉，家書到隔年。","湘江好煙月，門繫釣魚船。"]', '["旅館無良伴，凝情自悄然。","寒灯思旧事，斷鴈警愁眠。","远梦归侵晓，家书到隔年。","湘江好煙月，门繫釣鱼船。"]', '诗', 'shi', '', NULL, '旅宿 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee85588c-0534-4102-8f5c-e305f5f4eec0', '杜鵑', '杜鵑', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["杜宇竟何冤，年年呌蜀門。","至今銜積恨，終古弔殘魂。","芳草迷腸結，紅花染血痕。","山川盡春色，嗚咽復誰論。"]', '["杜宇竟何冤，年年呌蜀门。","至今銜積恨，終古弔殘魂。","芳草迷腸結，紅花染血痕。","山川尽春色，嗚咽复誰論。"]', '诗', 'shi', '', NULL, '杜鵑 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b1c163-b708-42d3-99af-a02f36eac49d', '聞蟬', '闻蟬', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["火雲初似滅，曉角欲微清。","故國行千里，新蟬忽數聲。","時行仍髣髴，度日更分明。","不敢頻傾耳，唯憂白髮生。"]', '["火云初似滅，晓角欲微清。","故国行千里，新蟬忽數声。","时行仍髣髴，度日更分明。","不敢頻傾耳，唯憂白髮生。"]', '诗', 'shi', '', NULL, '聞蟬 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde49e9e-6a1b-4410-9be7-00f366a05d55', '送友人', '送友人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["十載名兼利，人皆與命爭。","青春留不住，白髮自然生。","夜雨滴鄉思，秋風從別情。","都門五十里，馳馬逐雞聲。"]', '["十載名兼利，人皆與命爭。","青春留不住，白髮自然生。","夜雨滴乡思，秋风從別情。","都门五十里，驰马逐雞声。"]', '诗', 'shi', '', NULL, '送友人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30040ee2-58a0-4ff6-be84-c8c55f440a88', '旅情', '旅情', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["窗虛枕簟涼，寢倦憶瀟湘。","山色幾時老，人心終日忙。","松風半夜雨，簾月滿堂霜。","匹馬好歸去，江頭橘正香。"]', '["窗虛枕簟涼，寢倦憶瀟湘。","山色幾时老，人心終日忙。","松风半夜雨，簾月满堂霜。","匹马好归去，江头橘正香。"]', '诗', 'shi', '', NULL, '旅情 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71cf556f-c9b9-48dc-b8db-cd0e71489eab', '曉望', '晓望', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["獨起望山色，水雞鳴蓼洲。","房星隨月曉，楚木向雲秋。","曲渚疑江盡，平沙似浪浮。","秦原在何處，澤國碧悠悠。"]', '["独起望山色，水雞鳴蓼洲。","房星隨月晓，楚木向云秋。","曲渚疑江尽，平沙似浪浮。","秦原在何处，澤国碧悠悠。"]', '诗', 'shi', '', NULL, '曉望 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f6dd3b-adc6-4b9e-9ef0-64fbb119926d', '貽友人', '貽友人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["自是東西客，逢人又送人。","不應相見老，秖是別離頻。","度日還知暮，平生未識春。","儻無遷谷分，歸去養天真。"]', '["自是东西客，逢人又送人。","不應相见老，秖是別離頻。","度日還知暮，平生未識春。","儻無遷谷分，归去養天真。"]', '诗', 'shi', '', NULL, '貽友人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97a85c63-017e-4e4f-afbb-7584f6d9f977', '書事', '书事', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["自笑走紅塵，流年舊復新。","東風半夜雨，南國萬家春。","失計拋魚艇，何門化涸鱗。","是誰添歲月，老却暗投人。"]', '["自笑走紅塵，流年旧复新。","东风半夜雨，南国万家春。","失計拋鱼艇，何门化涸鱗。","是誰添歲月，老却暗投人。"]', '诗', 'shi', '', NULL, '書事 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b531a90-ba92-4f64-97e5-e7a353f14f65', '別鶴', '別鹤', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["分飛共所從，六翮勢催風。","聲斷碧雲外，影孤明月中。","青田歸路遠，丹桂舊巢空。","矯翼知何處，天涯不可窮。"]', '["分飞共所從，六翮勢催风。","声斷碧云外，影孤明月中。","青田归路远，丹桂旧巢空。","矯翼知何处，天涯不可窮。"]', '诗', 'shi', '', NULL, '別鶴 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa8fae9-ffb6-4bce-82ce-6e07262b64dc', '晚泊', '晚泊', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["帆濕去悠悠，停橈宿渡頭。","亂煙迷野岸，獨鳥出中流。","[篷]雨延鄉夢，江風阻暮秋。","儻無身外事，甘老向扁舟。"]', '["帆濕去悠悠，停橈宿渡头。","亂煙迷野岸，独鸟出中流。","[篷]雨延乡梦，江风阻暮秋。","儻無身外事，甘老向扁舟。"]', '诗', 'shi', '', NULL, '晚泊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caaca622-c956-41cc-8332-ed41f24818a7', '山寺', '山寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["峭壁引行徑，截溪開石門。","泉飛濺虛檻，雲起漲河軒。","隔水看來路，疎籬見定猿。","未閑難久住，歸去復何言。"]', '["峭壁引行徑，截溪开石门。","泉飞濺虛檻，云起漲河軒。","隔水看来路，疎籬见定猿。","未闲难久住，归去复何言。"]', '诗', 'shi', '', NULL, '山寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8712c56-38dc-490d-81ce-03dbb8fac1a1', '早行', '早行', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["垂鞭信馬行，數里未雞鳴。","林下帶殘夢，葉飛時忽驚。","霜凝孤鶴逈，月曉遠山橫。","僮僕休辭險，時平路復平。"]', '["垂鞭信马行，數里未雞鳴。","林下带殘梦，葉飞时忽驚。","霜凝孤鹤逈，月晓远山橫。","僮僕休辞險，时平路复平。"]', '诗', 'shi', '', NULL, '早行 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6de81737-7d03-4b65-87cb-fc3a286825b8', '秋日偶題', '秋日偶題', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["荷花兼柳葉，彼此不勝秋。","玉露滴初泣，金風吹更愁。","綠眉甘棄墜，紅臉恨飄流。","歎息是遊子，少年還白頭。"]', '["荷花兼柳葉，彼此不勝秋。","玉露滴初泣，金风吹更愁。","綠眉甘棄墜，紅臉恨飄流。","歎息是游子，少年還白头。"]', '诗', 'shi', '', NULL, '秋日偶題 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f5d1c3a-0f7a-4acf-8a5b-0a90f5eda796', '憶歸', '憶归', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["新城非故里，終日想柴扃。","興罷花還落，愁來酒欲醒。","何人初髪白，幾處亂山青。","遠憶湘江上，漁歌對月聽。"]', '["新城非故里，終日想柴扃。","兴罷花還落，愁来酒欲醒。","何人初髪白，幾处亂山青。","远憶湘江上，漁歌对月听。"]', '诗', 'shi', '', NULL, '憶歸 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15e15e7-93ac-4923-bf7b-d5e06a4104a2', '偶見', '偶见', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["朔風高緊掠河樓，白鼻騧郎白罽裘。","有箇當壚明似月，馬鞭斜揖笑回頭。"]', '["朔风高緊掠河楼，白鼻騧郎白罽裘。","有箇當壚明似月，马鞭斜揖笑回头。"]', '诗', 'shi', '', NULL, '偶見 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f484d9-6b45-4920-9497-7f9c1e94c4f1', '醉倒', '醉倒', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["日晴空樂下仙雲，俱在涼亭送使君。","莫辭一盞即相請，還是三年更不聞。"]', '["日晴空乐下仙云，俱在涼亭送使君。","莫辞一盞即相請，還是三年更不闻。"]', '诗', 'shi', '', NULL, '醉倒 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ea719c-de54-450a-a810-ec7e136445f7', '酬許十三秀才兼依來韻', '酬許十三秀才兼依来韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["多爲裁詩步竹軒，有時凝思過朝昏。","篇成敢道懷金璞，吟苦唯應似嶺猿。","迷興每慙花月夕，寄愁長在別離魂。","憑君把卷侵寒燭，麗句時傳畫戟門。"]', '["多爲裁诗步竹軒，有时凝思過朝昏。","篇成敢道懷金璞，吟苦唯應似嶺猿。","迷兴每慙花月夕，寄愁长在別離魂。","憑君把卷侵寒燭，丽句时傳畫戟门。"]', '诗', 'shi', '', NULL, '酬許十三秀才兼依來韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c486955-3227-4d91-a098-df46818ca5c8', '後池泛舟送王十秀才', '後池泛舟送王十秀才', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["城日晚悠悠，弦歌在碧流。","夕風飄度曲，煙嶼隱行舟。","問拍擬新令，憐香占彩毬。","當筵雖一醉，寧復緩離愁。"]', '["城日晚悠悠，弦歌在碧流。","夕风飄度曲，煙嶼隐行舟。","问拍擬新令，怜香占彩毬。","當筵雖一醉，寧复緩離愁。"]', '诗', 'shi', '', NULL, '後池泛舟送王十秀才 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41e6abd8-7f86-47c8-8864-80194d5f471e', '書情', '书情', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["誰家洛浦神，十四五來人。","媚髪輕垂額，香衫軟著身。","摘蓮紅袖濕，窺淥翠蛾頻。","飛鵲徒來往，平陽公主親。"]', '["誰家洛浦神，十四五来人。","媚髪轻垂額，香衫軟著身。","摘蓮紅袖濕，窺淥翠蛾頻。","飞鵲徒来往，平陽公主親。"]', '诗', 'shi', '', NULL, '書情 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9be387-45c4-434b-b095-169df99f2a87', '兵部尚書席上作', '兵部尚书席上作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["華堂今日綺筵開，誰喚分司御史來。","偶發狂言驚滿坐，三重粉面一時回。"]', '["华堂今日綺筵开，誰喚分司御史来。","偶發狂言驚满坐，三重粉面一时回。"]', '诗', 'shi', '', NULL, '兵部尚書席上作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91cb2639-7f72-4881-98fc-ab984c5e1dec', '驌驦坂', '驌驦坂', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["荆州一萬里，不如蒯易度。","仰首望飛鳴，伊人何異趣。"]', '["荆州一万里，不如蒯易度。","仰首望飞鳴，伊人何異趣。"]', '诗', 'shi', '', NULL, '驌驦坂 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8310ffab-fa9e-473b-b587-7f192954d94d', '冬日五湖館水亭懷別', '冬日五湖館水亭懷別', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蘆荻花多觸處飛，獨凭虛檻雨微微。","寒林葉落鳥巢出，古渡風高漁艇稀。","雲抱四山終日在，草荒三徑幾時歸。","江城向晚西流急，無限鄉心聞擣衣。"]', '["蘆荻花多觸处飞，独凭虛檻雨微微。","寒林葉落鸟巢出，古渡风高漁艇稀。","云抱四山終日在，草荒三徑幾时归。","江城向晚西流急，無限乡心闻擣衣。"]', '诗', 'shi', '', NULL, '冬日五湖館水亭懷別 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79cbc5bd-e582-45c9-81dc-41faae227083', '不寢', '不寢', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["到曉不成夢，思量堪白頭。","多無百年命，長有萬般愁。","世路應難盡，營生卒未休。","莫言名與利，名利是身讐。"]', '["到晓不成梦，思量堪白头。","多無百年命，长有万般愁。","世路應难尽，營生卒未休。","莫言名與利，名利是身讐。"]', '诗', 'shi', '', NULL, '不寢 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c798165-fe62-41c4-aaff-9d53cca79408', '泊松江', '泊松江', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["清露白雲明月天，與君齊櫂木蘭船。","南湖風雨一相失，夜泊橫塘心渺然。"]', '["清露白云明月天，與君齊櫂木蘭船。","南湖风雨一相失，夜泊橫塘心渺然。"]', '诗', 'shi', '', NULL, '泊松江 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28f10c86-ee73-4720-8e9c-0b39561a8578', '題水西寺', '題水西寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["三日去還住，一生焉再遊。","含情碧溪水，重上粲公樓。"]', '["三日去還住，一生焉再游。","含情碧溪水，重上粲公楼。"]', '诗', 'shi', '', NULL, '題水西寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487f4f4a-f3ef-46fb-98cf-4454f7135e85', '贈別宣州崔羣相公', '贈別宣州崔羣相公', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["衰散相逢洛水邊，却思同在紫薇天。","盡將舟楫板橋去，早晚歸來更濟川。"]', '["衰散相逢洛水邊，却思同在紫薇天。","尽將舟楫板橋去，早晚归来更濟川。"]', '诗', 'shi', '', NULL, '贈別宣州崔羣相公 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4155273-6b2c-477f-9ddc-08722def1c6a', '聞開江相國宋下世二首 一', '闻开江相国宋下世二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["權門陰進奪移才，驛騎如星墮峽來。","晁氏有恩忠作禍，賈生無罪直爲災。","貞魂誤向崇山沒，冤氣疑從湘水回。","畢竟成功何處是，五湖雲月一帆開。"]', '["權门陰進奪移才，驛騎如星墮峽来。","晁氏有恩忠作禍，賈生無罪直爲災。","貞魂誤向崇山沒，冤氣疑從湘水回。","畢竟成功何处是，五湖云月一帆开。"]', '诗', 'shi', '', NULL, '聞開江相國宋下世二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfc79005-7c71-4365-bbe6-6ff9b4a7f44a', '聞開江相國宋下世二首 二', '闻开江相国宋下世二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["月落清湘棹不喧，玉杯瑤瑟奠蘋蘩。","誰令力制乘軒鶴，自取機沈在檻猿。","位極乾坤三事貴，謗興華夏一夫冤。","宵衣旰食明天子，日伏青蒲不爲言。"]', '["月落清湘棹不喧，玉杯瑤瑟奠蘋蘩。","誰令力制乘軒鹤，自取機沈在檻猿。","位極乾坤三事貴，謗兴华夏一夫冤。","宵衣旰食明天子，日伏青蒲不爲言。"]', '诗', 'shi', '', NULL, '聞開江相國宋下世二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efa218b-1573-4c81-91fa-24b9c998caea', '出關', '出关', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["朝纓初解佐江濆，麋鹿心知自有羣。","漢囿獵稀慵獻賦，楚山耕早任移文。","臥歸漁浦月連海，行望鳳城花隔雲。","關吏不須迎馬笑，去時無意學終軍。"]', '["朝纓初解佐江濆，麋鹿心知自有羣。","漢囿獵稀慵獻賦，楚山耕早任移文。","臥归漁浦月連海，行望鳳城花隔云。","关吏不須迎马笑，去时無意学終軍。"]', '诗', 'shi', '', NULL, '出關 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc003c1-d2d3-4708-b014-7048cda8846b', '暝投雲智寺渡溪不得却取沿江路往', '暝投云智寺渡溪不得却取沿江路往', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雙嵓瀉一川，回馬斷橋前。","古廟陰風地，寒鐘暮雨天。","沙虛留虎跡，水滑帶龍涎。","却下臨江路，潮深無渡船。"]', '["雙嵓瀉一川，回马斷橋前。","古廟陰风地，寒鐘暮雨天。","沙虛留虎跡，水滑带龙涎。","却下臨江路，潮深無渡船。"]', '诗', 'shi', '', NULL, '暝投雲智寺渡溪不得却取沿江路往 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3af260ca-3d83-46a3-b1d3-7f8edac1789e', '宣城贈蕭兵曹', '宣城贈蕭兵曹', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["桂檝謫湘渚，三年波上春。","舟寒句溪雪，衣故洛城塵。","客道恥搖尾，皇恩寬犯鱗。","花時去國遠，月夕上樓頻。","賒酒不辭病，傭書非爲貧。","行吟值漁父，坐隱對樵人。","紫陌罷雙轍，碧潭窮一綸。","高秋更南去，煙水是通津。"]', '["桂檝謫湘渚，三年波上春。","舟寒句溪雪，衣故洛城塵。","客道恥搖尾，皇恩寬犯鱗。","花时去国远，月夕上楼頻。","賒酒不辞病，傭书非爲貧。","行吟值漁父，坐隐对樵人。","紫陌罷雙轍，碧潭窮一綸。","高秋更南去，煙水是通津。"]', '诗', 'shi', '', NULL, '宣城贈蕭兵曹 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988f49d0-3ae0-4a41-a673-0817a1ea97e0', '過鮑溶宅有感', '過鲍溶宅有感', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["寥落故人宅，重來身已亡。","古苔殘墨沼，深竹舊書堂。","秋色池館靜，雨聲雲木涼。","無因展交道，日暮倍心傷。"]', '["寥落故人宅，重来身已亡。","古苔殘墨沼，深竹旧书堂。","秋色池館静，雨声云木涼。","無因展交道，日暮倍心傷。"]', '诗', 'shi', '', NULL, '過鮑溶宅有感 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584fe075-d3b6-47c4-a182-0c169ca14b5a', '寄兄弟', '寄兄弟', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["江城紅葉盡，旅思倍淒涼。","孤夢家山遠，獨眠秋夜長。","道存空倚命，身賤未歸鄉。","南望仍垂淚，天邊鴈一行。"]', '["江城紅葉尽，旅思倍淒涼。","孤梦家山远，独眠秋夜长。","道存空倚命，身賤未归乡。","南望仍垂泪，天邊鴈一行。"]', '诗', 'shi', '', NULL, '寄兄弟 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e982c7d4-77e3-47d1-9005-8916b7347c70', '秋日', '秋日', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["有計自安業，秋風罷遠吟。","買山惟種竹，對客更彈琴。","煙起藥厨晚，杵聲松院深。","閑眠得真性，惆悵舊時心。"]', '["有計自安業，秋风罷远吟。","買山惟種竹，对客更彈琴。","煙起藥厨晚，杵声松院深。","闲眠得真性，惆悵旧时心。"]', '诗', 'shi', '', NULL, '秋日 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4952145-72c2-4da3-b777-a9d307cac272', '卜居招書侶', '卜居招书侶', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["憶昨未知道，臨川每羨魚。","世途行處見，人事病來疎。","微雨秋栽竹，孤燈夜讀書。","憐君亦同志，晚歲傍山居。"]', '["憶昨未知道，臨川每羨鱼。","世途行处见，人事病来疎。","微雨秋栽竹，孤灯夜读书。","怜君亦同志，晚歲傍山居。"]', '诗', 'shi', '', NULL, '卜居招書侶 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403f8c59-dcd9-4a22-82a1-c5c1230b62b0', '西山草堂', '西山草堂', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["何處人事少，西峰舊草堂。","曬書秋日晚，洗藥石泉香。","後嶺有微雨，北牕生曉涼。","徒勞問歸路，峰疊遶家鄉。"]', '["何处人事少，西峰旧草堂。","曬书秋日晚，洗藥石泉香。","後嶺有微雨，北牕生晓涼。","徒勞问归路，峰叠遶家乡。"]', '诗', 'shi', '', NULL, '西山草堂 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fef4c46-59d0-4a27-823e-8869262b093e', '貽隱者', '貽隐者', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["回報隱居山，莫憂山興闌。","求人顏色盡，知道性情寬。","信譜彈琴誤，緣崖斸藥難。","東臯亦自給，殊愧遠相安。"]', '["回報隐居山，莫憂山兴闌。","求人顏色尽，知道性情寬。","信譜彈琴誤，緣崖斸藥难。","东臯亦自給，殊愧远相安。"]', '诗', 'shi', '', NULL, '貽隱者 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac072c2-87a1-4963-bcea-5c38d28b72ab', '石池', '石池', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["通竹引泉脉，泓澄深石盆。","驚魚翻藻葉，浴鳥上松根。","殘月留山影，高風耗水痕。","誰家洗秋藥，來往自開門。"]', '["通竹引泉脉，泓澄深石盆。","驚鱼翻藻葉，浴鸟上松根。","殘月留山影，高风耗水痕。","誰家洗秋藥，来往自开门。"]', '诗', 'shi', '', NULL, '石池 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2171cf-cccb-4a93-93c0-f48fcbcfd026', '送蘇協律從事振武', '送蘇協律從事振武', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["琴尊詩思勞，更欲學龍韜。","王粲暫投筆，呂虔初佩刀。","夜吟關月苦，秋望塞雲高。","去去從軍樂，鵰飛岱馬豪。"]', '["琴尊诗思勞，更欲学龙韜。","王粲暫投笔，呂虔初佩刀。","夜吟关月苦，秋望塞云高。","去去從軍乐，鵰飞岱马豪。"]', '诗', 'shi', '', NULL, '送蘇協律從事振武 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cad612b5-a64b-4663-9313-84c7152468cc', '懷政禪師院', '懷政禪師院', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["山齋路幾層，敗衲學真乘。","寒暑移雙樹，光陰盡一燈。","風飄高竹雪，泉漲小池冰。","莫訝頻來此，修身欲到僧。"]', '["山斋路幾層，敗衲学真乘。","寒暑移雙樹，光陰尽一灯。","风飄高竹雪，泉漲小池冰。","莫訝頻来此，修身欲到僧。"]', '诗', 'shi', '', NULL, '懷政禪師院 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a3c877-5904-43d5-8248-7327151eb464', '送荔浦蔣明府赴任', '送荔浦蔣明府赴任', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["路長春欲盡，歌怨酒多酣。","白社蓮塘北，青袍桂水南。","驛行盤鳥道，船宿避龍潭。","真得詩人趣，煙霞處處諳。"]', '["路长春欲尽，歌怨酒多酣。","白社蓮塘北，青袍桂水南。","驛行盤鸟道，船宿避龙潭。","真得诗人趣，煙霞处处諳。"]', '诗', 'shi', '', NULL, '送荔浦蔣明府赴任 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b859bef-0c17-45ab-845d-9875dd865677', '秋夕有懷', '秋夕有懷', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["念遠坐西閣，華池涵月涼。","書回秋欲盡，酒醒夜初長。","露白蓮衣淺，風清蕙帶香。","前年此佳景，蘭棹醉橫塘。"]', '["念远坐西閣，华池涵月涼。","书回秋欲尽，酒醒夜初长。","露白蓮衣淺，风清蕙带香。","前年此佳景，蘭棹醉橫塘。"]', '诗', 'shi', '', NULL, '秋夕有懷 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b368e99-78ba-45ce-9a35-2bf5c0a250bb', '秋霽寄遠', '秋霽寄远', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["初霽獨登賞，西樓多遠風。","橫煙秋水上，疎雨夕陽中。","高樹下山鳥，平蕪飛草蟲。","唯應待明月，千里與君同。"]', '["初霽独登賞，西楼多远风。","橫煙秋水上，疎雨夕陽中。","高樹下山鸟，平蕪飞草蟲。","唯應待明月，千里與君同。"]', '诗', 'shi', '', NULL, '秋霽寄遠 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35120a7d-9555-479f-9cdc-370dc97d4b74', '經古行宮', '經古行宮', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["臺閣參差倚太陽，年年花發滿山香。","重門勘鎖青春晚，深殿垂簾白日長。","草色芊綿侵御路，泉聲嗚咽繞宮墻。","先皇一去無回駕，紅粉雲環空斷腸。"]', '["台閣參差倚太陽，年年花發满山香。","重门勘鎖青春晚，深殿垂簾白日长。","草色芊綿侵御路，泉声嗚咽繞宮墻。","先皇一去無回駕，紅粉云环空斷腸。"]', '诗', 'shi', '', NULL, '經古行宮 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de353cb-66da-46ad-bb87-7fe9a9052fa5', '宣州開元寺贈惟真上人', '宣州开元寺贈惟真上人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["曾與徑山爲小師，千年僧行衆人知。","夜深月色當禪處，齋後鐘聲到講時。","經雨綠苔侵古畫，過秋紅葉落新詩。","勸君莫厭江城客，雖在風塵別有期。"]', '["曾與徑山爲小師，千年僧行衆人知。","夜深月色當禪处，斋後鐘声到講时。","經雨綠苔侵古畫，過秋紅葉落新诗。","勸君莫厭江城客，雖在风塵別有期。"]', '诗', 'shi', '', NULL, '宣州開元寺贈惟真上人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c6c8b83-6bf8-4cf1-a6f9-72a7480931ad', '秋晚懷茅山石涵村舍', '秋晚懷茅山石涵村舍', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["十畝山田近石涵，村居風俗舊曾諳。","簾前白艾驚春燕，籬上青桑待晚蠶。","雲暖採茶來嶺北，月明沽酒過溪南。","陵陽秋盡多歸思，紅樹蕭蕭覆碧潭。"]', '["十畝山田近石涵，村居风俗旧曾諳。","簾前白艾驚春燕，籬上青桑待晚蠶。","云暖採茶来嶺北，月明沽酒過溪南。","陵陽秋尽多归思，紅樹蕭蕭覆碧潭。"]', '诗', 'shi', '', NULL, '秋晚懷茅山石涵村舍 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7fb92f5-2218-4360-af84-2b553b1060d1', '留題李侍御書齋', '留題李侍御书斋', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["曾話平生志，書齋幾見留。","道孤心易感，恩重力難酬。","獨立千峰晚，頻來一葉秋。","雞鳴應有處，不學淚空流。"]', '["曾話平生志，书斋幾见留。","道孤心易感，恩重力难酬。","独立千峰晚，頻来一葉秋。","雞鳴應有处，不学泪空流。"]', '诗', 'shi', '', NULL, '留題李侍御書齋 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7c94e4-93c7-45ce-8877-2d47cbd22a4b', '行次白沙館先寄上河南王侍郎', '行次白沙館先寄上河南王侍郎', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["夜程何處宿，山疊樹層層。","孤館閑秋雨，空堂停曙燈。","歌慙漁浦客，詩學雁門僧。","此意無人識，明朝見李膺。"]', '["夜程何处宿，山叠樹層層。","孤館闲秋雨，空堂停曙灯。","歌慙漁浦客，诗学雁门僧。","此意無人識，明朝见李膺。"]', '诗', 'shi', '', NULL, '行次白沙館先寄上河南王侍郎 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d505f107-27db-48e3-8e87-87d5a5a671e6', '貴遊', '貴游', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["朝回珮馬草萋萋，年少恩深衛霍齊。","斧鉞舊威龍塞北，池臺新賜鳳城西。","門通碧樹開金鎖，樓對青山倚玉梯。","南陌行人盡廻首，笙歌一曲暮雲低。"]', '["朝回珮马草萋萋，年少恩深衛霍齊。","斧鉞旧威龙塞北，池台新賜鳳城西。","门通碧樹开金鎖，楼对青山倚玉梯。","南陌行人尽廻首，笙歌一曲暮云低。"]', '诗', 'shi', '', NULL, '貴遊 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c49367d4-cdb7-4cc3-8433-0cac723302aa', '越中', '越中', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["石城花暖鷓鴣飛，征客春帆秋不歸。","猶自保郎心似石，綾梭夜夜織寒衣。"]', '["石城花暖鷓鴣飞，征客春帆秋不归。","猶自保郎心似石，綾梭夜夜织寒衣。"]', '诗', 'shi', '', NULL, '越中 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ac6585-2683-4b5f-b94c-854297f32676', '聞范秀才自蜀遊江湖', '闻范秀才自蜀游江湖', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["蜀道下湘渚，客帆應不迷。","江分三峽響，山竝九華齊。","秋泊鴈初宿，夜吟猿乍啼。","歸時慎行李，莫到石城西。"]', '["蜀道下湘渚，客帆應不迷。","江分三峽响，山竝九华齊。","秋泊鴈初宿，夜吟猿乍啼。","归时慎行李，莫到石城西。"]', '诗', 'shi', '', NULL, '聞范秀才自蜀遊江湖 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5272df5-6b7d-485f-a6bd-f1df33a54ae6', '綠蘿', '綠蘿', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["綠蘿縈數匝，本在草堂間。","秋色寄高樹，晝陰籠近山。","移花疎處過，斸藥困時攀。","日暮微風起，難尋舊徑還。"]', '["綠蘿縈數匝，本在草堂间。","秋色寄高樹，晝陰籠近山。","移花疎处過，斸藥困时攀。","日暮微风起，难尋旧徑還。"]', '诗', 'shi', '', NULL, '綠蘿 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdbb7018-8746-4c25-a00a-336a1a235075', '宿東橫山瀨', '宿东橫山瀨', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["孤舟路漸賒，時見碧桃花。","溪雨灘聲急，巖風樹勢斜。","獼猴懸弱柳，鸂鶒睡橫楂。","謾向仙林宿，無人識阮家。"]', '["孤舟路漸賒，时见碧桃花。","溪雨灘声急，巖风樹勢斜。","獼猴懸弱柳，鸂鶒睡橫楂。","謾向仙林宿，無人識阮家。"]', '诗', 'shi', '', NULL, '宿東橫山瀨 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('263c2582-05d9-4f21-b486-bcd547701eaa', '貽遷客', '貽遷客', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["無機還得罪，直道不傷情。","微雨昏山色，疎籠閉鶴聲。","閑居多野客，高枕見江城。","門外長溪水，憐君又濯纓。"]', '["無機還得罪，直道不傷情。","微雨昏山色，疎籠閉鹤声。","闲居多野客，高枕见江城。","门外长溪水，怜君又濯纓。"]', '诗', 'shi', '', NULL, '貽遷客 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccdf927c-b0d5-4603-8a99-ac627e88bf7d', '陵陽送客', '陵陽送客', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["南樓送郢客，西郭望荆門。","鳧鵠下寒渚，牛羊歸遠村。","蘭舟倚行棹，桂酒掩餘罇。","重此一留宿，前汀煙月昏。"]', '["南楼送郢客，西郭望荆门。","鳧鵠下寒渚，牛羊归远村。","蘭舟倚行棹，桂酒掩餘罇。","重此一留宿，前汀煙月昏。"]', '诗', 'shi', '', NULL, '陵陽送客 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c8555c-d6da-4681-810e-0bbd58a246e7', '寄桐江隱者', '寄桐江隐者', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["潮去潮來洲渚春，山花如繡草如茵。","嚴陵臺下桐江水，解釣鱸魚能幾人。"]', '["潮去潮来洲渚春，山花如繡草如茵。","嚴陵台下桐江水，解釣鱸鱼能幾人。"]', '诗', 'shi', '', NULL, '寄桐江隱者 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('952142bd-583b-4bbd-bafa-25e37f2d0953', '長興里夏日寄南隣避暑', '长兴里夏日寄南隣避暑', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["侯家大道傍，蟬噪樹蒼蒼。","開鎖洞門遠，捲簾官舍涼。","欄圍紅藥盛，架引綠蘿長。","永日一欹枕，故山雲水鄉。"]', '["侯家大道傍，蟬噪樹蒼蒼。","开鎖洞门远，捲簾官舍涼。","欄圍紅藥盛，架引綠蘿长。","永日一欹枕，故山云水乡。"]', '诗', 'shi', '', NULL, '長興里夏日寄南隣避暑 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3105b52-d9ef-4848-bf48-afb35adbd9f4', '送太昱禪師', '送太昱禪師', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["禪牀深竹裏，心與徑山期。","結社多高客，登壇盡小師。","早秋歸寺遠，新雨上灘遲。","別後江雲碧，南齋一首詩。"]', '["禪牀深竹裏，心與徑山期。","結社多高客，登壇尽小師。","早秋归寺远，新雨上灘遲。","別後江云碧，南斋一首诗。"]', '诗', 'shi', '', NULL, '送太昱禪師 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac22b4fe-0b9a-49bd-ad10-596cc309c935', '梁秀才以早春旅次大梁將歸郊扉言懷兼別示亦蒙見贈凡二十韻走筆依韻', '梁秀才以早春旅次大梁將归郊扉言懷兼別示亦蒙见贈凡二十韻走笔依韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["玉塞功猶阻，金門事已陳。","世途皆擾擾，鄉黨盡循循。","客道難投足，家聲易發身。","松篁標節晚，蘭蕙吐詞春。","處困羞搖尾，懷忠壯犯鱗。","宅臨三楚水，衣帶二京塵。","歛迹愁山鬼，遺形慕谷神。","採芝先避貴，栽橘早防貧。","弦泛桐材響，杯澄糯醁醇。","但尋陶令集，休獻楚王珍。","林密聞風遠，池平見月勻。","藤龕紅婀娜，苔磴綠嶙峋。","雪樹交梁苑，冰河漲孟津。","面邀文作友，心許德爲隣。","旅館將分被，嬰兒共灑巾。","渭陽連漢曲，京口接漳濱。","通塞時應定，榮枯理會均。","儒流當自勉，妻族更誰親。","照矚三光政，生成四氣仁。","磻溪有心者，垂白肯湮淪。"]', '["玉塞功猶阻，金门事已陳。","世途皆擾擾，乡黨尽循循。","客道难投足，家声易發身。","松篁標節晚，蘭蕙吐词春。","处困羞搖尾，懷忠壯犯鱗。","宅臨三楚水，衣带二京塵。","歛迹愁山鬼，遺形慕谷神。","採芝先避貴，栽橘早防貧。","弦泛桐材响，杯澄糯醁醇。","但尋陶令集，休獻楚王珍。","林密闻风远，池平见月勻。","藤龕紅婀娜，苔磴綠嶙峋。","雪樹交梁苑，冰河漲孟津。","面邀文作友，心許德爲隣。","旅館將分被，嬰兒共灑巾。","渭陽連漢曲，京口接漳濱。","通塞时應定，榮枯理會均。","儒流當自勉，妻族更誰親。","照矚三光政，生成四氣仁。","磻溪有心者，垂白肯湮淪。"]', '诗', 'shi', '', NULL, '梁秀才以早春旅次大梁將歸郊扉言懷兼別示亦蒙見贈凡二十韻走筆依韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d93a5ed7-6c7d-47fe-b394-00b755e2d855', '川守大夫劉公早歲寓居敦行里肆有題壁十韻今之置第乃獲舊居洛下大僚因有唱和歎詠不足輙獻此詩', '川守大夫劉公早歲寓居敦行里肆有題壁十韻今之置第乃獲旧居洛下大僚因有唱和歎詠不足輙獻此诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["旅館當年葺，公才此日論。","林繁輕竹祖，樹暗惜桐孫。","鍊藥藏金鼎，疏泉陷石盆。","散科松有節，深薙草無根。","龍臥池猶在，鸎遷谷尚存。","昔爲揚子宅，今是李膺門。","積學螢嘗聚，微詞鳳早吞。","百年明素志，三顧起新恩。","雪耀冰霜冷，塵飛水墨昏。","莫教垂露迹，歲晚雜苔痕。"]', '["旅館當年葺，公才此日論。","林繁轻竹祖，樹暗惜桐孫。","鍊藥藏金鼎，疏泉陷石盆。","散科松有節，深薙草無根。","龙臥池猶在，鸎遷谷尚存。","昔爲揚子宅，今是李膺门。","積学螢嘗聚，微词鳳早吞。","百年明素志，三顧起新恩。","雪耀冰霜冷，塵飞水墨昏。","莫教垂露迹，歲晚杂苔痕。"]', '诗', 'shi', '', NULL, '川守大夫劉公早歲寓居敦行里肆有題壁十韻今之置第乃獲舊居洛下大僚因有唱和歎詠不足輙獻此詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81acf292-4b8b-427e-bf96-bfceded135ea', '中秋日拜起居表晨渡天津橋即事十六韻獻居守相國崔公兼呈工部劉公', '中秋日拜起居表晨渡天津橋即事十六韻獻居守相国崔公兼呈工部劉公', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["碧樹康莊內，清川鞏洛間。","壇分中岳頂，城繚大河灣。","廣殿含涼靜，深宮積翠閑。","樓齊雲漠漠，橋束水潺潺。","過雨檉枝潤，迎霜柿葉殷。","紫鱗衝晚浪，白鳥背秋山。","月拜西歸表，晨趨北向班。","鴛鴻隨半仗，貔虎護重關。","玉帳才容足，金罇暫解顏。","跡留傷墮屨，恩在樂銜環。","南省蘭先握，東堂桂早攀。","龍門君夭矯，鶯谷我綿蠻。","分薄嵇心懶，哀多庾鬢班。","人慙公幹臥，頻送子牟還。","自覩宸居壯，誰憂國步艱。","只應時與醉，因病縱疎頑。"]', '["碧樹康莊內，清川鞏洛间。","壇分中岳頂，城繚大河灣。","廣殿含涼静，深宮積翠闲。","楼齊云漠漠，橋束水潺潺。","過雨檉枝潤，迎霜柿葉殷。","紫鱗衝晚浪，白鸟背秋山。","月拜西归表，晨趨北向班。","鴛鴻隨半仗，貔虎護重关。","玉帳才容足，金罇暫解顏。","跡留傷墮屨，恩在乐銜环。","南省蘭先握，东堂桂早攀。","龙门君夭矯，鶯谷我綿蠻。","分薄嵇心懶，哀多庾鬢班。","人慙公幹臥，頻送子牟還。","自覩宸居壯，誰憂国步艱。","只應时與醉，因病縱疎頑。"]', '诗', 'shi', '', NULL, '中秋日拜起居表晨渡天津橋即事十六韻獻居守相國崔公兼呈工部劉公 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b13ef423-0fc6-4e91-a62f-5c5ea99fffb3', '分司東都寓居履道叨承川尹劉侍郎大夫恩知上四十韻', '分司东都寓居履道叨承川尹劉侍郎大夫恩知上四十韻', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["命世須人瑞，匡君在岳靈。","氣和薰北陸，襟曠納東溟。","賦妙排鸚鵡，詩能繼鶺鴒。","蒲親香案色，蘭動粉闈馨。","周孔傳文教，蕭曹授武經。","家童諳禁掖，廐馬識金鈴。","性與姦邪背，心因啓沃冥。","進賢光日月，誅惡助雷霆。","閶闔開時召，簫韶奏處聽。","水精懸御幄，雲母展宮屏。","捧詔巡汧隴，飛書護井陘。","先聲威虎兕，餘力活蟭螟。","榮重秦軍箭，功高漢將銘。","戈鋋迴紫塞，干戚散彤庭。","順美皇恩洽，扶顛國步寧。","禹謨推掌誥，湯網屬司刑。","穉榻蓬萊掩，膺舟鞏洛停。","馬羣先去害，民籍更添丁。","猾吏門長塞，豪家戶不扃。","四知臺上鏡，三惑井中瓶。","雅韻憑開匣，雄鋩待發硎。","火中膠綠樹，泉下斸青萍。","五岳期雙節，三台空一星。","鳳池方注意，麟閣會圖行。","寒暑逾流電，光陰甚建瓴。","散曹分已白，崇直眼由青。","賜第成官舍，傭居起客亭。","松筠侵巷陌，禾黍接郊坰。","宿雨回爲沼，春沙淀作汀。","魚罾棲翡翠，蛛網掛蜻蜓。","遲曉河初轉，傷秋露已零。","夢餘鐘杳杳，吟罷燭熒熒。","字小書難寫，桮遲酒易醒。","久貧驚早鴈，多病放殘螢。","雪勁孤根竹，風彫數莢蓂。","轉喉空婀娜，垂手自娉婷。","脛細摧新履，腰羸減舊鞓。","海邊慵逐臭，塵外怯吞腥。","隱豹窺重巘，潛虯避濁涇。","商歌如不顧，歸棹越南{氵雨/品}。"]', '["命世須人瑞，匡君在岳靈。","氣和薰北陸，襟曠納东溟。","賦妙排鸚鵡，诗能繼鶺鴒。","蒲親香案色，蘭动粉闈馨。","周孔傳文教，蕭曹授武經。","家童諳禁掖，廐马識金鈴。","性與姦邪背，心因啓沃冥。","進賢光日月，誅惡助雷霆。","閶闔开时召，簫韶奏处听。","水精懸御幄，云母展宮屏。","捧詔巡汧隴，飞书護井陘。","先声威虎兕，餘力活蟭螟。","榮重秦軍箭，功高漢將銘。","戈鋋迴紫塞，干戚散彤庭。","順美皇恩洽，扶顛国步寧。","禹謨推掌誥，湯網屬司刑。","穉榻蓬萊掩，膺舟鞏洛停。","马羣先去害，民籍更添丁。","猾吏门长塞，豪家戶不扃。","四知台上镜，三惑井中瓶。","雅韻憑开匣，雄鋩待發硎。","火中膠綠樹，泉下斸青萍。","五岳期雙節，三台空一星。","鳳池方注意，麟閣會圖行。","寒暑逾流電，光陰甚建瓴。","散曹分已白，崇直眼由青。","賜第成官舍，傭居起客亭。","松筠侵巷陌，禾黍接郊坰。","宿雨回爲沼，春沙淀作汀。","鱼罾棲翡翠，蛛網掛蜻蜓。","遲晓河初轉，傷秋露已零。","梦餘鐘杳杳，吟罷燭熒熒。","字小书难寫，桮遲酒易醒。","久貧驚早鴈，多病放殘螢。","雪勁孤根竹，风彫數莢蓂。","轉喉空婀娜，垂手自娉婷。","脛細摧新履，腰羸減旧鞓。","海邊慵逐臭，塵外怯吞腥。","隐豹窺重巘，潛虯避濁涇。","商歌如不顧，归棹越南{氵雨/品}。"]', '诗', 'shi', '', NULL, '分司東都寓居履道叨承川尹劉侍郎大夫恩知上四十韻 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b32e82-b781-438a-ae5a-90fcff37ce2b', '題白雲樓', '題白云楼', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["西北樓開四望通，殘霞成綺月懸弓。","江村夜漲浮天水，澤國秋生動地風。","高下綠苗千頃盡，新陳紅粟萬箱空。","才微分薄憂何益，却欲回心學塞翁。"]', '["西北楼开四望通，殘霞成綺月懸弓。","江村夜漲浮天水，澤国秋生动地风。","高下綠苗千頃尽，新陳紅粟万箱空。","才微分薄憂何益，却欲回心学塞翁。"]', '诗', 'shi', '', NULL, '題白雲樓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be357910-9baf-4763-ac3e-3f8a11d074ca', '贈別', '贈別', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["眼前迎送不曾休，相續輪蹄似水流。","門外若無南北路，人間應免別離愁。","蘇秦六印歸何日，潘岳雙毛去值秋。","莫怪分襟銜淚語，十年耕釣憶滄洲。"]', '["眼前迎送不曾休，相續輪蹄似水流。","门外若無南北路，人间應免別離愁。","蘇秦六印归何日，潘岳雙毛去值秋。","莫怪分襟銜泪語，十年耕釣憶滄洲。"]', '诗', 'shi', '', NULL, '贈別 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11425c0-11e0-41ea-ba1b-7e0b12fd5b23', '秋夜與友人宿', '秋夜與友人宿', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["楚國同遊過十霜，萬重心事幾堪傷。","蒹葭露白蓮塘淺，砧杵夜清河漢涼。","雲外山川歸夢遠，天涯歧路客愁長。","寒城欲曉聞吹笛，猶臥東軒月滿牀。"]', '["楚国同游過十霜，万重心事幾堪傷。","蒹葭露白蓮塘淺，砧杵夜清河漢涼。","云外山川归梦远，天涯歧路客愁长。","寒城欲晓闻吹笛，猶臥东軒月满牀。"]', '诗', 'shi', '', NULL, '秋夜與友人宿 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('168eba54-c8a7-4690-90fd-aeb22b271741', '將赴京留贈僧院', '將赴京留贈僧院', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["九衢塵土遞追攀，馬跡軒車日暮間。","玄髪盡驚爲客換，白頭曾見幾人閑。","空悲浮世雲無定，多感流年水不還。","謝却從前受恩地，歸來依止叩禪關。"]', '["九衢塵土遞追攀，马跡軒车日暮间。","玄髪尽驚爲客換，白头曾见幾人闲。","空悲浮世云無定，多感流年水不還。","謝却從前受恩地，归来依止叩禪关。"]', '诗', 'shi', '', NULL, '將赴京留贈僧院 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08a96355-143c-40eb-9c8b-abcc42b82721', '寄湘中友人', '寄湘中友人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["莫戀醉鄉迷酒桮，流年長怕少年催。","西陵水闊魚難到，南國路遙書未回。","匹馬計程愁日盡，一蟬何事引秋來。","相如已定題橋志，江上無由夢釣臺。"]', '["莫戀醉乡迷酒桮，流年长怕少年催。","西陵水闊鱼难到，南国路遙书未回。","匹马計程愁日尽，一蟬何事引秋来。","相如已定題橋志，江上無由梦釣台。"]', '诗', 'shi', '', NULL, '寄湘中友人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377fd2d1-06c2-44c3-bb4c-301674936478', '江上逢友人', '江上逢友人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["故國歸人酒一盃，暫亭蘭棹共裴回。","村連三峽暮雲起，潮送九江寒雨來。","已作相如投賦計，還憑殷浩寄書迴。","到時若見東籬菊，爲問經霜幾度開。"]', '["故国归人酒一盃，暫亭蘭棹共裴回。","村連三峽暮云起，潮送九江寒雨来。","已作相如投賦計，還憑殷浩寄书迴。","到时若见东籬菊，爲问經霜幾度开。"]', '诗', 'shi', '', NULL, '江上逢友人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b014850a-7c92-4dc5-be88-3486cb0bea18', '金谷懷古', '金谷懷古', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["淒涼遺跡洛川東，浮世榮枯萬古同。","桃李香消金谷在，綺羅魂斷玉樓空。","往年人事傷心外，今日風光屬夢中。","徒想夜泉流客恨，夜泉流恨恨無窮。"]', '["淒涼遺跡洛川东，浮世榮枯万古同。","桃李香消金谷在，綺羅魂斷玉楼空。","往年人事傷心外，今日风光屬梦中。","徒想夜泉流客恨，夜泉流恨恨無窮。"]', '诗', 'shi', '', NULL, '金谷懷古 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e52d648-f27f-4c64-a47a-b06696d5e37f', '寄盧先輩', '寄盧先輩', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["一從分首劒江濱，南國相思寄夢頻。","書去又逢商嶺雪，信回應過洞庭春。","關河日日悲長路，霄漢年年望後塵。","願指丹梯曾到處，莫教猶作獨迷人。"]', '["一從分首劒江濱，南国相思寄梦頻。","书去又逢商嶺雪，信回應過洞庭春。","关河日日悲长路，霄漢年年望後塵。","願指丹梯曾到处，莫教猶作独迷人。"]', '诗', 'shi', '', NULL, '寄盧先輩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb76d3a-fa0f-4c28-afc4-73d7f1e1bdca', '南樓夜', '南楼夜', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["玉管金罇夜不休，如悲晝短惜年流。","歌聲褭褭澈清夜，月色娟娟當翠樓。","枕上暗驚垂釣夢，燈前偏起別家愁。","思量今日英雄事，身到簪裾已白頭。"]', '["玉管金罇夜不休，如悲晝短惜年流。","歌声褭褭澈清夜，月色娟娟當翠楼。","枕上暗驚垂釣梦，灯前偏起別家愁。","思量今日英雄事，身到簪裾已白头。"]', '诗', 'shi', '', NULL, '南樓夜 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c69eec8e-2a84-4950-9a73-dcd540447c55', '行經廬山東林寺', '行經廬山东林寺', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["離魂斷續楚江壖，葉墜初紅十月天。","紫陌事多難暫息，青山長在好閑眠。","方趨上國期干祿，未得空堂學坐禪。","他歲若教如范蠡，也應須入五湖煙。"]', '["離魂斷續楚江壖，葉墜初紅十月天。","紫陌事多难暫息，青山长在好闲眠。","方趨上国期干祿，未得空堂学坐禪。","他歲若教如范蠡，也應須入五湖煙。"]', '诗', 'shi', '', NULL, '行經廬山東林寺 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db6298f9-cb5c-4b4c-9707-4959c9a8e114', '途中逢故人話西山讀書早曾遊覽', '途中逢故人話西山读书早曾游覽', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["西巖曾到讀書堂，穿竹行莎十里強。","湖上夢餘波灩灩，嶺頭愁斷路茫茫。","經過事寄煙霞遠，名利塵隨日月長。","莫道少年頭不白，君看潘岳幾莖霜。"]', '["西巖曾到读书堂，穿竹行莎十里強。","湖上梦餘波灩灩，嶺头愁斷路茫茫。","經過事寄煙霞远，名利塵隨日月长。","莫道少年头不白，君看潘岳幾莖霜。"]', '诗', 'shi', '', NULL, '途中逢故人話西山讀書早曾遊覽 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1200f8ba-fd2b-4480-b584-99457cf3f081', '將赴京題陵陽王氏水居', '將赴京題陵陽王氏水居', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["簾卷平蕪接遠天，暫寬行役到罇前。","是非境裏有閑日，榮辱塵中無了年。","山簇暮雲千野雨，江分秋水九條煙。","馬蹄不道貪西去，爭向一聲高樹蟬。"]', '["簾卷平蕪接远天，暫寬行役到罇前。","是非境裏有闲日，榮辱塵中無了年。","山簇暮云千野雨，江分秋水九條煙。","马蹄不道貪西去，爭向一声高樹蟬。"]', '诗', 'shi', '', NULL, '將赴京題陵陽王氏水居 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2709de0e-6b44-4c05-b5c9-82915bc83ab8', '送別', '送別', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["溪邊楊柳色參差，攀折年年贈別離。","一片風帆望已極，三湘煙水返何時？","多緣去棹將愁遠，猶倚危亭欲下遲。","莫殢酒盃閑過日，碧雲深處是佳期。"]', '["溪邊楊柳色參差，攀折年年贈別離。","一片风帆望已極，三湘煙水返何时？","多緣去棹將愁远，猶倚危亭欲下遲。","莫殢酒盃闲過日，碧云深处是佳期。"]', '诗', 'shi', '', NULL, '送別 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78bd43f1-9a37-410a-9671-f7fbdeaf2443', '寄遠', '寄远', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["兩葉愁眉愁不開，獨含惆悵上層臺。","碧雲空斷鴈行處，紅葉已彫人未來。","塞外音書無信息，道傍車馬起塵埃。","功名待寄凌煙閣，力盡遼城不肯迴。"]', '["兩葉愁眉愁不开，独含惆悵上層台。","碧云空斷鴈行处，紅葉已彫人未来。","塞外音书無信息，道傍车马起塵埃。","功名待寄凌煙閣，力尽遼城不肯迴。"]', '诗', 'shi', '', NULL, '寄遠 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6699173b-2c98-4aa7-96fd-5ce5f8e5e51d', '新柳', '新柳', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["無力搖風曉色新，細腰爭妬看來頻。","綠陰未覆長堤水，金穗先迎上苑春。","幾處傷心懷遠路，一枝和雨送行塵。","東門門外多離別，愁殺朝朝暮暮人。"]', '["無力搖风晓色新，細腰爭妬看来頻。","綠陰未覆长堤水，金穗先迎上苑春。","幾处傷心懷远路，一枝和雨送行塵。","东门门外多離別，愁殺朝朝暮暮人。"]', '诗', 'shi', '', NULL, '新柳 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a66dc561-76e6-46d5-855f-8cc039e1f612', '旅懷作', '旅懷作', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["促促因吟晝短詩，朝驚穠色暮空枝。","無情春色不長久，有限年光多盛衰。","往事只應隨夢裏，勞生何處是閑時？","眼前擾擾日一日，暗送白頭人不知。"]', '["促促因吟晝短诗，朝驚穠色暮空枝。","無情春色不长久，有限年光多盛衰。","往事只應隨梦裏，勞生何处是闲时？","眼前擾擾日一日，暗送白头人不知。"]', '诗', 'shi', '', NULL, '旅懷作 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66b80d5-086e-4f74-91f0-4896c88da754', '鴈', '鴈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["萬里銜蘆別故鄉，雲飛雨宿向瀟湘。","數聲孤枕堪垂淚，幾處高樓欲斷腸。","度日翩翩斜避影，臨風一一直成行。","年年辛苦來衡岳，羽翼摧殘隴塞霜。"]', '["万里銜蘆別故乡，云飞雨宿向瀟湘。","數声孤枕堪垂泪，幾处高楼欲斷腸。","度日翩翩斜避影，臨风一一直成行。","年年辛苦来衡岳，羽翼摧殘隴塞霜。"]', '诗', 'shi', '', NULL, '鴈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ece70a7-c48a-4800-aa3f-5417939ce33f', '惜春', '惜春', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["花開又花落，時節暗中遷。","無計延春日，何能駐少年。","小藂初散蝶，高柳即聞蟬。","繁豔歸何處，滿山啼杜鵑。"]', '["花开又花落，时節暗中遷。","無計延春日，何能駐少年。","小藂初散蝶，高柳即闻蟬。","繁豔归何处，满山啼杜鵑。"]', '诗', 'shi', '', NULL, '惜春 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d766bc60-a7aa-4ffd-9ed7-74a4b57080ab', '鴛鴦', '鴛鴦', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["兩兩戲沙汀，長疑畫不成。","錦機爭織樣，歌曲愛呼名。","好育顧栖息，堪憐泛淺清。","鳧鷗皆爾類，惟羨獨含情。"]', '["兩兩戲沙汀，长疑畫不成。","錦機爭织樣，歌曲愛呼名。","好育顧栖息，堪怜泛淺清。","鳧鷗皆爾類，惟羨独含情。"]', '诗', 'shi', '', NULL, '鴛鴦 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15456a8-72f0-4c28-9e52-7d5194ba4759', '聞鴈', '闻鴈', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["帶霜南去鴈，夜好宿汀沙。","驚起向何處，高飛極海涯。","入雲聲漸遠，離岳路由賒。","歸夢當時斷，參差欲到家。"]', '["带霜南去鴈，夜好宿汀沙。","驚起向何处，高飞極海涯。","入云声漸远，離岳路由賒。","归梦當时斷，參差欲到家。"]', '诗', 'shi', '', NULL, '聞鴈 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff7aa762-4959-4037-8af3-5b23c71fec46', '江樓晚望', '江楼晚望', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["湖山翠欲結蒙籠，汗漫誰遊夕照中。","初語燕雛知社日，習飛鷹隼識秋風。","波搖珠樹千尋拔，山鑿金陵萬仞空。","不欲登樓更懷古，斜陽江上正飛鴻。"]', '["湖山翠欲結蒙籠，汗漫誰游夕照中。","初語燕雛知社日，習飞鷹隼識秋风。","波搖珠樹千尋拔，山鑿金陵万仞空。","不欲登楼更懷古，斜陽江上正飞鴻。"]', '诗', 'shi', '', NULL, '江樓晚望 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b4183c-0bac-4d7f-bc2b-c60bd4f6d975', '九日', '九日', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["金英繁亂拂闌香，明府辭官酒滿缸。","還有玉樓輕薄女，笑他寒燕一雙雙。"]', '["金英繁亂拂闌香，明府辞官酒满缸。","還有玉楼轻薄女，笑他寒燕一雙雙。"]', '诗', 'shi', '', NULL, '九日 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ba31e4-154a-4a6b-bea0-7d3c3b666235', '寄牛相公', '寄牛相公', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["漢水橫衝蜀浪分，危樓點的拂孤雲。","六年仁政謳歌去，柳遶春堤處處聞。"]', '["漢水橫衝蜀浪分，危楼点的拂孤云。","六年仁政謳歌去，柳遶春堤处处闻。"]', '诗', 'shi', '', NULL, '寄牛相公 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d31ad0-1298-4d2b-9791-abf5ae6217a3', '爲人題贈二首 一', '爲人題贈二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["我乏青雲稱，君無買笑金。","虛傳南國貌，爭奈五陵心。","桂席塵瑤珮，瓊鑪燼水沈。","凝魂空薦夢，低耳悔聽琴。","月落珠簾卷，春寒錦幕深。","誰家樓上笛，何處月明砧？","蘭徑飛蝴蝶，筠籠語翠襟。","和簪拋鳳髻，將淚入鴛衾。","的的新添恨，迢迢絕好音。","文園終病渴，休詠白頭吟。"]', '["我乏青云稱，君無買笑金。","虛傳南国貌，爭奈五陵心。","桂席塵瑤珮，瓊鑪燼水沈。","凝魂空薦梦，低耳悔听琴。","月落珠簾卷，春寒錦幕深。","誰家楼上笛，何处月明砧？","蘭徑飞蝴蝶，筠籠語翠襟。","和簪拋鳳髻，將泪入鴛衾。","的的新添恨，迢迢絕好音。","文园終病渴，休詠白头吟。"]', '诗', 'shi', '', NULL, '爲人題贈二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b17ef17-afc8-4012-a1d4-38c60d838bbf', '爲人題贈二首 二', '爲人題贈二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["綠樹鶯鶯語，平江燕燕飛。","枕前聞[鴈去]，樓上送春歸。","半月縆雙臉，凝腰素一圍。","西牆苔漠漠，南浦夢依依。","有恨簪花懶，無聊鬬草稀。","雕籠長慘淡，蘭畹謾芳菲。","鏡歛青蛾黛，燈挑皓腕肌。","避人勻迸淚，拖袖倚殘暉。","有貌雖桃李，單棲足是非。","雲軿載馭去，寒夜看裁衣。"]', '["綠樹鶯鶯語，平江燕燕飞。","枕前闻[鴈去]，楼上送春归。","半月縆雙臉，凝腰素一圍。","西牆苔漠漠，南浦梦依依。","有恨簪花懶，無聊鬬草稀。","雕籠长慘淡，蘭畹謾芳菲。","镜歛青蛾黛，灯挑皓腕肌。","避人勻迸泪，拖袖倚殘暉。","有貌雖桃李，單棲足是非。","云軿載馭去，寒夜看裁衣。"]', '诗', 'shi', '', NULL, '爲人題贈二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f8e8fcd-3837-44c6-a8ed-8d5fad1b89a8', '懷紫閣山', '懷紫閣山', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["學他趨世少深機，紫閣青霄半掩扉。","山路遠懷王子晉，詩家長憶謝玄暉。","百年不肯疎榮辱，雙鬢終應老是非。","人道青山歸去好，青山曾有幾人歸。"]', '["学他趨世少深機，紫閣青霄半掩扉。","山路远懷王子晉，诗家长憶謝玄暉。","百年不肯疎榮辱，雙鬢終應老是非。","人道青山归去好，青山曾有幾人归。"]', '诗', 'shi', '', NULL, '懷紫閣山 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ca8f60-156f-4e8d-be89-af81e81a4e21', '題孫逸人山居', '題孫逸人山居', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["長懸青紫與芳枝，塵剎無應免別離。","馬上多于在家日，罇前堪憶少年時。","關河客夢還鄉遠，雨雪山程出店遲。","却羨高人終此老，軒車過盡不知誰。"]', '["长懸青紫與芳枝，塵剎無應免別離。","马上多于在家日，罇前堪憶少年时。","关河客梦還乡远，雨雪山程出店遲。","却羨高人終此老，軒车過尽不知誰。"]', '诗', 'shi', '', NULL, '題孫逸人山居 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972e906f-1d41-4dbd-91a6-cea7d0ac0103', '中途寄友人', '中途寄友人', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["道傍高木盡依依，落葉驚風處處飛。","未到鄉關聞早鴈，獨於客路授寒衣。","煙霞舊想長相阻，書劒投人久不歸。","何日一名隨事了，與君同採碧溪薇。"]', '["道傍高木尽依依，落葉驚风处处飞。","未到乡关闻早鴈，独於客路授寒衣。","煙霞旧想长相阻，书劒投人久不归。","何日一名隨事了，與君同採碧溪薇。"]', '诗', 'shi', '', NULL, '中途寄友人 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db854b4c-e12b-4df4-a689-38b9b21c92fc', '悵詩', '悵诗', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["自是尋春去校遲，不須惆悵怨芳時。","狂風落盡深紅色，綠葉成陰子滿枝。"]', '["自是尋春去校遲，不須惆悵怨芳时。","狂风落尽深紅色，綠葉成陰子满枝。"]', '诗', 'shi', '', NULL, '悵詩 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09c0b985-2860-4c36-9819-34bf9492b4cb', '吳宮詞二首 一', '吳宮词二首 一', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["越兵驅綺羅，越女唱吳歌。","宮燼花聲少，臺荒麋跡多。","茱萸垂曉露，菡萏落秋波。","無遣君王醉，滿城嚬翠蛾。"]', '["越兵驱綺羅，越女唱吳歌。","宮燼花声少，台荒麋跡多。","茱萸垂晓露，菡萏落秋波。","無遣君王醉，满城嚬翠蛾。"]', '诗', 'shi', '', NULL, '吳宮詞二首 一 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb8eaf8-053d-4a82-a3f2-50ef87acb86e', '吳宮詞二首 二', '吳宮词二首 二', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["香逕遶吳宮，千帆落照中。","鶴鳴山苦雨，魚躍水多風。","城帶晚莎綠，池連秋蓼紅。","當年國門外，誰信伍員忠。"]', '["香逕遶吳宮，千帆落照中。","鹤鳴山苦雨，鱼躍水多风。","城带晚莎綠，池連秋蓼紅。","當年国门外，誰信伍員忠。"]', '诗', 'shi', '', NULL, '吳宮詞二首 二 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c42792a9-b483-48a9-8f8d-b0ed6d22db1c', '金陵', '金陵', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["始發碧江口，曠然諧遠心。","風清舟在鑑，日落水浮金。","瓜步逢潮信，臺城過雁音。","故鄉何處是，雲外即喬林。"]', '["始發碧江口，曠然諧远心。","风清舟在鑑，日落水浮金。","瓜步逢潮信，台城過雁音。","故乡何处是，云外即喬林。"]', '诗', 'shi', '', NULL, '金陵 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2087940b-efb1-46e8-9f42-9d61118e2f65', '即事', '即事', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["小院無人雨長苔，滿庭修竹間疎槐。","春愁兀兀成幽夢，又被流鶯喚醒來。"]', '["小院無人雨长苔，满庭修竹间疎槐。","春愁兀兀成幽梦，又被流鶯喚醒来。"]', '诗', 'shi', '', NULL, '即事 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f748737-934b-41fb-92a1-15ac0106f5ff', '七夕', '七夕', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["雲堦月地一相過，未抵經年別恨多。","最恨明朝洗車雨，不教回脚渡天河。"]', '["云堦月地一相過，未抵經年別恨多。","最恨明朝洗车雨，不教回脚渡天河。"]', '诗', 'shi', '', NULL, '七夕 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978ec320-75b9-4de0-b0a1-4bf2f24deba9', '薔薇花', '薔薇花', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["朵朵精神葉葉柔，雨晴香拂醉人頭。","石家錦幛依然在，閑倚狂風夜不收。"]', '["朵朵精神葉葉柔，雨晴香拂醉人头。","石家錦幛依然在，闲倚狂风夜不收。"]', '诗', 'shi', '', NULL, '薔薇花 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f60ca29-73a7-4d6d-920c-163e1757cd78', '句', '句', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["幽人聽達曙，聊罷蘇牀琴。","魚多知海熟，藥少覺山貧。","土控吳兼越，州連歙與池。","山河地襟帶，軍鎮國藩維。","綠水櫂雲月，洞庭歸路長。","春橋垂酒幔，夜柵集茶檣。","箬影沈溪暖，蘋花遶郭香。","經冬野菜青青色，未臘山梅樹樹花。","半破前峰月。"]', '["幽人听達曙，聊罷蘇牀琴。","鱼多知海熟，藥少覺山貧。","土控吳兼越，州連歙與池。","山河地襟带，軍鎮国藩維。","綠水櫂云月，洞庭归路长。","春橋垂酒幔，夜柵集茶檣。","箬影沈溪暖，蘋花遶郭香。","經冬野菜青青色，未臘山梅樹樹花。","半破前峰月。"]', '诗', 'shi', '', NULL, '句 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bfd5f7d-2db9-40e9-9756-e662b1f26902', '陪王尚書泛舟蓮池', '陪王尚书泛舟蓮池', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蓮塘移畫舸，泛泛日華清。","水暖魚頻躍，煙秋雁早鳴。","舞疑回雪態，歌轉遏雲聲。","客散山公醉，風高月滿城。"]', '["蓮塘移畫舸，泛泛日华清。","水暖鱼頻躍，煙秋雁早鳴。","舞疑回雪態，歌轉遏云声。","客散山公醉，风高月满城。"]', '诗', 'shi', '', NULL, '陪王尚書泛舟蓮池 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f232cc-76bc-49e2-9939-c9afe9382fd7', '贈裴處士', '贈裴处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["爲儒白髮生，鄉里早聞名。","煖酒雪初下，讀書山欲明。","字形翻鳥跡，詩調合猿聲。","門外滄浪水，知君欲濯纓。"]', '["爲儒白髮生，乡里早闻名。","煖酒雪初下，读书山欲明。","字形翻鸟跡，诗調合猿声。","门外滄浪水，知君欲濯纓。"]', '诗', 'shi', '', NULL, '贈裴處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66eef6e0-819c-4d4b-ba83-72358755f2d9', '對雪', '对雪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["飛舞北風涼，玉人歌玉堂。","簾帷增曙色，珠翠發寒光。","柳重絮微濕，梅繁花未香。","茲辰賀豐歲，簫鼓宴梁王。"]', '["飞舞北风涼，玉人歌玉堂。","簾帷增曙色，珠翠發寒光。","柳重絮微濕，梅繁花未香。","茲辰賀豐歲，簫鼓宴梁王。"]', '诗', 'shi', '', NULL, '對雪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d5c005-1f9d-475d-b6f6-4db178d71dfe', '王居士', '王居士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["筇杖倚柴關，都城賣卜還。","雨中耕白水，雲外斸青山。","有藥身長健，無機性自閑。","即應生羽翼，華表在人間。"]', '["筇杖倚柴关，都城賣卜還。","雨中耕白水，云外斸青山。","有藥身长健，無機性自闲。","即應生羽翼，华表在人间。"]', '诗', 'shi', '', NULL, '王居士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fedb06cc-37da-4aaf-8f39-85ebcb08b947', '早秋三首 一', '早秋三首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["遙夜泛清瑟，西風生翠蘿。","殘螢委玉露，早鴈拂銀河。","高樹曉還密，遠山晴更多。","淮南一葉下，自覺老煙波。"]', '["遙夜泛清瑟，西风生翠蘿。","殘螢委玉露，早鴈拂銀河。","高樹晓還密，远山晴更多。","淮南一葉下，自覺老煙波。"]', '诗', 'shi', '', NULL, '早秋三首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63cfaf6e-f0d7-4b7a-a1b6-156d046d6549', '早秋三首 二', '早秋三首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一葉下前墀，淮南人已悲。","蹉跎青漢望，迢遰白雲期。","老信相如渴，貧憂曼倩飢。"]', '["一葉下前墀，淮南人已悲。","蹉跎青漢望，迢遰白云期。","老信相如渴，貧憂曼倩飢。"]', '诗', 'shi', '', NULL, '早秋三首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc94ca1-bd5e-43a2-8233-581d68b277de', '早秋三首 三', '早秋三首 三', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["薊北雁猶遠，淮南人已悲。","殘桃間墮井，新菊亦侵籬。","書劒豈相誤，琴尊聊自持。","西齋風雨夜，更有詠貧詩。"]', '["薊北雁猶远，淮南人已悲。","殘桃间墮井，新菊亦侵籬。","书劒豈相誤，琴尊聊自持。","西斋风雨夜，更有詠貧诗。"]', '诗', 'shi', '', NULL, '早秋三首 三 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8871da0e-5659-48ca-b47e-4fdc2871e542', '洛東蘭若夜歸', '洛东蘭若夜归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["一衲老禪牀，吾生半異鄉。","管弦愁裏老，書劒夢中忙。","鳥急山初暝，蟬稀樹正涼。","又歸何處去，塵路月蒼蒼。"]', '["一衲老禪牀，吾生半異乡。","管弦愁裏老，书劒梦中忙。","鸟急山初暝，蟬稀樹正涼。","又归何处去，塵路月蒼蒼。"]', '诗', 'shi', '', NULL, '洛東蘭若夜歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d990bf-0a3d-42bf-ad1f-20ab8a7eae80', '送段覺歸杜曲閑居', '送段覺归杜曲闲居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["書劒南歸去，山扉別幾年。","苔侵巖下路，果落洞中泉。","紅葉高齋雨，青蘿曲檻煙。","寧知遠游客，羸馬太行前。"]', '["书劒南归去，山扉別幾年。","苔侵巖下路，果落洞中泉。","紅葉高斋雨，青蘿曲檻煙。","寧知远游客，羸马太行前。"]', '诗', 'shi', '', NULL, '送段覺歸杜曲閑居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c200404-86a6-44c1-be5d-925f67a29a2b', '寄天鄉寺仲儀上人富春孫處士', '寄天乡寺仲儀上人富春孫处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["詩僧與釣翁，千里兩情通。","雲帶鴈門雪，水連漁浦風。","心期榮辱外，名挂是非中。","歲晚亦歸去，田園清洛東。"]', '["诗僧與釣翁，千里兩情通。","云带鴈门雪，水連漁浦风。","心期榮辱外，名挂是非中。","歲晚亦归去，田园清洛东。"]', '诗', 'shi', '', NULL, '寄天鄉寺仲儀上人富春孫處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db574e31-99c3-42fa-8b45-00bb52037cad', '寄契盈上人', '寄契盈上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["何處是西林，疎鐘復遠砧。","鴈來秋水闊，鴉盡夕陽沈。","婚嫁乖前志，功名異夙心。","湯師不可問，江上碧雲深。"]', '["何处是西林，疎鐘复远砧。","鴈来秋水闊，鴉尽夕陽沈。","婚嫁乖前志，功名異夙心。","湯師不可问，江上碧云深。"]', '诗', 'shi', '', NULL, '寄契盈上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b38cd90-d673-48c6-a71c-d09b9c622e25', '晨起二首 一', '晨起二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桂樹綠層層，風微煙露凝。","簷楹銜落月，幃幌映殘燈。","蘄簟曙香冷，越瓶秋水澄。","心閑即無事，何異住山僧。"]', '["桂樹綠層層，风微煙露凝。","簷楹銜落月，幃幌映殘灯。","蘄簟曙香冷，越瓶秋水澄。","心闲即無事，何異住山僧。"]', '诗', 'shi', '', NULL, '晨起二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5416fc63-68d3-4259-88ac-6278432931e8', '晨起二首 二', '晨起二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["殘月皓煙露，掩門深竹齋。","水蟲鳴曲檻，山鳥下空階。","清鏡曉看髪，素琴秋寄懷。","因知北窗客，日與世情乖。"]', '["殘月皓煙露，掩门深竹斋。","水蟲鳴曲檻，山鸟下空階。","清镜晓看髪，素琴秋寄懷。","因知北窗客，日與世情乖。"]', '诗', 'shi', '', NULL, '晨起二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a1fa9b2-6635-453a-b2ce-bba56021376c', '曉發鄞江北渡寄崔韓二先輩', '晓發鄞江北渡寄崔韓二先輩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南北信多岐，生涯半別離。","地窮山盡處，江泛水寒時。","露曉蒹葭重，霜晴橘柚垂。","無勞促回檝，千里有心期。"]', '["南北信多岐，生涯半別離。","地窮山尽处，江泛水寒时。","露晓蒹葭重，霜晴橘柚垂。","無勞促回檝，千里有心期。"]', '诗', 'shi', '', NULL, '曉發鄞江北渡寄崔韓二先輩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13693ea3-2a58-4c7e-a114-af3df8816d71', '盈上人', '盈上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["月沈霜已凝，無夢竟寒燈。","寄世何殊客，修身未到僧。","二毛梳上雪，雙淚枕前冰。","借問曹溪路，山多路幾層。"]', '["月沈霜已凝，無梦竟寒灯。","寄世何殊客，修身未到僧。","二毛梳上雪，雙泪枕前冰。","借问曹溪路，山多路幾層。"]', '诗', 'shi', '', NULL, '盈上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8eb5ada-10d7-423a-aae6-647f4a1c6c9f', '廣陵道中', '廣陵道中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["城勢已坡陀，城邊東逝波。","綠桑非苑樹，青草是宮莎。","山暝牛羊少，水寒鳧鴈多。","因高一回首，還詠黍離歌。"]', '["城勢已坡陀，城邊东逝波。","綠桑非苑樹，青草是宮莎。","山暝牛羊少，水寒鳧鴈多。","因高一回首，還詠黍離歌。"]', '诗', 'shi', '', NULL, '廣陵道中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8599f94-fc90-443f-8a40-d556f8724b2b', '宿開元寺樓', '宿开元寺楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["誰家歌褭褭，孤枕在西樓。","竹色寒清簟，松香染翠幬。","月移珠殿曉，風遰玉箏秋。","日出應移棹，三湘萬里愁。"]', '["誰家歌褭褭，孤枕在西楼。","竹色寒清簟，松香染翠幬。","月移珠殿晓，风遰玉箏秋。","日出應移棹，三湘万里愁。"]', '诗', 'shi', '', NULL, '宿開元寺樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e82eadf-3c24-49c0-9771-bcb4bddabc6e', '洞靈觀冬青', '洞靈观冬青', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["霜霰不凋色，兩株交石壇。","未秋紅實淺，經夏綠陰寒。","露重蟬鳴急，風多鳥宿難。","何如西禁柳，晴舞玉闌干。"]', '["霜霰不凋色，兩株交石壇。","未秋紅實淺，經夏綠陰寒。","露重蟬鳴急，风多鸟宿难。","何如西禁柳，晴舞玉闌干。"]', '诗', 'shi', '', NULL, '洞靈觀冬青 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ba82d59-8e2e-4ade-8f2a-48df44825c5c', '送友人自荆襄歸江東', '送友人自荆襄归江东', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["商洛轉江濆，一杯聊送君。","劒愁龍失伴，琴怨鶴離羣。","楚驛枕秋水，湘帆凌暮雲。","猿聲斷腸夜，應向雨中聞。"]', '["商洛轉江濆，一杯聊送君。","劒愁龙失伴，琴怨鹤離羣。","楚驛枕秋水，湘帆凌暮云。","猿声斷腸夜，應向雨中闻。"]', '诗', 'shi', '', NULL, '送友人自荆襄歸江東 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad9d3fdf-78b1-4091-a5f3-394608cb87c4', '送同年崔先輩', '送同年崔先輩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西風帆勢輕，南浦遍離情。","菊豔含秋水，荷花遰雨聲。","扣舷灘鳥沒，移棹草蟲鳴。","更憶前年別，槐花滿鳳城。"]', '["西风帆勢轻，南浦遍離情。","菊豔含秋水，荷花遰雨声。","扣舷灘鸟沒，移棹草蟲鳴。","更憶前年別，槐花满鳳城。"]', '诗', 'shi', '', NULL, '送同年崔先輩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a6f80c1-092b-4534-bd0b-a602cf0e9914', '山雞', '山雞', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["珍禽暫不扃，飛舞躍前庭。","翠網摧金距，雕籠減繡翎。","月圓疑望鏡，花暖似依屏。","何必舊巢去，山山芳草青。"]', '["珍禽暫不扃，飞舞躍前庭。","翠網摧金距，雕籠減繡翎。","月圓疑望镜，花暖似依屏。","何必旧巢去，山山芳草青。"]', '诗', 'shi', '', NULL, '山雞 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06445bc-ad26-4e2f-8364-b3effc4c0a18', '孤鴈', '孤鴈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["昔年雙頡頏，池上靄春暉。","霄漢力猶怯，稻粱心已違。","蘆洲寒獨宿，榆塞夜孤飛。","不及營巢燕，西風相伴歸。"]', '["昔年雙頡頏，池上靄春暉。","霄漢力猶怯，稻粱心已違。","蘆洲寒独宿，榆塞夜孤飞。","不及營巢燕，西风相伴归。"]', '诗', 'shi', '', NULL, '孤鴈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f19cf9e-5a90-47ff-8a55-9f3a9db209f8', '寓懷', '寓懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南國浣紗伴，盈盈天下姝。","盤金明繡帶，動珮響羅襦。","素手怨瑤瑟，清心悲玉壺。","春華坐銷落，未忍泣蘼蕪。"]', '["南国浣紗伴，盈盈天下姝。","盤金明繡带，动珮响羅襦。","素手怨瑤瑟，清心悲玉壺。","春华坐銷落，未忍泣蘼蕪。"]', '诗', 'shi', '', NULL, '寓懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d62f99e9-ef65-448f-9930-7fdb06e4c06a', '洛中遊眺貽同志', '洛中游眺貽同志', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["康衢一望通，河洛正天中。","樓勢排高鳳，橋形架斷虹。","遠山晴帶雪，寒水晚多風。","幾日還攜手，鳥鳴花滿宮。"]', '["康衢一望通，河洛正天中。","楼勢排高鳳，橋形架斷虹。","远山晴带雪，寒水晚多风。","幾日還携手，鸟鳴花满宮。"]', '诗', 'shi', '', NULL, '洛中遊眺貽同志 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eda154d7-9bbf-4c0e-be4f-342c0e1128c7', '夏日戲題郭別駕東堂', '夏日戲題郭別駕东堂', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["微風起畫鸞，金翠暗珊珊。","晚樹垂朱實，春篁露粉竿。","散香蘄簟滑，沈水越瓶寒。","猶恐何郎熱，冰生白玉盤。"]', '["微风起畫鸾，金翠暗珊珊。","晚樹垂朱實，春篁露粉竿。","散香蘄簟滑，沈水越瓶寒。","猶恐何郎熱，冰生白玉盤。"]', '诗', 'shi', '', NULL, '夏日戲題郭別駕東堂 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e91c5f-14bf-48ee-ad1b-a4430e1a5e15', '長安旅夜', '长安旅夜', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["久客怨長夜，西風吹鴈聲。","雲移河漢淺，月泛露華清。","掩瑟獨凝思，緩歌空寄情。","門前有歸路，迢遰洛陽城。"]', '["久客怨长夜，西风吹鴈声。","云移河漢淺，月泛露华清。","掩瑟独凝思，緩歌空寄情。","门前有归路，迢遰洛陽城。"]', '诗', 'shi', '', NULL, '長安旅夜 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b87aaa-89cf-47f9-b711-534ec1c996c8', '鸂鶒', '鸂鶒', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["池寒柳復凋，獨宿夜迢迢。","雨頂冠應冷，風毛劒欲飄。","故巢迷碧水，舊侶越丹霄。","不是無歸處，心高多寂寥。"]', '["池寒柳复凋，独宿夜迢迢。","雨頂冠應冷，风毛劒欲飄。","故巢迷碧水，旧侶越丹霄。","不是無归处，心高多寂寥。"]', '诗', 'shi', '', NULL, '鸂鶒 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96facf2a-2d4b-4c7d-ae52-592710f0e8f9', '懿安皇太后挽歌詞', '懿安皇太后挽歌词', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["陵前春不盡，陵下夜何窮。","未信金蠶老，先驚玉燕空。","挽移蘭殿月，笳引柏城風。","自此隨龍馭，橋山翠靄中。"]', '["陵前春不尽，陵下夜何窮。","未信金蠶老，先驚玉燕空。","挽移蘭殿月，笳引柏城风。","自此隨龙馭，橋山翠靄中。"]', '诗', 'shi', '', NULL, '懿安皇太后挽歌詞 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7dd7ca6-3e1f-47ba-b5a0-09c950cf0ba2', '示弟', '示弟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["自爾出門去，淚痕長滿衣。","家貧爲客早，路遠得書稀。","文字何人賞，煙波幾日歸。","秋風正搖落，孤鴈又南飛。"]', '["自爾出门去，泪痕长满衣。","家貧爲客早，路远得书稀。","文字何人賞，煙波幾日归。","秋风正搖落，孤鴈又南飞。"]', '诗', 'shi', '', NULL, '示弟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3271f92-09a8-4fc5-93c4-6258d5ba2ea0', '送楊處士叔初卜居曲江', '送楊处士叔初卜居曲江', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["鴈門歸去遠，垂老脫袈裟。","蕭寺休爲客，曹溪便寄家。","綠琪千歲樹，黃槿四時花。","別怨應無限，門前桂水斜。"]', '["鴈门归去远，垂老脫袈裟。","蕭寺休爲客，曹溪便寄家。","綠琪千歲樹，黄槿四时花。","別怨應無限，门前桂水斜。"]', '诗', 'shi', '', NULL, '送楊處士叔初卜居曲江 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4935d66-666b-4003-8ad9-24879fdc118c', '發靈溪館', '發靈溪館', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山多水不窮，一葉似漁翁。","鳥浴寒潭雨，猿吟暮嶺風。","雜英垂錦繡，衆籟合絲桐。","應有曹溪路，千巖萬壑中。"]', '["山多水不窮，一葉似漁翁。","鸟浴寒潭雨，猿吟暮嶺风。","杂英垂錦繡，衆籟合絲桐。","應有曹溪路，千巖万壑中。"]', '诗', 'shi', '', NULL, '發靈溪館 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f894e67f-f9c3-4e7b-979d-00e8dabd743b', '題杜居士', '題杜居士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["松偃石牀平，何人識姓名。","溪冰寒棹響，巖雪夜窗明。","機盡心猿伏，神閑意馬行。","應知此來客，身世兩無情。"]', '["松偃石牀平，何人識姓名。","溪冰寒棹响，巖雪夜窗明。","機尽心猿伏，神闲意马行。","應知此来客，身世兩無情。"]', '诗', 'shi', '', NULL, '題杜居士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('925cae85-b045-4109-af8e-607819e6d254', '神女祠', '神女祠', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["停車祀聖女，涼葉下陰風。","龍氣石牀濕，鳥聲山廟空。","長眉留桂綠，丹臉寄蓮紅。","莫學陽臺畔，朝雲暮雨中。"]', '["停车祀聖女，涼葉下陰风。","龙氣石牀濕，鸟声山廟空。","长眉留桂綠，丹臉寄蓮紅。","莫学陽台畔，朝云暮雨中。"]', '诗', 'shi', '', NULL, '神女祠 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acee9d4-9c93-4139-aeda-cbd22d787387', '送李定言南遊', '送李定言南游', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["酒酣輕別恨，酒醒復離憂。","遠水應移棹，高峯更上樓。","簟涼清露夜，琴響碧天秋。","重惜芳尊宴，滿城無舊游。"]', '["酒酣轻別恨，酒醒复離憂。","远水應移棹，高峯更上楼。","簟涼清露夜，琴响碧天秋。","重惜芳尊宴，满城無旧游。"]', '诗', 'shi', '', NULL, '送李定言南遊 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5779c07f-80fc-414b-8dc6-76ee7c14b5cd', '早發中巖寺別契直上人', '早發中巖寺別契直上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蒼蒼松桂陰，殘月半西岑。","素壁寒燈暗，紅爐夜火深。","廚開山鼠散，鐘盡嶺猿吟。","行役方如此，逢師嬾話心。"]', '["蒼蒼松桂陰，殘月半西岑。","素壁寒灯暗，紅爐夜火深。","廚开山鼠散，鐘尽嶺猿吟。","行役方如此，逢師嬾話心。"]', '诗', 'shi', '', NULL, '早發中巖寺別契直上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa2fd24-3a53-4459-a2cb-a141d9343dfe', '行次潼關題驛後軒', '行次潼关題驛後軒', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["飛閣極層臺，終南此路回。","山形朝闕去，河勢抱關來。","鴈過秋風急，蟬鳴宿霧開。","平生無限意，驅馬任塵埃。"]', '["飞閣極層台，終南此路回。","山形朝闕去，河勢抱关来。","鴈過秋风急，蟬鳴宿霧开。","平生無限意，驱马任塵埃。"]', '诗', 'shi', '', NULL, '行次潼關題驛後軒 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9ef9f61-44e2-453d-8f46-809449fd3b85', '晨至南亭呈裴明府', '晨至南亭呈裴明府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南齋夢釣竿，晨起月猶殘。","露重螢依草，風高蝶委蘭。","池光秋鏡澈，山色曉屏寒。","更戀陶彭澤，無心議去官。"]', '["南斋梦釣竿，晨起月猶殘。","露重螢依草，风高蝶委蘭。","池光秋镜澈，山色晓屏寒。","更戀陶彭澤，無心議去官。"]', '诗', 'shi', '', NULL, '晨至南亭呈裴明府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3683ef45-e2e6-49d1-af4e-fcf55925b925', '灞東題司馬郊園', '灞东題司马郊园', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["楚翁秦塞住，昔事李輕車。","白社貧思橘，青門老仰瓜。","讀書三逕草，沽酒一籬花。","更欲尋芝朮，商山便寄家。"]', '["楚翁秦塞住，昔事李轻车。","白社貧思橘，青门老仰瓜。","读书三逕草，沽酒一籬花。","更欲尋芝朮，商山便寄家。"]', '诗', 'shi', '', NULL, '灞東題司馬郊園 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4112cb7e-bf6b-4476-becd-9392aec49d61', '游維山新興寺宿石屏村謝叟家', '游維山新兴寺宿石屏村謝叟家', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["晚過石屏村，村長日漸曛。","僧歸下嶺見，人語隔溪聞。","谷響寒耕雪，山明夜燒雲。","家家扣銅鼓，欲賽魯將軍。"]', '["晚過石屏村，村长日漸曛。","僧归下嶺见，人語隔溪闻。","谷响寒耕雪，山明夜燒云。","家家扣銅鼓，欲賽魯將軍。"]', '诗', 'shi', '', NULL, '游維山新興寺宿石屏村謝叟家 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c91cd2-10a8-4d62-8d03-4a5d73ccb3b6', '送從兄歸隱藍溪二首 一', '送從兄归隐藍溪二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["名高猶素衣，窮巷掩荆扉。","漸老故人少，久貧豪客稀。","塞雲橫劒望，山月抱琴歸。","幾日藍溪醉，藤花拂釣磯。"]', '["名高猶素衣，窮巷掩荆扉。","漸老故人少，久貧豪客稀。","塞云橫劒望，山月抱琴归。","幾日藍溪醉，藤花拂釣磯。"]', '诗', 'shi', '', NULL, '送從兄歸隱藍溪二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb58f507-ddc3-4bbd-be19-06d2889c88a3', '送從兄歸隱藍溪二首 二', '送從兄归隐藍溪二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["京洛多高蓋，憐兄劇斷蓬。","身隨一劒老，家入萬山空。","夜憶蕭關月，行悲易水風。","無人知此意，甘臥白雲中。"]', '["京洛多高蓋，怜兄劇斷蓬。","身隨一劒老，家入万山空。","夜憶蕭关月，行悲易水风。","無人知此意，甘臥白云中。"]', '诗', 'shi', '', NULL, '送從兄歸隱藍溪二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f9d8df6-46d6-44b2-9b7b-c6e2081702c9', '村舍', '村舍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["燕鴈下秋塘，田家自此忙。","移蔬通遠水，收果待繁霜。","野碓舂秔滑，山廚焙茗香。","客來還有酒，隨事宿茅堂。"]', '["燕鴈下秋塘，田家自此忙。","移蔬通远水，收果待繁霜。","野碓舂秔滑，山廚焙茗香。","客来還有酒，隨事宿茅堂。"]', '诗', 'shi', '', NULL, '村舍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac9288a2-ad21-45fc-8208-c449ed069dfe', '思歸', '思归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["疊嶂平蕪外，依依識舊邦。","氣高詩易怨，愁極酒難降。","樹暗支公院，山寒謝守窗。","殷勤樓下水，幾日到荆江。"]', '["叠嶂平蕪外，依依識旧邦。","氣高诗易怨，愁極酒难降。","樹暗支公院，山寒謝守窗。","殷勤楼下水，幾日到荆江。"]', '诗', 'shi', '', NULL, '思歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d728f52-c34d-433e-b22a-bf13d6380617', '晚泊七里灘', '晚泊七里灘', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["天晚日沈沈，歸舟繫柳陰。","江村平見寺，山郭遠聞砧。","樹密猿聲響，波澄鴈影深。","榮華暫時事，誰識子陵心。"]', '["天晚日沈沈，归舟繫柳陰。","江村平见寺，山郭远闻砧。","樹密猿声响，波澄鴈影深。","榮华暫时事，誰識子陵心。"]', '诗', 'shi', '', NULL, '晚泊七里灘 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91a79230-f568-44ab-825a-a57a4d3f00b0', '寄題南山王隱居', '寄題南山王隐居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["近逢商洛客，知爾住南塘。","草閣平春水，柴門掩夕陽。","隨蜂收野蜜，尋麝采生香。","更憶前年醉，松花滿石牀。"]', '["近逢商洛客，知爾住南塘。","草閣平春水，柴门掩夕陽。","隨蜂收野蜜，尋麝采生香。","更憶前年醉，松花满石牀。"]', '诗', 'shi', '', NULL, '寄題南山王隱居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b5251d-f467-4589-b268-1a12592369f3', '晨裝', '晨裝', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["帶月飯行侶，西游關塞長。","晨雞鳴遠戍，宿鴈起寒塘。","雲卷四山雪，風凝千樹霜。","誰家游俠子，沈醉臥蘭堂。"]', '["带月飯行侶，西游关塞长。","晨雞鳴远戍，宿鴈起寒塘。","云卷四山雪，风凝千樹霜。","誰家游俠子，沈醉臥蘭堂。"]', '诗', 'shi', '', NULL, '晨裝 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dae0e95-3506-4a0a-a9e8-53960ec35271', '題韋隱居西齋', '題韋隐居西斋', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["斸藥去還歸，家人半掩扉。","山風藤子落，溪雨豆花肥。","寺遠僧來少，橋危客到稀。","不聞砧杵動，應解製荷衣。"]', '["斸藥去還归，家人半掩扉。","山风藤子落，溪雨豆花肥。","寺远僧来少，橋危客到稀。","不闻砧杵动，應解製荷衣。"]', '诗', 'shi', '', NULL, '題韋隱居西齋 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c93792f9-5858-4a15-8ed6-ecd32441ecc9', '送李溟秀才西行', '送李溟秀才西行', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["萬里不辭勞，寒裝疊緼袍。","停車山店雨，挂席海門濤。","鷹勢暮偏急，鶴聲秋更高。","知君北邙路，留劒泣黃蒿。"]', '["万里不辞勞，寒裝叠緼袍。","停车山店雨，挂席海门濤。","鷹勢暮偏急，鹤声秋更高。","知君北邙路，留劒泣黄蒿。"]', '诗', 'shi', '', NULL, '送李溟秀才西行 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7390785-10d9-4bc3-9af9-70e3c774d9b9', '經馬鎮西宅', '經马鎮西宅', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["將軍久已沒，行客自興哀。","功業山長在，繁華水不回。","亂藤侵廢井，荒菊上叢臺。","借問此中事，幾家歌舞來。"]', '["將軍久已沒，行客自兴哀。","功業山长在，繁华水不回。","亂藤侵廢井，荒菊上叢台。","借问此中事，幾家歌舞来。"]', '诗', 'shi', '', NULL, '經馬鎮西宅 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85d58eb2-4f47-465d-a136-408cacf26ef9', '重遊鬱林寺道玄上人院', '重游鬱林寺道玄上人院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["藤杖叩松關，春溪斸藥還。","雨晴巢燕急，波暖浴鷗閑。","倚檻花臨水，回舟月照山。","憶歸師莫笑，書劒在人間。"]', '["藤杖叩松关，春溪斸藥還。","雨晴巢燕急，波暖浴鷗闲。","倚檻花臨水，回舟月照山。","憶归師莫笑，书劒在人间。"]', '诗', 'shi', '', NULL, '重遊鬱林寺道玄上人院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52dcd2d6-4257-4e42-b5e5-28b6d01415f0', '泛溪', '泛溪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["疑與武陵通，青溪碧嶂中。","水寒深見石，松晚靜聞風。","遯迹驅雞吏，冥心失馬翁。","纔應畢婚嫁，還此息微躬。"]', '["疑與武陵通，青溪碧嶂中。","水寒深见石，松晚静闻风。","遯迹驱雞吏，冥心失马翁。","纔應畢婚嫁，還此息微躬。"]', '诗', 'shi', '', NULL, '泛溪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e2b23d0-14e2-4055-a8d2-a9f4ed90fe72', '送樓煩李別駕', '送楼煩李別駕', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["琴清詩思勞，更欲學龍韜。","王粲暫停筆，呂虔初佩刀。","夜吟關月靜，秋望塞雲高。","去去從軍樂，鵰飛代馬豪。"]', '["琴清诗思勞，更欲学龙韜。","王粲暫停笔，呂虔初佩刀。","夜吟关月静，秋望塞云高。","去去從軍乐，鵰飞代马豪。"]', '诗', 'shi', '', NULL, '送樓煩李別駕 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee7dc17-e38c-4756-885f-1d7c422cf46a', '聞兩河用兵因貽友人', '闻兩河用兵因貽友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故人日已遠，身事與誰論。","性拙難趨世，心孤易感恩。","秋悲憐宋玉，夜舞笑劉琨。","徒有干時策，青山尚掩門。"]', '["故人日已远，身事與誰論。","性拙难趨世，心孤易感恩。","秋悲怜宋玉，夜舞笑劉琨。","徒有干时策，青山尚掩门。"]', '诗', 'shi', '', NULL, '聞兩河用兵因貽友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d726f81-2211-4151-9bb4-6f59bbac3361', '獻白尹', '獻白尹', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["醉舞任生涯，褐寬烏帽斜。","庾公先在郡，疎傅早還家。","林晚鳥爭樹，園春蜂護花。","高吟應更逸，嵩洛舊煙霞。"]', '["醉舞任生涯，褐寬烏帽斜。","庾公先在郡，疎傅早還家。","林晚鸟爭樹，园春蜂護花。","高吟應更逸，嵩洛旧煙霞。"]', '诗', 'shi', '', NULL, '獻白尹 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93db053-2961-48be-86b9-0756a74ab797', '茅山贈梁尊師', '茅山贈梁尊師', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲屋何年客，青山白日長。","種花春掃雪，看籙夜焚香。","上象壺中闊，平生夢裏忙。","幸承仙籍後，乞取大還方。"]', '["云屋何年客，青山白日长。","種花春掃雪，看籙夜焚香。","上象壺中闊，平生梦裏忙。","幸承仙籍後，乞取大還方。"]', '诗', 'shi', '', NULL, '茅山贈梁尊師 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eddec6b2-bcd2-454b-939a-b4165317282e', '聞薛先輩陪大夫看早梅因寄', '闻薛先輩陪大夫看早梅因寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["澗梅寒正發，莫信笛中吹。","素豔雪凝樹，清香風滿枝。","折驚山鳥散，攜任野蜂隨。","今日從公醉，何人倒接䍦。"]', '["澗梅寒正發，莫信笛中吹。","素豔雪凝樹，清香风满枝。","折驚山鸟散，携任野蜂隨。","今日從公醉，何人倒接䍦。"]', '诗', 'shi', '', NULL, '聞薛先輩陪大夫看早梅因寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7843035d-54ca-495e-a134-799205580a0a', '送前緱氏韋明府南游', '送前緱氏韋明府南游', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["酒闌橫劒歌，日暮望關河。","道直去官早，家貧爲客多。","山昏函谷雨，木落洞庭波。","莫盡遠游興，故園荒薜蘿。"]', '["酒闌橫劒歌，日暮望关河。","道直去官早，家貧爲客多。","山昏函谷雨，木落洞庭波。","莫尽远游兴，故园荒薜蘿。"]', '诗', 'shi', '', NULL, '送前緱氏韋明府南游 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae58fed-90b3-4662-b9a4-728c392f97dc', '看雪', '看雪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["松亞竹珊珊，心知萬井歡。","山明迷舊徑，溪滿漲新瀾。","客醉瑤臺曙，兵防玉塞寒。","紅樓知有酒，誰肯學袁安。"]', '["松亞竹珊珊，心知万井歡。","山明迷旧徑，溪满漲新瀾。","客醉瑤台曙，兵防玉塞寒。","紅楼知有酒，誰肯学袁安。"]', '诗', 'shi', '', NULL, '看雪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b99c5e-e0da-49f3-b293-d71c5b404e8f', '贈僧', '贈僧', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["心法本無住，流沙歸復來。","錫隨山鳥動，經附海船回。","洗足柳遮寺，坐禪花委苔。","唯將一童子，又欲上天台。"]', '["心法本無住，流沙归复来。","錫隨山鸟动，經附海船回。","洗足柳遮寺，坐禪花委苔。","唯將一童子，又欲上天台。"]', '诗', 'shi', '', NULL, '贈僧 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08824232-c3d6-4670-81a4-59fab9a554b4', '趨慈和寺移宴', '趨慈和寺移宴', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高寺移清宴，漁舟繫綠蘿。","潮平秋水闊，雲歛暮山多。","廣檻停簫鼓，繁弦散綺羅。","西樓半牀月，莫問夜如何。"]', '["高寺移清宴，漁舟繫綠蘿。","潮平秋水闊，云歛暮山多。","廣檻停簫鼓，繁弦散綺羅。","西楼半牀月，莫问夜如何。"]', '诗', 'shi', '', NULL, '趨慈和寺移宴 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8170d0-81ea-4583-8484-c10f60fb8a3d', '留贈偃師主人', '留贈偃師主人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["孤城漏未殘，徒侶拂征鞍。","洛北去游遠，淮南歸夢闌。","曉燈回壁暗，晴雪卷簾寒。","強盡主人酒，出門行路難。"]', '["孤城漏未殘，徒侶拂征鞍。","洛北去游远，淮南归梦闌。","晓灯回壁暗，晴雪卷簾寒。","強尽主人酒，出门行路难。"]', '诗', 'shi', '', NULL, '留贈偃師主人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52115b43-aaab-4d61-b404-0d43dedef0dc', '送南陵李少府', '送南陵李少府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["高人亦未閑，來往楚雲間。","劒在心應壯，書窮鬢已斑。","落帆秋水寺，驅馬夕陽山。","明日南昌尉，空齋又掩關。"]', '["高人亦未闲，来往楚云间。","劒在心應壯，书窮鬢已斑。","落帆秋水寺，驱马夕陽山。","明日南昌尉，空斋又掩关。"]', '诗', 'shi', '', NULL, '送南陵李少府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a40be5-cd3b-498a-829d-452aaebd6d70', '別韋處士', '別韋处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南北斷蓬飛，別多相見稀。","更傷今日酒，未換昔年衣。","舊友幾人在，故鄉何處歸？","秦原向西路，雲晚雪霏霏。"]', '["南北斷蓬飞，別多相见稀。","更傷今日酒，未換昔年衣。","旧友幾人在，故乡何处归？","秦原向西路，云晚雪霏霏。"]', '诗', 'shi', '', NULL, '別韋處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e174911d-3ccf-46fe-ba9c-7c815fb842dc', '九日登樟亭驛樓', '九日登樟亭驛楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["鱸鱠與蒪羹，西風片席輕。","潮回孤島晚，雲歛衆山晴。","丹羽下高閣，黃花垂古城。","因秋倍多感，鄉樹接咸京。"]', '["鱸鱠與蒪羹，西风片席轻。","潮回孤島晚，云歛衆山晴。","丹羽下高閣，黄花垂古城。","因秋倍多感，乡樹接咸京。"]', '诗', 'shi', '', NULL, '九日登樟亭驛樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f7e42b-1b55-4bc1-806d-6bff4553d3fd', '再遊越中傷朱餘慶協律好直上人', '再游越中傷朱餘慶協律好直上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["昔年湖上客，留訪雪山翁。","王氏船猶在，蕭家寺已空。","月高花有露，煙合水無風。","處處多遺韻，何曾入剡中。"]', '["昔年湖上客，留訪雪山翁。","王氏船猶在，蕭家寺已空。","月高花有露，煙合水無风。","处处多遺韻，何曾入剡中。"]', '诗', 'shi', '', NULL, '再遊越中傷朱餘慶協律好直上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e75685d9-1b7a-47b9-a61c-626f0295dcaf', '京口津亭送張崔二侍御', '京口津亭送張崔二侍御', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["愛樹滿西津，津亭墮淚頻。","素車應度洛，珠履更歸秦。","水接三湘暮，山通五嶺春。","傷離與懷舊，明日白頭人。"]', '["愛樹满西津，津亭墮泪頻。","素车應度洛，珠履更归秦。","水接三湘暮，山通五嶺春。","傷離與懷旧，明日白头人。"]', '诗', 'shi', '', NULL, '京口津亭送張崔二侍御 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f569440d-43b1-4550-b457-6db79ec5517e', '江樓夜別', '江楼夜別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["離別奈情何，江樓凝豔歌。","蕙蘭秋露重，蘆葦夜風多。","深怨寄清瑟，遠愁生翠蛾。","酒酣相顧起，明月棹寒波。"]', '["離別奈情何，江楼凝豔歌。","蕙蘭秋露重，蘆葦夜风多。","深怨寄清瑟，远愁生翠蛾。","酒酣相顧起，明月棹寒波。"]', '诗', 'shi', '', NULL, '江樓夜別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64534330-2243-4baf-ba90-86dfc324761a', '送惟素上人歸新安', '送惟素上人归新安', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山空葉復落，一逕下新安。","風急渡溪晚，雪晴歸寺寒。","尋雲策藤杖，向日倚蒲團。","寧憶西游客，勞勞歌路難。"]', '["山空葉复落，一逕下新安。","风急渡溪晚，雪晴归寺寒。","尋云策藤杖，向日倚蒲團。","寧憶西游客，勞勞歌路难。"]', '诗', 'shi', '', NULL, '送惟素上人歸新安 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa790d33-c9ed-40bf-8ae0-f1071d003bdc', '霅上宴別', '霅上宴別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山斷水茫茫，洛人西路長。","笙歌留遠棹，風雨寄華堂。","紅壁耿秋燭，翠簾凝曉香。","誰堪從此去，雲樹滿陵陽。"]', '["山斷水茫茫，洛人西路长。","笙歌留远棹，风雨寄华堂。","紅壁耿秋燭，翠簾凝晓香。","誰堪從此去，云樹满陵陽。"]', '诗', 'shi', '', NULL, '霅上宴別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a51616d-dabb-4327-8917-1f66187b5277', '下第別友人楊至之', '下第別友人楊至之', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["花落水潺潺，十年離舊山。","夜愁添白髮，春淚減朱顏。","孤劒北游塞，遠書東出關。","逢君話心曲，一醉灞陵間。"]', '["花落水潺潺，十年離旧山。","夜愁添白髮，春泪減朱顏。","孤劒北游塞，远书东出关。","逢君話心曲，一醉灞陵间。"]', '诗', 'shi', '', NULL, '下第別友人楊至之 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e8a43db-d4c8-4bc5-b962-80b94004ceba', '尋戴處士', '尋戴处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["車馬長安道，誰知大隱心。","蠻僧留古鏡，蜀客寄新琴。","曬藥竹齋暖，擣茶松院深。","思君一相訪，殘雪似山陰。"]', '["车马长安道，誰知大隐心。","蠻僧留古镜，蜀客寄新琴。","曬藥竹斋暖，擣茶松院深。","思君一相訪，殘雪似山陰。"]', '诗', 'shi', '', NULL, '尋戴處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5bec487-a3df-469c-a069-b8d2ce92074b', '放猿', '放猿', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["殷勤解金鎖，昨夜雨淒淒。","山淺憶巫峽，水寒思建溪。","遠尋紅樹宿，深向白雲啼。","好覓來時路，煙蘿莫共迷。"]', '["殷勤解金鎖，昨夜雨淒淒。","山淺憶巫峽，水寒思建溪。","远尋紅樹宿，深向白云啼。","好覓来时路，煙蘿莫共迷。"]', '诗', 'shi', '', NULL, '放猿 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b208bff-3a2e-48a1-bbaf-c5c9cba720d6', '將離郊園留示弟姪', '將離郊园留示弟姪', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["身賤與心違，秋風生旅衣。","久貧辭國遠，多病在家稀。","山暝客初散，樹涼人未歸。","西都萬餘里，明旦別柴扉。"]', '["身賤與心違，秋风生旅衣。","久貧辞国远，多病在家稀。","山暝客初散，樹涼人未归。","西都万餘里，明旦別柴扉。"]', '诗', 'shi', '', NULL, '將離郊園留示弟姪 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b594270e-32d5-4cc7-bd15-05bb17ea198e', '夜歸丁卯橋村舍', '夜归丁卯橋村舍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["月涼風靜夜，歸客泊巖前。","橋響犬遙吠，庭空人散眠。","紫蒲低水檻，紅葉半江船。","自有還家計，南湖二頃田。"]', '["月涼风静夜，归客泊巖前。","橋响犬遙吠，庭空人散眠。","紫蒲低水檻，紅葉半江船。","自有還家計，南湖二頃田。"]', '诗', 'shi', '', NULL, '夜歸丁卯橋村舍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62b0d58-fa1d-4473-af0d-7cd2311ee658', '題青山館', '題青山館', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["昔人詩酒地，芳草思王孫。","白水半塘岸，青山橫郭門。","懸巖碑已折，盤石井猶存。","無處繼行樂，野花空一尊。"]', '["昔人诗酒地，芳草思王孫。","白水半塘岸，青山橫郭门。","懸巖碑已折，盤石井猶存。","無处繼行乐，野花空一尊。"]', '诗', 'shi', '', NULL, '題青山館 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64924211-3ff5-4000-a085-94e5792e8fa5', '秋日衆哲館對竹', '秋日衆哲館对竹', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蕭蕭凌雪霜，濃翠異三湘。","疎影月移壁，寒聲風滿堂。","捲簾秋更早，高枕夜偏長。","忽憶秦溪路，萬竿今正涼。"]', '["蕭蕭凌雪霜，濃翠異三湘。","疎影月移壁，寒声风满堂。","捲簾秋更早，高枕夜偏长。","忽憶秦溪路，万竿今正涼。"]', '诗', 'shi', '', NULL, '秋日衆哲館對竹 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e3f0315-9583-4fa9-8370-6c24ef2ca34d', '春日題韋曲野老村舍二首 一', '春日題韋曲野老村舍二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["遶屋遍桑麻，村南第一家。","林繁樹勢直，溪轉水紋斜。","竹院晝看筍，藥欄春賣花。","故園歸未得，到此是天涯。"]', '["遶屋遍桑麻，村南第一家。","林繁樹勢直，溪轉水紋斜。","竹院晝看筍，藥欄春賣花。","故园归未得，到此是天涯。"]', '诗', 'shi', '', NULL, '春日題韋曲野老村舍二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ffe075-391f-4beb-9bde-be14f35decbf', '春日題韋曲野老村舍二首 二', '春日題韋曲野老村舍二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["北嶺枕南塘，數家村落長。","鶯啼幼婦嬾，蠶出小姑忙。","煙草近溝濕，風花臨路香。","自憐非楚客，春望亦心傷。"]', '["北嶺枕南塘，數家村落长。","鶯啼幼婦嬾，蠶出小姑忙。","煙草近溝濕，风花臨路香。","自怜非楚客，春望亦心傷。"]', '诗', 'shi', '', NULL, '春日題韋曲野老村舍二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82bfa4c6-3b4b-46ba-b11e-08e18a922b60', '崇聖寺別楊至之', '崇聖寺別楊至之', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蕭寺暫相逢，離憂滿病容。","寒齋秋少燕，陰壁夜多蛩。","樹暗水千里，山深雲萬重。","懷君在書信，莫過鴈回峯。"]', '["蕭寺暫相逢，離憂满病容。","寒斋秋少燕，陰壁夜多蛩。","樹暗水千里，山深云万重。","懷君在书信，莫過鴈回峯。"]', '诗', 'shi', '', NULL, '崇聖寺別楊至之 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d70f6a6-abed-4cfc-9785-731b1b2ee812', '途經李翰林墓', '途經李翰林墓', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["氣逸何人識，才高舉世疑。","禰生狂善賦，陶令醉能詩。","碧水鱸魚思，青山鵩鳥悲。","至今孤塚在，荆棘楚江湄。"]', '["氣逸何人識，才高舉世疑。","禰生狂善賦，陶令醉能诗。","碧水鱸鱼思，青山鵩鸟悲。","至今孤塚在，荆棘楚江湄。"]', '诗', 'shi', '', NULL, '途經李翰林墓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c83eb0b6-daca-4a7c-8904-e5d2d15a5479', '嚴陵釣臺貽行侶', '嚴陵釣台貽行侶', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故人天下定，垂釣碧巖幽。","舊跡隨臺古，高名寄水流。","鳥喧羣木晚，蟬急衆山秋。","更待新安月，憑君暫駐舟。"]', '["故人天下定，垂釣碧巖幽。","旧跡隨台古，高名寄水流。","鸟喧羣木晚，蟬急衆山秋。","更待新安月，憑君暫駐舟。"]', '诗', 'shi', '', NULL, '嚴陵釣臺貽行侶 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b29b89-63cc-48fa-8c07-7eb3995d658f', '南樓春望', '南楼春望', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南樓春一望，雲水共昏昏。","野店歸山路，危橋帶郭村。","晴煙和草色，夜雨長溪痕。","下岸誰家住，殘陽半掩門。"]', '["南楼春一望，云水共昏昏。","野店归山路，危橋带郭村。","晴煙和草色，夜雨长溪痕。","下岸誰家住，殘陽半掩门。"]', '诗', 'shi', '', NULL, '南樓春望 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1b6e3cd-f5d1-4d41-8808-44960fd345ad', '送無夢道人先歸甘露寺', '送無梦道人先归甘露寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["飄飄隨晚浪，杯影入鷗羣。","岸凍千船雪，巖陰一寺雲。","夜燈江北見，寒磬水西聞。","鶴嶺煙霞在，歸期不羨君。"]', '["飄飄隨晚浪，杯影入鷗羣。","岸凍千船雪，巖陰一寺云。","夜灯江北见，寒磬水西闻。","鹤嶺煙霞在，归期不羨君。"]', '诗', 'shi', '', NULL, '送無夢道人先歸甘露寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3722838-827a-4595-9ced-c7f0c4afcb92', '閑居孟夏即事', '闲居孟夏即事', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠樹蔭青苔，柴門臨水開。","簟涼初熟麥，枕膩乍經梅。","魚躍海風起，鼉鳴江雨來。","佳人竟何處，日夕上樓臺。"]', '["綠樹蔭青苔，柴门臨水开。","簟涼初熟麦，枕膩乍經梅。","鱼躍海风起，鼉鳴江雨来。","佳人竟何处，日夕上楼台。"]', '诗', 'shi', '', NULL, '閑居孟夏即事 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35a7b4a1-7173-40de-b5d2-c1cea2893e4c', '題灞西駱隱士', '題灞西駱隐士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["磻溪連灞水，商嶺接秦山。","青漢不回駕，白雲長掩關。","雀喧知鶴靜，鳧戲識鷗閑。","却笑南昌尉，悠悠城市間。"]', '["磻溪連灞水，商嶺接秦山。","青漢不回駕，白云长掩关。","雀喧知鹤静，鳧戲識鷗闲。","却笑南昌尉，悠悠城市间。"]', '诗', 'shi', '', NULL, '題灞西駱隱士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bafc5477-4e0d-4f6b-b111-db86d0b48d39', '溪亭二首 一', '溪亭二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["溪亭四面山，橫柳半溪灣。","蟬響螳螂急，魚深翡翠閑。","水寒留客醉，月上與僧還。","猶戀蕭蕭竹，西齋未掩關。"]', '["溪亭四面山，橫柳半溪灣。","蟬响螳螂急，鱼深翡翠闲。","水寒留客醉，月上與僧還。","猶戀蕭蕭竹，西斋未掩关。"]', '诗', 'shi', '', NULL, '溪亭二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfbcc91f-a55a-4549-8899-eb5ebca01489', '溪亭二首 二', '溪亭二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["暖枕眠溪柳，僧齋昨夜期。","茶香秋夢後，松韻晚吟時。","共戲魚翻藻，爭棲鳥墜枝。","重陽應一醉，栽菊助東籬。"]', '["暖枕眠溪柳，僧斋昨夜期。","茶香秋梦後，松韻晚吟时。","共戲鱼翻藻，爭棲鸟墜枝。","重陽應一醉，栽菊助东籬。"]', '诗', 'shi', '', NULL, '溪亭二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('292c14cd-151f-4321-a94c-46fc86693eb3', '秋日赴闕題潼關驛樓', '秋日赴闕題潼关驛楼', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["紅葉晚蕭蕭，長亭酒一瓢。","殘雲歸太華，疎雨過中條。","樹色隨山迥，河聲入海遙。","帝鄉明日到，猶自夢漁樵。"]', '["紅葉晚蕭蕭，长亭酒一瓢。","殘云归太华，疎雨過中條。","樹色隨山迥，河声入海遙。","帝乡明日到，猶自梦漁樵。"]', '诗', 'shi', '', NULL, '秋日赴闕題潼關驛樓 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02e478c-589f-4ce4-b682-6cec1573dc1b', '吳門送客早發', '吳门送客早發', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["吳歌咽深思，楚客怨歸程。","寺曉樓臺迥，江秋管吹清。","早潮低水檻，殘月下山城。","惆悵回舟日，湘南春草生。"]', '["吳歌咽深思，楚客怨归程。","寺晓楼台迥，江秋管吹清。","早潮低水檻，殘月下山城。","惆悵回舟日，湘南春草生。"]', '诗', 'shi', '', NULL, '吳門送客早發 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57515fd-9841-4bf1-b949-bf171705c4ca', '送太昱禪師', '送太昱禪師', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["禪牀深竹裏，心與徑山期。","結社多高客，登壇盡小師。","早秋歸寺遠，新雨上灘遲。","別後江雲碧，南齋一首詩。"]', '["禪牀深竹裏，心與徑山期。","結社多高客，登壇尽小師。","早秋归寺远，新雨上灘遲。","別後江云碧，南斋一首诗。"]', '诗', 'shi', '', NULL, '送太昱禪師 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('224486d6-50d2-4c4e-968c-867aa36b2dd2', '旅懷', '旅懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["征車何軋軋，南北極天涯。","孤枕易爲客，遠書難到家。","鄉連雲外樹，城閉月中花。","猶有扁舟思，前年別若耶。"]', '["征车何軋軋，南北極天涯。","孤枕易爲客，远书难到家。","乡連云外樹，城閉月中花。","猶有扁舟思，前年別若耶。"]', '诗', 'shi', '', NULL, '旅懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8002dd4f-2224-4acc-8d4a-f1ff73ad75d2', '南亭與首公讌集', '南亭與首公讌集', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["秋來水上亭，幾處似巖扃。","戲鳥翻江葉，游龜帶綠萍。","管弦心戚戚，羅綺鬢星星。","行樂非吾事，西齋尚有螢。"]', '["秋来水上亭，幾处似巖扃。","戲鸟翻江葉，游龟带綠萍。","管弦心戚戚，羅綺鬢星星。","行乐非吾事，西斋尚有螢。"]', '诗', 'shi', '', NULL, '南亭與首公讌集 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0d24ca-2be7-4404-9256-365c9895c11a', '早發壽安次永壽渡', '早發壽安次永壽渡', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["東西車馬塵，鞏洛與咸秦。","山月夜行客，水煙朝渡人。","樹涼風皓皓，灘淺石磷磷。","會待功名就，扁舟寄此身。"]', '["东西车马塵，鞏洛與咸秦。","山月夜行客，水煙朝渡人。","樹涼风皓皓，灘淺石磷磷。","會待功名就，扁舟寄此身。"]', '诗', 'shi', '', NULL, '早發壽安次永壽渡 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97392a14-7813-463e-b6e6-2e08a9935fd4', '泊松江渡', '泊松江渡', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["漠漠故宮地，月涼風露幽。","雞鳴荒戍曉，鴈過古城秋。","楊柳北歸路，蒹葭南渡舟。","去鄉今已遠，更上望京樓。"]', '["漠漠故宮地，月涼风露幽。","雞鳴荒戍晓，鴈過古城秋。","楊柳北归路，蒹葭南渡舟。","去乡今已远，更上望京楼。"]', '诗', 'shi', '', NULL, '泊松江渡 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec5cc11-be31-4e2a-ac72-b39b64d9fc4e', '送魚思別處士歸有懷', '送鱼思別处士归有懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["宴罷衆賓散，長歌攜一巵。","溪亭相送遠，山郭獨歸遲。","風檻夕雲散，月軒寒露滋。","病來雙鬢白，不是舊離時。"]', '["宴罷衆賓散，长歌携一巵。","溪亭相送远，山郭独归遲。","风檻夕云散，月軒寒露滋。","病来雙鬢白，不是旧離时。"]', '诗', 'shi', '', NULL, '送魚思別處士歸有懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1780ff68-d310-4276-a966-e2bd6c80817a', '重經姑蘇懷古二首 一', '重經姑蘇懷古二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["越兵驅綺羅，越女唱吳歌。","宮盡燕聲少，臺荒麋跡多。","茱萸垂曉露，菡萏落秋波。","無復君王醉，滿城顰翠蛾。"]', '["越兵驱綺羅，越女唱吳歌。","宮尽燕声少，台荒麋跡多。","茱萸垂晓露，菡萏落秋波。","無复君王醉，满城顰翠蛾。"]', '诗', 'shi', '', NULL, '重經姑蘇懷古二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3146b0b3-5192-4ec2-b0c1-591da35cb6fc', '重經姑蘇懷古二首 二', '重經姑蘇懷古二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["香逕遶吳宮，千帆落照中。","鸛鳴山欲雨，魚躍水多風。","城帶晚莎綠，池連秋蓼紅。","當年國門外，誰識伍員忠。"]', '["香逕遶吳宮，千帆落照中。","鸛鳴山欲雨，鱼躍水多风。","城带晚莎綠，池連秋蓼紅。","當年国门外，誰識伍員忠。"]', '诗', 'shi', '', NULL, '重經姑蘇懷古二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917c409c-9e63-45af-9052-9a5190c2a5c9', '將赴京師留題孫處士山居二首 一', '將赴京師留題孫处士山居二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["草堂近西郭，遙對敬亭開。","枕膩海雲起，簟涼山雨來。","高歌懷地肺，遠賦憶天台。","應學相如志，終須駟馬回。"]', '["草堂近西郭，遙对敬亭开。","枕膩海云起，簟涼山雨来。","高歌懷地肺，远賦憶天台。","應学相如志，終須駟马回。"]', '诗', 'shi', '', NULL, '將赴京師留題孫處士山居二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c1c18c-d0c1-4e96-ba26-37ddfc3828b1', '將赴京師留題孫處士山居二首 二', '將赴京師留題孫处士山居二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西巖有高興，路僻幾人知。","松蔭花開晚，山寒酒熟遲。","游從隨野鶴，休息遇靈龜。","長見鄰翁說，容華似舊時。"]', '["西巖有高兴，路僻幾人知。","松蔭花开晚，山寒酒熟遲。","游從隨野鹤，休息遇靈龟。","长见鄰翁说，容华似旧时。"]', '诗', 'shi', '', NULL, '將赴京師留題孫處士山居二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db201840-8273-4d1d-a365-f5ab532cb5e2', '下第寓居崇聖寺感事', '下第寓居崇聖寺感事', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["懷土泣京華，舊山歸路賒。","靜依禪客院，幽學野人家。","林晚鳥爭樹，園春蝶護花。","東門有閑地，誰種邵平瓜。"]', '["懷土泣京华，旧山归路賒。","静依禪客院，幽学野人家。","林晚鸟爭樹，园春蝶護花。","东门有闲地，誰種邵平瓜。"]', '诗', 'shi', '', NULL, '下第寓居崇聖寺感事 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad092f9-fb3d-4df3-a94d-319a018591b4', '曉發天井關寄李師晦', '晓發天井关寄李師晦', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山在水滔滔，流年欲二毛。","湘潭歸夢遠，燕趙客程勞。","露曉紅蘭重，雲晴碧樹高。","逢秋正多感，萬里別同袍。"]', '["山在水滔滔，流年欲二毛。","湘潭归梦远，燕趙客程勞。","露晓紅蘭重，云晴碧樹高。","逢秋正多感，万里別同袍。"]', '诗', 'shi', '', NULL, '曉發天井關寄李師晦 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1fcea5-5eae-440c-9ac0-a19b8ef54797', '喜遠書', '喜远书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["端居換時節，離恨隔龍瀧。","苔色上春閣，柳陰移晚窗。","寄懷因桂水，流淚極楓江。","此日南來使，金盤魚一雙。"]', '["端居換时節，離恨隔龙瀧。","苔色上春閣，柳陰移晚窗。","寄懷因桂水，流泪極楓江。","此日南来使，金盤鱼一雙。"]', '诗', 'shi', '', NULL, '喜遠書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71e82353-6624-4fc3-9266-929715c33939', '懷江南同志', '懷江南同志', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南國別經年，雲晴波接天。","蒲深鸂鶒戲，花暖鷓鴣眠。","竹暗湘妃廟，楓陰楚客船。","唯應洞庭月，萬里共嬋娟。"]', '["南国別經年，云晴波接天。","蒲深鸂鶒戲，花暖鷓鴣眠。","竹暗湘妃廟，楓陰楚客船。","唯應洞庭月，万里共嬋娟。"]', '诗', 'shi', '', NULL, '懷江南同志 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba418a8-d57c-4614-9293-d5022c332af7', '洛中秋日', '洛中秋日', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故國無歸處，官閑憶遠遊。","吳僧秣陵寺，楚客洞庭舟。","久病先知雨，長貧早覺秋。","壯心能幾許，伊水更東流。"]', '["故国無归处，官闲憶远游。","吳僧秣陵寺，楚客洞庭舟。","久病先知雨，长貧早覺秋。","壯心能幾許，伊水更东流。"]', '诗', 'shi', '', NULL, '洛中秋日 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0501d2f2-fccc-45d1-8320-5b4c8a3ccc70', '將赴京師蒜山津送客還荆渚', '將赴京師蒜山津送客還荆渚', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["尊前萬里愁，楚塞與皇州。","雲識瀟湘雨，風知鄠杜秋。","潮平猶倚棹，月上更登樓。","他日滄浪水，漁歌對白頭。"]', '["尊前万里愁，楚塞與皇州。","云識瀟湘雨，风知鄠杜秋。","潮平猶倚棹，月上更登楼。","他日滄浪水，漁歌对白头。"]', '诗', 'shi', '', NULL, '將赴京師蒜山津送客還荆渚 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e49e4df5-f884-4ba2-bb01-9dd8e6d21762', '潼關蘭若', '潼关蘭若', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["來往幾經過，前軒枕大河。","遠帆春水闊，高寺夕陽多。","蝶影下紅藥，鳥聲喧綠蘿。","故山歸未得，徒詠採芝歌。"]', '["来往幾經過，前軒枕大河。","远帆春水闊，高寺夕陽多。","蝶影下紅藥，鸟声喧綠蘿。","故山归未得，徒詠採芝歌。"]', '诗', 'shi', '', NULL, '潼關蘭若 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ecfdff1-9784-4be0-8201-02eee3d7fe11', '翫殘雪寄江南尹劉大夫', '翫殘雪寄江南尹劉大夫', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["豔陽無處避，皎潔不成容。","素質添瑤水，清光散玉峯。","眠鷗猶戀草，棲鶴未離松。","聞在金鑾望，羣仙對九重。"]', '["豔陽無处避，皎潔不成容。","素質添瑤水，清光散玉峯。","眠鷗猶戀草，棲鹤未離松。","闻在金鑾望，羣仙对九重。"]', '诗', 'shi', '', NULL, '翫殘雪寄江南尹劉大夫 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acbc4e8-85af-412f-9e6e-e9dfa2e9ad07', '陪越中使院諸公鏡波館餞明台裴鄭二使君', '陪越中使院諸公镜波館餞明台裴鄭二使君', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["傾幕來華館，淹留二使君。","舞移清夜月，歌斷碧空雲。","海郡樓臺接，江船劒戟分。","明時自騫翥，無復歎離羣。"]', '["傾幕来华館，淹留二使君。","舞移清夜月，歌斷碧空云。","海郡楼台接，江船劒戟分。","明时自騫翥，無复歎離羣。"]', '诗', 'shi', '', NULL, '陪越中使院諸公鏡波館餞明台裴鄭二使君 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8771a9-82fa-4d35-85c0-970ab7ebad8d', '春泊弋陽', '春泊弋陽', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江行春欲半，孤枕弋陽堤。","雲暗猶飄雪，潮寒未應溪。","飲猿聞棹散，飛鳥背船低。","此路成幽絕，家山鞏洛西。"]', '["江行春欲半，孤枕弋陽堤。","云暗猶飄雪，潮寒未應溪。","饮猿闻棹散，飞鸟背船低。","此路成幽絕，家山鞏洛西。"]', '诗', 'shi', '', NULL, '春泊弋陽 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('209079c5-08ba-4a9f-9c64-f055b5b4242f', '晨別翛然上人', '晨別翛然上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["吳僧誦經罷，敗衲倚蒲團。","鐘韻花猶歛，樓陰月向殘。","晴山開殿響，秋水捲簾寒。","獨恨孤舟去，千灘復萬灘。"]', '["吳僧誦經罷，敗衲倚蒲團。","鐘韻花猶歛，楼陰月向殘。","晴山开殿响，秋水捲簾寒。","独恨孤舟去，千灘复万灘。"]', '诗', 'shi', '', NULL, '晨別翛然上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0c24ab-2d9e-4ad8-aaf7-007c63f6f436', '送客江行', '送客江行', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蕭蕭蘆荻花，郢客獨辭家。","遠棹依山響，危檣轉浦斜。","水寒澄淺石，潮落漲虛沙。","莫與征徒望，鄉園去漸賒。"]', '["蕭蕭蘆荻花，郢客独辞家。","远棹依山响，危檣轉浦斜。","水寒澄淺石，潮落漲虛沙。","莫與征徒望，乡园去漸賒。"]', '诗', 'shi', '', NULL, '送客江行 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ccee73e-3244-44fe-9d43-20c505ddded4', '將歸塗口宿鬱林寺道玄上人院二首 一', '將归塗口宿鬱林寺道玄上人院二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西巖一磬長，僧起樹蒼蒼。","開殿灑寒水，誦經焚晚香。","竹風雲漸散，杉露月猶光。","無復重來此，歸舟凌夕陽。"]', '["西巖一磬长，僧起樹蒼蒼。","开殿灑寒水，誦經焚晚香。","竹风云漸散，杉露月猶光。","無复重来此，归舟凌夕陽。"]', '诗', 'shi', '', NULL, '將歸塗口宿鬱林寺道玄上人院二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ad002b-2a7a-4af3-bb8d-827344c43a03', '將歸塗口宿鬱林寺道玄上人院二首 二', '將归塗口宿鬱林寺道玄上人院二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["春尋採藥翁，歸路宿禪宮。","雲起客眠處，月殘僧定中。","藤花深洞水，槲葉滿山風。","清境不能住，朝朝慙遠公。"]', '["春尋採藥翁，归路宿禪宮。","云起客眠处，月殘僧定中。","藤花深洞水，槲葉满山风。","清境不能住，朝朝慙远公。"]', '诗', 'shi', '', NULL, '將歸塗口宿鬱林寺道玄上人院二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac5f393-1297-4d29-98be-df08f1e75332', '題宣州元處士幽居', '題宣州元处士幽居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["潺湲遶門水，未省濯纓塵。","鳥散千巖曙，蜂來一逕春。","杉松還待客，芝朮不求人。","寧學磻溪叟，逢時罷隱淪。"]', '["潺湲遶门水，未省濯纓塵。","鸟散千巖曙，蜂来一逕春。","杉松還待客，芝朮不求人。","寧学磻溪叟，逢时罷隐淪。"]', '诗', 'shi', '', NULL, '題宣州元處士幽居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f3382c9-9dae-4be5-a239-b7f321a60527', '送李秀才', '送李秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南樓送郢客，西郭見荆門。","鳧鵠下寒渚，牛羊歸遠村。","蘭舟倚行掉，桂酒掩餘尊。","重此一留宿，前村煙水昏。"]', '["南楼送郢客，西郭见荆门。","鳧鵠下寒渚，牛羊归远村。","蘭舟倚行掉，桂酒掩餘尊。","重此一留宿，前村煙水昏。"]', '诗', 'shi', '', NULL, '送李秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81beea63-3272-426d-b9f8-7dcde441d20d', '題倪處士舊居', '題倪处士旧居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["儒翁九十餘，舊向此山居。","生寄一壺酒，死留千卷書。","檻摧新竹少，池淺故蓮疎。","但有子孫在，帶經還荷鋤。"]', '["儒翁九十餘，旧向此山居。","生寄一壺酒，死留千卷书。","檻摧新竹少，池淺故蓮疎。","但有子孫在，带經還荷鋤。"]', '诗', 'shi', '', NULL, '題倪處士舊居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2059680c-58b9-4996-b797-4a3aaadf63d8', '贈梁將軍', '贈梁將軍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["曾經黑山虜，一劒出重圍。","年長窮書意，時清隱釣磯。","高齋雲外住，瘦馬月中歸。","唯說鄉心苦，春風鴈北飛。"]', '["曾經黑山虜，一劒出重圍。","年长窮书意，时清隐釣磯。","高斋云外住，瘦马月中归。","唯说乡心苦，春风鴈北飞。"]', '诗', 'shi', '', NULL, '贈梁將軍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02be451e-a9e6-48de-9dc9-3de4b28dc469', '春望思舊游', '春望思旧游', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["適意極春日，南臺披薜蘿。","花光晴漾漾，山色晝峨峨。","湘水美人遠，信陵豪客多。","唯憑一瓢酒，彈瑟縱高歌。"]', '["適意極春日，南台披薜蘿。","花光晴漾漾，山色晝峨峨。","湘水美人远，信陵豪客多。","唯憑一瓢酒，彈瑟縱高歌。"]', '诗', 'shi', '', NULL, '春望思舊游 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b60708b2-6c5f-4eee-8e29-3940efe65462', '病中二首 一', '病中二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["三年嬰酒渴，高臥似袁安。","秋色鬢應改，夜涼心已寬。","風衣藤簟滑，露井竹牀寒。","臥憶郊扉月，恩深未挂冠。"]', '["三年嬰酒渴，高臥似袁安。","秋色鬢應改，夜涼心已寬。","风衣藤簟滑，露井竹牀寒。","臥憶郊扉月，恩深未挂冠。"]', '诗', 'shi', '', NULL, '病中二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99b70822-e572-4068-bba5-895e14031fda', '病中二首 二', '病中二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["私歸人暫適，扶杖遶西林。","風急柳溪響，露寒莎徑深。","一身仍白髮，萬慮只丹心。","此意無言處，高窗託素琴。"]', '["私归人暫適，扶杖遶西林。","风急柳溪响，露寒莎徑深。","一身仍白髮，万慮只丹心。","此意無言处，高窗託素琴。"]', '诗', 'shi', '', NULL, '病中二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('748e0791-96ce-4280-b298-c027d69c3bac', '姑熟官舍寄汝洛友人', '姑熟官舍寄汝洛友人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["[官]靜亦無能，平生少面朋。","務開唯印吏，公退只棊僧。","藥鼎初寒火，書龕欲夜燈。","安知北溟水，終日送摶鵬。"]', '["[官]静亦無能，平生少面朋。","務开唯印吏，公退只棊僧。","藥鼎初寒火，书龕欲夜灯。","安知北溟水，終日送摶鵬。"]', '诗', 'shi', '', NULL, '姑熟官舍寄汝洛友人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e61831c5-d0be-4905-bb80-dd0e95eb8f76', '恩德寺', '恩德寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["樓臺橫復重，猶有半巖空。","蘿洞淺深水，竹廊高下風。","晴山疎雨後，秋樹斷雲中。","未盡平生意，孤帆又向東。"]', '["楼台橫复重，猶有半巖空。","蘿洞淺深水，竹廊高下风。","晴山疎雨後，秋樹斷云中。","未尽平生意，孤帆又向东。"]', '诗', 'shi', '', NULL, '恩德寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2970098-8c3d-4acf-b136-960b759cd15a', '天竺寺題葛洪井', '天竺寺題葛洪井', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["羽客鍊丹井，井留人已無。","舊泉青石下，餘甃碧山隅。","雲朗鏡開匣，月寒冰在壺。","仍聞釀仙酒，此水過瓊酴。"]', '["羽客鍊丹井，井留人已無。","旧泉青石下，餘甃碧山隅。","云朗镜开匣，月寒冰在壺。","仍闻釀仙酒，此水過瓊酴。"]', '诗', 'shi', '', NULL, '天竺寺題葛洪井 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44098361-dbe7-4210-b972-a8fcd93447bc', '朗上人院晨坐', '朗上人院晨坐', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["簟涼襟袖清，月沒尚殘星。","山果落秋院，水花開曉庭。","疎藤風嫋嫋，圓桂露冥冥。","正憶江南寺，巖齋聞誦經。"]', '["簟涼襟袖清，月沒尚殘星。","山果落秋院，水花开晓庭。","疎藤风嫋嫋，圓桂露冥冥。","正憶江南寺，巖斋闻誦經。"]', '诗', 'shi', '', NULL, '朗上人院晨坐 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3438c909-a367-4633-b0ab-a09a0c787f59', '送客歸湘楚', '送客归湘楚', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["無辭一杯酒，昔日與君深。","秋色換歸鬢，曙光生別心。","桂花山廟冷，楓樹水樓陰。","此路千餘里，應勞楚客吟。"]', '["無辞一杯酒，昔日與君深。","秋色換归鬢，曙光生別心。","桂花山廟冷，楓樹水楼陰。","此路千餘里，應勞楚客吟。"]', '诗', 'shi', '', NULL, '送客歸湘楚 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('480317ec-d52e-477f-b710-46d742e023c6', '過故友舊居', '過故友旧居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["往年公子宅，夜宴樂難忘。","高竹動疎翠，早蓮飄暗香。","珠盤凝寶瑟，綺席遰華觴。","今日皆何處，閉門春草長。"]', '["往年公子宅，夜宴乐难忘。","高竹动疎翠，早蓮飄暗香。","珠盤凝寶瑟，綺席遰华觴。","今日皆何处，閉门春草长。"]', '诗', 'shi', '', NULL, '過故友舊居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ecb56f4-59a7-42a1-b6ab-7e6f6144403c', '送客歸峽中', '送客归峽中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["津亭多別離，楊柳半無枝。","住接猿啼處，行逢鴈過時。","江風颺帆急，山月下樓遲。","還就西齋宿，煙波勞夢思。"]', '["津亭多別離，楊柳半無枝。","住接猿啼处，行逢鴈過时。","江风颺帆急，山月下楼遲。","還就西斋宿，煙波勞梦思。"]', '诗', 'shi', '', NULL, '送客歸峽中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87e871cd-309f-432c-abac-35e91bce9d08', '題冲沼上人院', '題冲沼上人院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["斸石種松子，數根侵杳冥。","天寒猶講律，雨暗尚尋經。","小殿燈千盞，深爐水一瓶。","碧雲多別思，休到望溪亭。"]', '["斸石種松子，數根侵杳冥。","天寒猶講律，雨暗尚尋經。","小殿灯千盞，深爐水一瓶。","碧云多別思，休到望溪亭。"]', '诗', 'shi', '', NULL, '題冲沼上人院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b25f617-6076-42e9-a9dc-e986e5509bc6', '和畢員外雪中見寄', '和畢員外雪中见寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["仙署淹清景，雪華松桂陰。","夜凌瑤席宴，春寄玉京吟。","燭晃垂羅幙，香寒重繡衾。","相思不相訪，煙月剡溪深。"]', '["仙署淹清景，雪华松桂陰。","夜凌瑤席宴，春寄玉京吟。","燭晃垂羅幙，香寒重繡衾。","相思不相訪，煙月剡溪深。"]', '诗', 'shi', '', NULL, '和畢員外雪中見寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05d0c7e-3480-47cb-9073-b4408e445f99', '春醉', '春醉', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["酒醲花一樹，何暇卓文君。","客坐長先飲，公閑半已曛。","水鄉春足雨，山郭夜多雲。","何似參禪理，榮枯盡不聞。"]', '["酒醲花一樹，何暇卓文君。","客坐长先饮，公闲半已曛。","水乡春足雨，山郭夜多云。","何似參禪理，榮枯尽不闻。"]', '诗', 'shi', '', NULL, '春醉 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc750ec6-3a85-4488-9cbd-758d481e5997', '題岫上人院', '題岫上人院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["病客與僧閑，頻來不掩關。","高窗雲外樹，疎磬雨中山。","離索秋蟲響，登臨夕鳥還。","心知落帆處，明日淛河灣。"]', '["病客與僧闲，頻来不掩关。","高窗云外樹，疎磬雨中山。","離索秋蟲响，登臨夕鸟還。","心知落帆处，明日淛河灣。"]', '诗', 'shi', '', NULL, '題岫上人院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9dedd5-31d7-445e-94d9-2071c4bb1bc6', '送客南歸有懷', '送客南归有懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠水暖青蘋，湘潭萬里春。","瓦尊迎海客，銅鼓賽江神。","避雨松楓岸，看雲楊柳津。","長安一杯酒，座上有歸人。"]', '["綠水暖青蘋，湘潭万里春。","瓦尊迎海客，銅鼓賽江神。","避雨松楓岸，看云楊柳津。","长安一杯酒，座上有归人。"]', '诗', 'shi', '', NULL, '送客南歸有懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca6b982-e260-414d-9c5e-298a07298639', '李生棄官入道因寄', '李生棄官入道因寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西巖一徑通，知學採芝翁。","寒暑丹心外，光陰白髮中。","水深魚避釣，雲迥鶴辭籠。","坐想還家日，人非井邑空。"]', '["西巖一徑通，知学採芝翁。","寒暑丹心外，光陰白髮中。","水深鱼避釣，云迥鹤辞籠。","坐想還家日，人非井邑空。"]', '诗', 'shi', '', NULL, '李生棄官入道因寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ad6ed1-104c-4bf7-9547-58005168a6fd', '長興里夏日南鄰避暑', '长兴里夏日南鄰避暑', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["侯門大道傍，蟬噪樹蒼蒼。","開鏁洞門遠，下簾賓館涼。","欄圍紅藥盛，架引綠蘿長。","永日一欹枕，故山雲水鄉。"]', '["侯门大道傍，蟬噪樹蒼蒼。","开鏁洞门远，下簾賓館涼。","欄圍紅藥盛，架引綠蘿长。","永日一欹枕，故山云水乡。"]', '诗', 'shi', '', NULL, '長興里夏日南鄰避暑 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3599333c-7e9d-4897-92d4-0bc31381791b', '送韓校書', '送韓校书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["恨與前歡隔，愁因此會同。","跡高芸閣吏，名散雪樓翁。","城閉三秋雨，帆飛一夜風。","酒醒鱸鱠美，應在竟陵東。"]', '["恨與前歡隔，愁因此會同。","跡高芸閣吏，名散雪楼翁。","城閉三秋雨，帆飞一夜风。","酒醒鱸鱠美，應在竟陵东。"]', '诗', 'shi', '', NULL, '送韓校書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afd48c75-6501-4167-a8b2-149d47b05919', '秋晚登城', '秋晚登城', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["城高不可下，永日一登臨。","曲檻涼飆急，空樓返照深。","葦花迷夕棹，梧葉散秋砧。","謾作歸田賦，蹉跎歲欲陰。"]', '["城高不可下，永日一登臨。","曲檻涼飆急，空楼返照深。","葦花迷夕棹，梧葉散秋砧。","謾作归田賦，蹉跎歲欲陰。"]', '诗', 'shi', '', NULL, '秋晚登城 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c05e8f-d3c3-47dd-ad5a-d531f29da487', '江西鄭常侍赴鎮之日有寄因酬和', '江西鄭常侍赴鎮之日有寄因酬和', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["來暮亦何愁，金貂在鷁舟。","斾隨寒浪動，帆帶夕陽收。","布令滕王閣，裁詩郢客樓。","即應歸鳳沼，中外贊天休。"]', '["来暮亦何愁，金貂在鷁舟。","斾隨寒浪动，帆带夕陽收。","布令滕王閣，裁诗郢客楼。","即應归鳳沼，中外贊天休。"]', '诗', 'shi', '', NULL, '江西鄭常侍赴鎮之日有寄因酬和 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7487d0b0-b96b-4af7-a297-933e1558f377', '蒙河南劉大夫見示與吏部張公喜雪酬唱輒敢攀和', '蒙河南劉大夫见示與吏部張公喜雪酬唱輒敢攀和', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["風度龍山暗，雲凝象闕陰。","瑞花瓊樹合，仙草玉苗深。","欲醉梁王酒，先調楚客琴。","即應攜手去，將此助商霖。"]', '["风度龙山暗，云凝象闕陰。","瑞花瓊樹合，仙草玉苗深。","欲醉梁王酒，先調楚客琴。","即應携手去，將此助商霖。"]', '诗', 'shi', '', NULL, '蒙河南劉大夫見示與吏部張公喜雪酬唱輒敢攀和 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e779d798-62ec-4ba8-aef8-22c14546179f', '下第送宋秀才游岐下楊秀才還江東', '下第送宋秀才游岐下楊秀才還江东', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["年來不自得，一望幾傷心。","風轉蕙蘭色，月移松桂陰。","馬隨邊草遠，帆落海雲深。","明旦各分首，更聽梁甫吟。"]', '["年来不自得，一望幾傷心。","风轉蕙蘭色，月移松桂陰。","马隨邊草远，帆落海云深。","明旦各分首，更听梁甫吟。"]', '诗', 'shi', '', NULL, '下第送宋秀才游岐下楊秀才還江東 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6d4076b-7980-456f-b002-4120afa4c148', '南亭偶題', '南亭偶題', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["城下水縈回，潮衝野艇來。","鳥驚山果落，龜泛綠萍開。","白首書千卷，朱顏酒一杯。","南軒自流涕，不是望燕臺。"]', '["城下水縈回，潮衝野艇来。","鸟驚山果落，龟泛綠萍开。","白首书千卷，朱顏酒一杯。","南軒自流涕，不是望燕台。"]', '诗', 'shi', '', NULL, '南亭偶題 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b498332-b5f5-4640-acb5-29477af681bc', '與裴三十秀才自越西歸望亭阻凍登虎丘山寺精舍', '與裴三十秀才自越西归望亭阻凍登虎丘山寺精舍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["春草越吳間，心期旦夕還。","酒鄉逢客病，詩境遇僧閑。","倚棹冰生浦，登樓雪滿山。","東風不可待，歸鬢坐斑斑。"]', '["春草越吳间，心期旦夕還。","酒乡逢客病，诗境遇僧闲。","倚棹冰生浦，登楼雪满山。","东风不可待，归鬢坐斑斑。"]', '诗', 'shi', '', NULL, '與裴三十秀才自越西歸望亭阻凍登虎丘山寺精舍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce2a6ae-98e8-46bd-b9c1-05f545f7ea1d', '太和初靖恭里感事', '太和初靖恭里感事', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["清湘弔屈原，垂淚擷蘋蘩。","謗起乘軒鶴，機沈在檻猨。","乾坤三事貴，華夏一夫冤。","寧有唐虞世，心知不爲言。"]', '["清湘弔屈原，垂泪擷蘋蘩。","謗起乘軒鹤，機沈在檻猨。","乾坤三事貴，华夏一夫冤。","寧有唐虞世，心知不爲言。"]', '诗', 'shi', '', NULL, '太和初靖恭里感事 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c82ff6ae-cdc3-4651-ba33-f93beb4286da', '與侯春時同年南池夜話', '與侯春时同年南池夜話', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蘆葦暮修修，溪禽上釣舟。","露涼花歛夕，風靜竹含秋。","素志應難契，清言豈易求。","相歡一瓢酒，明日醉西樓。"]', '["蘆葦暮修修，溪禽上釣舟。","露涼花歛夕，风静竹含秋。","素志應难契，清言豈易求。","相歡一瓢酒，明日醉西楼。"]', '诗', 'shi', '', NULL, '與侯春時同年南池夜話 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291429aa-73ad-4373-9dfc-28b4a96ba982', '廣陵送剡縣薛明府赴任', '廣陵送剡縣薛明府赴任', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["車馬楚城壕，清歌送濁醪。","露花羞別淚，煙草讓歸袍。","鳥浴春塘暖，猨吟暮嶺高。","尋仙在仙骨，不用廢牛刀。"]', '["车马楚城壕，清歌送濁醪。","露花羞別泪，煙草讓归袍。","鸟浴春塘暖，猨吟暮嶺高。","尋仙在仙骨，不用廢牛刀。"]', '诗', 'shi', '', NULL, '廣陵送剡縣薛明府赴任 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc378fa9-aae1-40b4-815c-a56650da4fa5', '遊果晝二僧院', '游果晝二僧院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["何必老林泉，冥心便是禪。","講時開院去，齋後下簾眠。","鏡朗燈分焰，香銷印絕煙。","真乘不可到，雲盡月明天。"]', '["何必老林泉，冥心便是禪。","講时开院去，斋後下簾眠。","镜朗灯分焰，香銷印絕煙。","真乘不可到，云尽月明天。"]', '诗', 'shi', '', NULL, '遊果晝二僧院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576b6d5c-a5f5-4522-a39b-aea6c86c5523', '題官舍', '題官舍', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["燕鴈水鄉飛，京華信自稀。","簟瓢貧守道，書劒病忘機。","疊鼓吏初散，繁鐘鳥獨歸。","高梧與疎柳，風雨似郊扉。"]', '["燕鴈水乡飞，京华信自稀。","簟瓢貧守道，书劒病忘機。","叠鼓吏初散，繁鐘鸟独归。","高梧與疎柳，风雨似郊扉。"]', '诗', 'shi', '', NULL, '題官舍 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670ad077-f5fa-4393-b323-d605218b8a4a', '酬報先上人登樓見寄', '酬報先上人登楼见寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["丹葉下西樓，知君萬里愁。","鐘非黔峽寺，帆是敬亭舟。","山色和雲暮，湖光共月秋。","天台多道侶，何惜更南遊。"]', '["丹葉下西楼，知君万里愁。","鐘非黔峽寺，帆是敬亭舟。","山色和云暮，湖光共月秋。","天台多道侶，何惜更南游。"]', '诗', 'shi', '', NULL, '酬報先上人登樓見寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c91f10-cd6a-4092-a67e-ae8173e48057', '曉過鬱林寺戲呈李明府', '晓過鬱林寺戲呈李明府', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["身閑白日長，何處不尋芳？","山崦登樓寺，谿灣泊晚檣。","洞花蜂聚蜜，巖栢麝留香。","若指求仙路，劉郎學阮郎。"]', '["身闲白日长，何处不尋芳？","山崦登楼寺，谿灣泊晚檣。","洞花蜂聚蜜，巖栢麝留香。","若指求仙路，劉郎学阮郎。"]', '诗', 'shi', '', NULL, '曉過鬱林寺戲呈李明府 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c7cf51-4004-4fb6-b94e-848fb86cac95', '泛舟尋鬱林寺道玄上人遇雨而返因寄', '泛舟尋鬱林寺道玄上人遇雨而返因寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["禪扉倚石梯，雲濕雨淒淒。","草色分松逕，泉聲咽稻畦。","棹移灘鳥沒，鐘斷嶺猨啼。","入夜花如雪，回舟憶剡溪。"]', '["禪扉倚石梯，云濕雨淒淒。","草色分松逕，泉声咽稻畦。","棹移灘鸟沒，鐘斷嶺猨啼。","入夜花如雪，回舟憶剡溪。"]', '诗', 'shi', '', NULL, '泛舟尋鬱林寺道玄上人遇雨而返因寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083cdd5f-b1ac-4aee-82cb-87d076e86dda', '鬱林寺', '鬱林寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["臺殿冠嵯峨，春來日日過。","水分諸院少，雲近上方多。","衆籟凝絲竹，繁英耀綺羅。","酒酣詩自逸，乘月棹寒波。"]', '["台殿冠嵯峨，春来日日過。","水分諸院少，云近上方多。","衆籟凝絲竹，繁英耀綺羅。","酒酣诗自逸，乘月棹寒波。"]', '诗', 'shi', '', NULL, '鬱林寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3921d439-6153-48a0-8c8c-0993f2cb6b94', '題崇聖寺', '題崇聖寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西林本行殿，池榭日坡陁。","雨過水初漲，雲開山漸多。","曉街垂御柳，秋院閉宮莎。","借問龍歸處，鼎湖空碧波。"]', '["西林本行殿，池榭日坡陁。","雨過水初漲，云开山漸多。","晓街垂御柳，秋院閉宮莎。","借问龙归处，鼎湖空碧波。"]', '诗', 'shi', '', NULL, '題崇聖寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd46c5b-6283-408e-b838-07dc82cbd15c', '贈高處士', '贈高处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["宅前雲水滿，高興一書生。","垂釣有深意，望山多遠情。","夜棊留客宿，春酒勸僧傾。","未作干時計，何人問姓名。"]', '["宅前云水满，高兴一书生。","垂釣有深意，望山多远情。","夜棊留客宿，春酒勸僧傾。","未作干时計，何人问姓名。"]', '诗', 'shi', '', NULL, '贈高處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370ceeec-e080-44af-ab76-9e0215cee632', '送僧歸金山寺', '送僧归金山寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["老歸江上寺，不忘舊師恩。","駐錫逢山色，停杯見浪痕。","秋濤吞楚驛，曉月上荆門。","爲訪題詩處，莓苔幾字存。"]', '["老归江上寺，不忘旧師恩。","駐錫逢山色，停杯见浪痕。","秋濤吞楚驛，晓月上荆门。","爲訪題诗处，莓苔幾字存。"]', '诗', 'shi', '', NULL, '送僧歸金山寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('629f0831-43f0-4a07-8875-8abbd83f47b5', '金谷桃花', '金谷桃花', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["花在舞樓空，年年依舊紅。","淚光停曉露，愁態倚春風。","開處妾先死，落時君亦終。","東流兩三片，應在夜泉中。"]', '["花在舞楼空，年年依旧紅。","泪光停晓露，愁態倚春风。","开处妾先死，落时君亦終。","东流兩三片，應在夜泉中。"]', '诗', 'shi', '', NULL, '金谷桃花 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5679821e-4d95-4e64-bcea-d9e0531b3cda', '憶長洲', '憶长洲', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["香徑小船通，菱歌遶故宮。","魚沈秋水靜，鳥宿暮山空。","荷葉橋邊雨，蘆花海上風。","歸心無處託，高枕畫屏中。"]', '["香徑小船通，菱歌遶故宮。","鱼沈秋水静，鸟宿暮山空。","荷葉橋邊雨，蘆花海上风。","归心無处託，高枕畫屏中。"]', '诗', 'shi', '', NULL, '憶長洲 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1d289d5-7b9b-44a9-afa1-5f839f10ace3', '寄殷堯藩', '寄殷堯藩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["直道知難用，經年向水濱。","宅從栽竹貴，家爲買書貧。","就學多新客，登朝盡故人。","蓬萊自有路，莫羨武陵春。"]', '["直道知难用，經年向水濱。","宅從栽竹貴，家爲買书貧。","就学多新客，登朝尽故人。","蓬萊自有路，莫羨武陵春。"]', '诗', 'shi', '', NULL, '寄殷堯藩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e87a03-29a4-4e7f-a36b-28ae803d65a3', '題鄒處士隱居', '題鄒处士隐居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["桑柘滿江村，西齋接海門。","浪衝高岸響，潮入小池渾。","嵒樹陰棊局，山花落酒樽。","相逢亦留宿，還似識王孫。"]', '["桑柘满江村，西斋接海门。","浪衝高岸响，潮入小池渾。","嵒樹陰棊局，山花落酒樽。","相逢亦留宿，還似識王孫。"]', '诗', 'shi', '', NULL, '題鄒處士隱居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9649b00-f87c-43ca-b84a-dc17089105e1', '送僧歸敬亭山寺', '送僧归敬亭山寺', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["十年劒中路，傳盡本師經。","曉月下黔峽，秋風歸敬亭。","開門新樹綠，登閣舊山青。","遙想論禪處，松陰水一瓶。"]', '["十年劒中路，傳尽本師經。","晓月下黔峽，秋风归敬亭。","开门新樹綠，登閣旧山青。","遙想論禪处，松陰水一瓶。"]', '诗', 'shi', '', NULL, '送僧歸敬亭山寺 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d80c52e-0108-4215-86e5-4ee71ecf9aac', '新卜原上居寄袁校書', '新卜原上居寄袁校书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["貧居樂游此，江海思迢迢。","雪夜書千卷，花時酒一瓢。","獨愁秦樹老，孤夢楚山遙。","有路應相念，風塵滿黑貂。"]', '["貧居乐游此，江海思迢迢。","雪夜书千卷，花时酒一瓢。","独愁秦樹老，孤梦楚山遙。","有路應相念，风塵满黑貂。"]', '诗', 'shi', '', NULL, '新卜原上居寄袁校書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('437f7068-127c-47db-b4b4-80bf4b78a30a', '天街曉望', '天街晓望', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["明星低未央，蓮闕逈蒼蒼。","疊鼓催殘月，疎鐘迎早霜。","關防浮瑞氣，宮館耀神光。","再拜爲君壽，南山高且長。"]', '["明星低未央，蓮闕逈蒼蒼。","叠鼓催殘月，疎鐘迎早霜。","关防浮瑞氣，宮館耀神光。","再拜爲君壽，南山高且长。"]', '诗', 'shi', '', NULL, '天街曉望 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b5f7b8-530b-426b-b7ae-03bee02523c2', '江上喜洛中親友繼至', '江上喜洛中親友繼至', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["戰馬昔紛紛，風驚嵩少塵。","全家南渡遠，舊友北來頻。","罷酒松筠晚，賦詩楊柳春。","誰言今夜月，同是洛陽人。"]', '["戰马昔紛紛，风驚嵩少塵。","全家南渡远，旧友北来頻。","罷酒松筠晚，賦诗楊柳春。","誰言今夜月，同是洛陽人。"]', '诗', 'shi', '', NULL, '江上喜洛中親友繼至 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcfa2c6d-bc15-49c1-8533-6ed189e7946e', '下第歸朱方寄劉三復', '下第归朱方寄劉三复', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["素衣京洛塵，歸棹過南津。","故里跡猶在，舊交心更親。","月高蕭寺夜，風暖庾樓春。","詩酒應無暇，朝朝問旅人。"]', '["素衣京洛塵，归棹過南津。","故里跡猶在，旧交心更親。","月高蕭寺夜，风暖庾楼春。","诗酒應無暇，朝朝问旅人。"]', '诗', 'shi', '', NULL, '下第歸朱方寄劉三復 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35b41d75-03c1-4ed1-a684-80437eb641cf', '送人歸吳興', '送人归吳兴', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠水棹雲月，洞庭歸路長。","春橋懸酒幔，夜柵集茶檣。","箬葉沈溪暖，蘋花遶郭香。","應逢柳太守，爲說過瀟湘。"]', '["綠水棹云月，洞庭归路长。","春橋懸酒幔，夜柵集茶檣。","箬葉沈溪暖，蘋花遶郭香。","應逢柳太守，爲说過瀟湘。"]', '诗', 'shi', '', NULL, '送人歸吳興 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73e62369-50fa-4a3e-b041-ac1e66892b83', '月夜期友人不至', '月夜期友人不至', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["坐待故人宿，月華清興秋。","管弦誰處醉，池館此時愁。","風過渚荷動，露含山桂幽。","孤吟不可曙，昨夜共登樓。"]', '["坐待故人宿，月华清兴秋。","管弦誰处醉，池館此时愁。","风過渚荷动，露含山桂幽。","孤吟不可曙，昨夜共登楼。"]', '诗', 'shi', '', NULL, '月夜期友人不至 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb67157d-5696-4952-b121-e34f7731fb27', '白馬寺不出院僧', '白马寺不出院僧', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["禪空心已寂，世路任多岐。","到院客長見，閉關人不知。","寺喧聽講絕，廚遠送齋遲。","牆外洛陽道，東西無盡時。"]', '["禪空心已寂，世路任多岐。","到院客长见，閉关人不知。","寺喧听講絕，廚远送斋遲。","牆外洛陽道，东西無尽时。"]', '诗', 'shi', '', NULL, '白馬寺不出院僧 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50a329cd-54ac-44a6-886f-3de53073a127', '寄袁校書', '寄袁校书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["擾擾換時節，舊山琪樹陰。","猶乖清漢志，空負白雲心。","廣陌埃塵遠，重門管吹深。","勞歌極西望，芸省有知音。"]', '["擾擾換时節，旧山琪樹陰。","猶乖清漢志，空負白云心。","廣陌埃塵远，重门管吹深。","勞歌極西望，芸省有知音。"]', '诗', 'shi', '', NULL, '寄袁校書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74cfdd9-73ed-4d4c-bb74-4c4232447ee2', '贈柳璟馮陶二校書', '贈柳璟馮陶二校书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["霄漢兩飛鳴，喧喧動禁城。","桂堂同日盛，芸閣間年榮。","香掩蕙蘭氣，韻高鸞鶴聲。","應憐茂陵客，未有子虛名。"]', '["霄漢兩飞鳴，喧喧动禁城。","桂堂同日盛，芸閣间年榮。","香掩蕙蘭氣，韻高鸾鹤声。","應怜茂陵客，未有子虛名。"]', '诗', 'shi', '', NULL, '贈柳璟馮陶二校書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b47a8a2a-336a-46c8-9274-89c4ea7f625c', '王秀才自越見尋不遇題詩而迴因以酬寄', '王秀才自越见尋不遇題诗而迴因以酬寄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南齋知數宿，半爲木蘭開。","晴閣留詩遍，春帆載酒回。","煙深楊子宅，雲斷越王臺。","自有孤舟興，何妨更一來。"]', '["南斋知數宿，半爲木蘭开。","晴閣留诗遍，春帆載酒回。","煙深楊子宅，云斷越王台。","自有孤舟兴，何妨更一来。"]', '诗', 'shi', '', NULL, '王秀才自越見尋不遇題詩而迴因以酬寄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1769695-570c-42b2-b2b4-d390c920112e', '秋霽潼關驛亭', '秋霽潼关驛亭', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["霽色明高巘，關河獨望遙。","殘雲歸太華，疎雨過中條。","鳥散綠蘿靜，蟬鳴紅樹凋。","何言此時節，去去任蓬飄。"]', '["霽色明高巘，关河独望遙。","殘云归太华，疎雨過中條。","鸟散綠蘿静，蟬鳴紅樹凋。","何言此时節，去去任蓬飄。"]', '诗', 'shi', '', NULL, '秋霽潼關驛亭 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5540c14-8205-4149-b323-d169a0706fb1', '送客歸蘭谿', '送客归蘭谿', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["花下送歸客，路長應過秋。","暮隨江鳥宿，寒共嶺猨愁。","衆水喧嚴瀨，羣峰抱沈樓。","因君幾南望，曾向此中遊。"]', '["花下送归客，路长應過秋。","暮隨江鸟宿，寒共嶺猨愁。","衆水喧嚴瀨，羣峰抱沈楼。","因君幾南望，曾向此中游。"]', '诗', 'shi', '', NULL, '送客歸蘭谿 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b00404-8b22-433a-a292-803a77e1015d', '貽終南山隱者', '貽終南山隐者', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["中巖多少隱，提榼抱琴遊。","潭冷薜蘿晚，山香松桂秋。","瓢閑高樹挂，杯急曲池流。","獨有迷津客，東西南北愁。"]', '["中巖多少隐，提榼抱琴游。","潭冷薜蘿晚，山香松桂秋。","瓢闲高樹挂，杯急曲池流。","独有迷津客，东西南北愁。"]', '诗', 'shi', '', NULL, '貽終南山隱者 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7d9f7f-642b-495e-947e-24b0ff36a165', '送李文明下第鄜州覲兄', '送李文明下第鄜州覲兄', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["征夫天一涯，醉贈別吾詩。","鴈迥參差遠，龍多次第遲。","寧歌還夜苦，宋賦更秋悲。","的的遙相待，清風白露時。"]', '["征夫天一涯，醉贈別吾诗。","鴈迥參差远，龙多次第遲。","寧歌還夜苦，宋賦更秋悲。","的的遙相待，清风白露时。"]', '诗', 'shi', '', NULL, '送李文明下第鄜州覲兄 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('accc2622-4cfe-4709-a70d-cda0f9c13e73', '送段覺歸東陽兼寄竇使君', '送段覺归东陽兼寄竇使君', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山水引歸路，陸郎從此諳。","秋茶垂露細，寒菊帶霜甘。","臺倚烏龍嶺，樓侵白鴈潭。","沈公如借問，心在浙河南。"]', '["山水引归路，陸郎從此諳。","秋茶垂露細，寒菊带霜甘。","台倚烏龙嶺，楼侵白鴈潭。","沈公如借问，心在浙河南。"]', '诗', 'shi', '', NULL, '送段覺歸東陽兼寄竇使君 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('981b0ac2-a0b4-40a2-b506-9cbca656cd4a', '韶州送竇司直北歸', '韶州送竇司直北归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江曲山如畫，貪程亦駐舟。","果隨巖狖落，槎帶水禽流。","客散他鄉夜，人歸故國秋。","樽前挂帆去，風雨下西樓。"]', '["江曲山如畫，貪程亦駐舟。","果隨巖狖落，槎带水禽流。","客散他乡夜，人归故国秋。","樽前挂帆去，风雨下西楼。"]', '诗', 'shi', '', NULL, '韶州送竇司直北歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acd0964e-4217-4615-b3f9-1aff4c25bcd3', '傷馮秀才', '傷馮秀才', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["旅葬不可問，茫茫西隴頭。","水雲青草濕，山月白楊愁。","琴信有時罷，劒傷無處留。","淮南舊煙月，孤棹更逢秋。"]', '["旅葬不可问，茫茫西隴头。","水云青草濕，山月白楊愁。","琴信有时罷，劒傷無处留。","淮南旧煙月，孤棹更逢秋。"]', '诗', 'shi', '', NULL, '傷馮秀才 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ee9135f-a5fa-4900-86fe-c8a8f23bff83', '送鄭寂上人南行', '送鄭寂上人南行', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["儒家有釋子，年少學支公。","心出是非外，跡辭榮辱中。","錫寒秦嶺月，杯急楚江風。","離怨故園思，小秋梨葉紅。"]', '["儒家有釋子，年少学支公。","心出是非外，跡辞榮辱中。","錫寒秦嶺月，杯急楚江风。","離怨故园思，小秋梨葉紅。"]', '诗', 'shi', '', NULL, '送鄭寂上人南行 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f78c04bf-1973-48aa-a05b-7ef368e12c51', '贈王處士', '贈王处士', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["歸臥養天真，鹿裘烏角巾。","茂陵閑久病，彭澤醉長貧。","冠蓋西園夜，笙歌北里春。","誰憐清渭曲，又老釣魚人。"]', '["归臥養天真，鹿裘烏角巾。","茂陵闲久病，彭澤醉长貧。","冠蓋西园夜，笙歌北里春。","誰怜清渭曲，又老釣鱼人。"]', '诗', 'shi', '', NULL, '贈王處士 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e07a0b-9797-4ad7-9696-0aaf14c35046', '送友人歸荆楚', '送友人归荆楚', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["調瑟勸離酒，苦諳荆楚門。","竹斑悲帝女，草綠怨王孫。","潮落九疑迥，雨連三峽昏。","同來不同去，迢遰更傷魂。"]', '["調瑟勸離酒，苦諳荆楚门。","竹斑悲帝女，草綠怨王孫。","潮落九疑迥，雨連三峽昏。","同来不同去，迢遰更傷魂。"]', '诗', 'shi', '', NULL, '送友人歸荆楚 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b671e637-ed10-4b19-8796-d2af74da6ae0', '重傷楊攀處士二首 一', '重傷楊攀处士二首 一', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠雲多學術，黃髪竟無成。","酒縱山中性，詩留海上名。","讀書新樹老，垂釣舊磯平。","今日悲前事，西風聞哭聲。"]', '["綠云多学術，黄髪竟無成。","酒縱山中性，诗留海上名。","读书新樹老，垂釣旧磯平。","今日悲前事，西风闻哭声。"]', '诗', 'shi', '', NULL, '重傷楊攀處士二首 一 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c6d27cd-3758-43fb-a6f9-99e9a301e1a4', '重傷楊攀處士二首 二', '重傷楊攀处士二首 二', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["從官任直道，幾處脫長裾。","歿後兒猶小，葬來人漸疎。","新隣占池館，長史覓圖書。","身賤難相報，平生恨有餘。"]', '["從官任直道，幾处脫长裾。","歿後兒猶小，葬来人漸疎。","新隣占池館，长史覓圖书。","身賤难相報，平生恨有餘。"]', '诗', 'shi', '', NULL, '重傷楊攀處士二首 二 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1e81aed-9e20-498e-be9f-ea7722680f44', '送友人罷舉歸東海', '送友人罷舉归东海', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["滄波天塹外，何島是新羅。","舶主辭番遠，碁僧入漢多。","海風吹白鶴，沙日曬紅螺。","此去知投筆，須求利劒磨。"]', '["滄波天塹外，何島是新羅。","舶主辞番远，碁僧入漢多。","海风吹白鹤，沙日曬紅螺。","此去知投笔，須求利劒磨。"]', '诗', 'shi', '', NULL, '送友人罷舉歸東海 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ce48e57-0b3f-4217-a7cb-0994036bab6e', '西園', '西园', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["西園春欲盡，芳草徑難分。","靜語唯幽鳥，閑眠獨使君。","密林生雨氣，古石帶苔文。","雖去清朝遠，朝朝見白雲。"]', '["西园春欲尽，芳草徑难分。","静語唯幽鸟，闲眠独使君。","密林生雨氣，古石带苔文。","雖去清朝远，朝朝见白云。"]', '诗', 'shi', '', NULL, '西園 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cdc4b5a-abdc-4551-9b3d-b05727f9a807', '苦雨', '苦雨', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江昏山半晴，南阻絕人行。","葭菼連雲色，杉松共雨聲。","早秋仍燕舞，深夜更鼉鳴。","爲報迷津客，訛言未可輕。"]', '["江昏山半晴，南阻絕人行。","葭菼連云色，杉松共雨声。","早秋仍燕舞，深夜更鼉鳴。","爲報迷津客，訛言未可轻。"]', '诗', 'shi', '', NULL, '苦雨 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b6bf32-ea9b-421e-bf4a-230fda0c878e', '遊茅山', '游茅山', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["步步入山門，仙家鳥徑分。","漁樵不到處，麋鹿自成羣。","石面迸出水，松頭穿破雲。","道人星月下，相次禮茅君。"]', '["步步入山门，仙家鸟徑分。","漁樵不到处，麋鹿自成羣。","石面迸出水，松头穿破云。","道人星月下，相次禮茅君。"]', '诗', 'shi', '', NULL, '遊茅山 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b18371c-f32a-4e6d-b708-f9e37cd9d63d', '洛陽道中', '洛陽道中', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["洛陽多舊迹，一日幾堪愁。","風起林花晚，月明陵樹秋。","興亡不可問，自古水東流。"]', '["洛陽多旧迹，一日幾堪愁。","风起林花晚，月明陵樹秋。","兴亡不可问，自古水东流。"]', '诗', 'shi', '', NULL, '洛陽道中 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da3132c7-2f84-4d31-962c-97a5560e2618', '江上燕別', '江上燕別', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雲物如故鄉，山川異岐路。","年來未歸客，馬上春欲暮。","一樽花下酒，殘日水西樹。","不待管弦終，搖鞭背花去。"]', '["云物如故乡，山川異岐路。","年来未归客，马上春欲暮。","一樽花下酒，殘日水西樹。","不待管弦終，搖鞭背花去。"]', '诗', 'shi', '', NULL, '江上燕別 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d170bf96-3a39-4c70-be03-7e0a1560f2b9', '卜居招書侶', '卜居招书侶', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["憶昨未知道，臨川每羨魚。","世途行處見，人事病來疎。","微雨秋栽竹，孤燈夜讀書。","憐君亦同志，晚歲傍山居。"]', '["憶昨未知道，臨川每羨鱼。","世途行处见，人事病来疎。","微雨秋栽竹，孤灯夜读书。","怜君亦同志，晚歲傍山居。"]', '诗', 'shi', '', NULL, '卜居招書侶 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba63f2f-a1ed-428a-8a9c-1e8447b8ef5b', '西山草堂', '西山草堂', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["何處少人事，西山舊草堂。","晒書秋日晚，洗藥石泉香。","浚嶺有朝雨，北窗生夜涼。","從勞問歸路，峰疊遶家鄉。"]', '["何处少人事，西山旧草堂。","晒书秋日晚，洗藥石泉香。","浚嶺有朝雨，北窗生夜涼。","從勞问归路，峰叠遶家乡。"]', '诗', 'shi', '', NULL, '西山草堂 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd1f2c3a-f0c4-409f-829b-a7a7e8e854e1', '贈隱者', '贈隐者', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["回報隱居士，莫愁山興闌。","求人顏色盡，知道性情寬。","信譜彈琴誤，緣崖劚藥難。","東臯亦自給，殊愧遠相安。"]', '["回報隐居士，莫愁山兴闌。","求人顏色尽，知道性情寬。","信譜彈琴誤，緣崖劚藥难。","东臯亦自給，殊愧远相安。"]', '诗', 'shi', '', NULL, '贈隱者 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('831e1360-a726-42e6-b403-50ce04f1907e', '舟次武陵寄天竺僧無晝', '舟次武陵寄天竺僧無晝', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["谿長山幾重，十里萬株松。","秋日下丹檻，暮雲歸碧峰。","樹棲新放鶴，潭隱舊降龍。","還在孤舟宿，臥聞初夜鐘。"]', '["谿长山幾重，十里万株松。","秋日下丹檻，暮云归碧峰。","樹棲新放鹤，潭隐旧降龙。","還在孤舟宿，臥闻初夜鐘。"]', '诗', 'shi', '', NULL, '舟次武陵寄天竺僧無晝 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e3368e-aa81-4bad-9172-31cd39602335', '寄小弟', '寄小弟', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["江城紅葉盡，旅思復悽傷。","孤夢家山遠，獨眠秋夜長。","道存空倚命，身賤未歸鄉。","南望空垂淚，天邊鴈一行。"]', '["江城紅葉尽，旅思复悽傷。","孤梦家山远，独眠秋夜长。","道存空倚命，身賤未归乡。","南望空垂泪，天邊鴈一行。"]', '诗', 'shi', '', NULL, '寄小弟 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8846f916-f34a-4123-807e-ec16c465d8fa', '秋日', '秋日', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["有計自安業，秋風罷苦吟。","買山兼種竹，對客更彈琴。","煙起藥園晚，杵聲松院深。","閑眠得真性，惆悵舊時心。"]', '["有計自安業，秋风罷苦吟。","買山兼種竹，对客更彈琴。","煙起藥园晚，杵声松院深。","闲眠得真性，惆悵旧时心。"]', '诗', 'shi', '', NULL, '秋日 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8468516-e8e1-4ba5-a5bf-4d6b6119d9c3', '石池', '石池', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["通竹引泉脉，泓澄瀲石盆。","驚魚翻藻葉，浴鳥上松根。","殘月留山影，高風耗水痕。","誰家秋洗藥，來往自開門。"]', '["通竹引泉脉，泓澄瀲石盆。","驚鱼翻藻葉，浴鸟上松根。","殘月留山影，高风耗水痕。","誰家秋洗藥，来往自开门。"]', '诗', 'shi', '', NULL, '石池 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bda99da-d73a-4127-be83-435c4e5e49e2', '留題李侍御書齋', '留題李侍御书斋', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["昔話平生志，高齋曾見留。","道孤心易感，恩重力難酬。","獨立千峰曉，頻來一葉秋。","雞鳴應有處，不覺淚空流。"]', '["昔話平生志，高斋曾见留。","道孤心易感，恩重力难酬。","独立千峰晓，頻来一葉秋。","雞鳴應有处，不覺泪空流。"]', '诗', 'shi', '', NULL, '留題李侍御書齋 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4f3106-4987-4343-bae0-4c11e7167530', '行次白沙館先寄上河南王侍御', '行次白沙館先寄上河南王侍御', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["夜程何處宿，山疊樹層層。","孤館閉秋雨，空堂停曙燈。","歌慙漁浦客，詩學鴈門僧。","此意無人識，明朝見李膺。"]', '["夜程何处宿，山叠樹層層。","孤館閉秋雨，空堂停曙灯。","歌慙漁浦客，诗学鴈门僧。","此意無人識，明朝见李膺。"]', '诗', 'shi', '', NULL, '行次白沙館先寄上河南王侍御 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963a756e-4b6a-4b0d-924a-e48c9ce93f38', '紫藤', '紫藤', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["綠蘿縈數匝，本在草堂間。","秋色寄高樹，晝陰籠遠山。","移花疎處種，劚藥困時攀。","日暮微風起，難尋舊徑還。"]', '["綠蘿縈數匝，本在草堂间。","秋色寄高樹，晝陰籠远山。","移花疎处種，劚藥困时攀。","日暮微风起，难尋旧徑還。"]', '诗', 'shi', '', NULL, '紫藤 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd3431c-26c9-4049-90d6-f5049ca88c3e', '暝投靈智寺渡谿不得却取沿江路往', '暝投靈智寺渡谿不得却取沿江路往', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雙巖瀉一川，回馬斷橋前。","古廟陰風地，寒鐘暮雨天。","沙虛留虎跡，水滑帶龍涎。","却下臨江路，潮深無渡船。"]', '["雙巖瀉一川，回马斷橋前。","古廟陰风地，寒鐘暮雨天。","沙虛留虎跡，水滑带龙涎。","却下臨江路，潮深無渡船。"]', '诗', 'shi', '', NULL, '暝投靈智寺渡谿不得却取沿江路往 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e57774bf-1620-4f7b-8366-e4510951e6bb', '下第歸蒲城墅居', '下第归蒲城墅居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["失意歸三徑，傷春別九門。","薄煙楊柳路，微雨杏花村。","牧豎還呼犢，隣翁亦抱孫。","不知余正苦，迎馬問寒溫。"]', '["失意归三徑，傷春別九门。","薄煙楊柳路，微雨杏花村。","牧豎還呼犢，隣翁亦抱孫。","不知余正苦，迎马问寒溫。"]', '诗', 'shi', '', NULL, '下第歸蒲城墅居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2562194-d1c6-4565-9f22-6a43aec65eab', '重賦鷺鷥', '重賦鷺鷥', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["何年去此地，南浦滿鳧雛。","雲漢知心遠，林塘覺思孤。","低飛下晚樹，獨睡映新蒲。","爲爾多歸興，前年在五湖。"]', '["何年去此地，南浦满鳧雛。","云漢知心远，林塘覺思孤。","低飞下晚樹，独睡映新蒲。","爲爾多归兴，前年在五湖。"]', '诗', 'shi', '', NULL, '重賦鷺鷥 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d38ae55-3a46-4607-b6be-362248664d71', '途中寒食', '途中寒食', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["處處哭聲悲，行人馬亦遲。","店閑無火日，村暖斫桑時。","泣路同楊子，燒山憶介推。","清明明日是，甘負故園期。"]', '["处处哭声悲，行人马亦遲。","店闲無火日，村暖斫桑时。","泣路同楊子，燒山憶介推。","清明明日是，甘負故园期。"]', '诗', 'shi', '', NULL, '途中寒食 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bfee4d8-2855-4b03-b000-f9ecc8cdd5c0', '深春', '深春', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["故里千帆外，深春一鴈飛。","干名頻慟哭，將老欲何歸。","未穀拋還憶，交親晚更稀。","空持望鄉淚，霑灑寄來衣。"]', '["故里千帆外，深春一鴈飞。","干名頻慟哭，將老欲何归。","未穀拋還憶，交親晚更稀。","空持望乡泪，霑灑寄来衣。"]', '诗', 'shi', '', NULL, '深春 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b97cae5b-8e62-40e1-96d2-2422315eb31c', '歲首懷甘露寺自省上人', '歲首懷甘露寺自省上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["心悟覺身勞，雲中棄寶刀。","久閑生䏶肉，多壽長眉毫。","客棹春潮急，禪齋暮雪高。","南𤃩一回首，山碧水滔滔。"]', '["心悟覺身勞，云中棄寶刀。","久闲生䏶肉，多壽长眉毫。","客棹春潮急，禪斋暮雪高。","南𤃩一回首，山碧水滔滔。"]', '诗', 'shi', '', NULL, '歲首懷甘露寺自省上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2c8a9d7-81c3-454f-bfc6-4f303672f097', '尋周鍊師不遇留贈', '尋周鍊師不遇留贈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["閉門池館靜，云訪紫芝翁。","零落槿花雨，參差荷葉風。","夜碁全局在，春酒半壺空。","長嘯倚西閣，悠悠名利中。"]', '["閉门池館静，云訪紫芝翁。","零落槿花雨，參差荷葉风。","夜碁全局在，春酒半壺空。","长嘯倚西閣，悠悠名利中。"]', '诗', 'shi', '', NULL, '尋周鍊師不遇留贈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3b86677-69e0-41a3-aa83-56ae7364cfda', '題灞西駱隱居', '題灞西駱隐居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["志凌三蜀客，心愛五湖人。","𢬵死酒中老，謀生書外貧。","掃花眠石榻，擣藥轉溪輪。","往往乘黃牸，鹿裘烏角巾。"]', '["志凌三蜀客，心愛五湖人。","𢬵死酒中老，謀生书外貧。","掃花眠石榻，擣藥轉溪輪。","往往乘黄牸，鹿裘烏角巾。"]', '诗', 'shi', '', NULL, '題灞西駱隱居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b52231a-a838-41a4-aa12-7e0876ce48cc', '旅夜懷遠客', '旅夜懷远客', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["異鄉多遠情，夢斷落江城。","病起慙書癖，貧家負酒名。","過春花自落，竟曉月空明。","獨此一長嘯，故人天際行。"]', '["異乡多远情，梦斷落江城。","病起慙书癖，貧家負酒名。","過春花自落，竟晓月空明。","独此一长嘯，故人天際行。"]', '诗', 'shi', '', NULL, '旅夜懷遠客 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4079b65c-9a7a-40c5-8510-c8f943a8327d', '秋夜櫂舟訪李隱君', '秋夜櫂舟訪李隐君', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["望月憶披襟，長溪柳半陰。","高齋初釀酒，孤棹遠攜琴。","犬吠秋山迥，雞鳴曉樹深。","開門更攲枕，誰識野人心。"]', '["望月憶披襟，长溪柳半陰。","高斋初釀酒，孤棹远携琴。","犬吠秋山迥，雞鳴晓樹深。","开门更攲枕，誰識野人心。"]', '诗', 'shi', '', NULL, '秋夜櫂舟訪李隱君 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60c1ee80-ab05-4465-b52d-7dd34da06849', '臥病寄諸公', '臥病寄諸公', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["飛蓋集蘭堂，清歌遰柏觴。","高城榆柳蔭，虛閣芰荷香。","海月秋偏靜，山風夜更涼。","自憐書萬卷，扶病對螢光。"]', '["飞蓋集蘭堂，清歌遰柏觴。","高城榆柳蔭，虛閣芰荷香。","海月秋偏静，山风夜更涼。","自怜书万卷，扶病对螢光。"]', '诗', 'shi', '', NULL, '臥病寄諸公 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1650ca54-664a-4e3b-b01a-1f343cc88e3a', '寓崇聖寺懷李校書', '寓崇聖寺懷李校书', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["幾日臥南亭，卷簾秋月清。","河關初罷夢，池閣更含情。","寒露潤金井，高風飄玉箏。","前年共遊客，刀筆事戎旌。"]', '["幾日臥南亭，卷簾秋月清。","河关初罷梦，池閣更含情。","寒露潤金井，高风飄玉箏。","前年共游客，刀笔事戎旌。"]', '诗', 'shi', '', NULL, '寓崇聖寺懷李校書 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c064166-83bb-49be-91ba-1c9e10f5b468', '秋日行次關西', '秋日行次关西', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["金風蕩天地，關西羣木凋。","早霜雞喔喔，殘月馬蕭蕭。","紫陌秦山近，青楓楚樹遙。","還同長卿志，題字滿河橋。"]', '["金风蕩天地，关西羣木凋。","早霜雞喔喔，殘月马蕭蕭。","紫陌秦山近，青楓楚樹遙。","還同长卿志，題字满河橋。"]', '诗', 'shi', '', NULL, '秋日行次關西 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca23a19c-aaf0-447d-9b26-89227da55dac', '山居冬夜喜魏扶見訪因贈', '山居冬夜喜魏扶见訪因贈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["霜風露葉下，遠思獨裴回。","夜久草堂靜，月明山客來。","遣貧相勸酒，憶字共書灰。","何事清平世，干名待有媒。"]', '["霜风露葉下，远思独裴回。","夜久草堂静，月明山客来。","遣貧相勸酒，憶字共书灰。","何事清平世，干名待有媒。"]', '诗', 'shi', '', NULL, '山居冬夜喜魏扶見訪因贈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54b3143-f029-414a-873b-da6670b5ebbb', '喜李詡秀才見訪因贈', '喜李詡秀才见訪因贈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["浙南分首日，誰謂別經時。","路遠遙相訪，家貧喜見知。","不須辭小酌，更請續新詩。","但得心中劒，酬恩會有期。"]', '["浙南分首日，誰謂別經时。","路远遙相訪，家貧喜见知。","不須辞小酌，更請續新诗。","但得心中劒，酬恩會有期。"]', '诗', 'shi', '', NULL, '喜李詡秀才見訪因贈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a43d6cc-e2ba-4cb9-8b91-49119364c9d5', '晚投慈恩寺呈俊上人', '晚投慈恩寺呈俊上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["雙巖瀉一川，十里絕人煙。","古廟陰風地，寒鐘暮雨天。","沙虛留虎跡，水滑帶龍涎。","不及曹溪侶，空林已夜禪。"]', '["雙巖瀉一川，十里絕人煙。","古廟陰风地，寒鐘暮雨天。","沙虛留虎跡，水滑带龙涎。","不及曹溪侶，空林已夜禪。"]', '诗', 'shi', '', NULL, '晚投慈恩寺呈俊上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41103129-3b0a-4e4e-a1c7-7ceb8da4d59e', '行次虎頭巖酬寄路中丞', '行次虎头巖酬寄路中丞', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["樟亭去已遠，來上虎頭巖。","灘急水移棹，山回風滿帆。","石梯迎雨滑，沙井落潮醎。","何以慰行旅，如公書一緘。"]', '["樟亭去已远，来上虎头巖。","灘急水移棹，山回风满帆。","石梯迎雨滑，沙井落潮醎。","何以慰行旅，如公书一緘。"]', '诗', 'shi', '', NULL, '行次虎頭巖酬寄路中丞 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f686881d-d8e5-4ab5-b8aa-267d085b8f3c', '送荔浦蔣明府赴任', '送荔浦蔣明府赴任', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["路長春欲盡，歌怨酒初酣。","白社蓮宮北，青袍桂水南。","驛行盤鳥道，船宿避龍潭。","真得詩人趣，煙霞處處諳。"]', '["路长春欲尽，歌怨酒初酣。","白社蓮宮北，青袍桂水南。","驛行盤鸟道，船宿避龙潭。","真得诗人趣，煙霞处处諳。"]', '诗', 'shi', '', NULL, '送荔浦蔣明府赴任 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0628cb36-de19-48ab-91b5-529bf3915cef', '懷政禪師院', '懷政禪師院', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["山齋路幾層，敗衲學真乘。","寒暑移雙樹，光陰盡一燈。","風飄高竹雪，泉漲小池冰。","莫訝頻來此，修身欲到僧。"]', '["山斋路幾層，敗衲学真乘。","寒暑移雙樹，光陰尽一灯。","风飄高竹雪，泉漲小池冰。","莫訝頻来此，修身欲到僧。"]', '诗', 'shi', '', NULL, '懷政禪師院 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d83d53e-72cb-4952-9d3b-23f39b2dc327', '秋夕有懷', '秋夕有懷', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["念遠坐西閣，華池涵月涼。","書回秋欲盡，酒醒夜初長。","露白蓮衣淺，風清蕙帶香。","前年此佳景，蘭棹醉橫塘。"]', '["念远坐西閣，华池涵月涼。","书回秋欲尽，酒醒夜初长。","露白蓮衣淺，风清蕙带香。","前年此佳景，蘭棹醉橫塘。"]', '诗', 'shi', '', NULL, '秋夕有懷 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f7ad17-52fc-4b03-9b3c-d4ae667ed27e', '秋霽寄遠', '秋霽寄远', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["初霽獨登賞，西樓多遠風。","橫煙秋水上，疎雨夕陽中。","高樹下山鳥，平蕪飛草蟲。","唯應待明月，千里與君同。"]', '["初霽独登賞，西楼多远风。","橫煙秋水上，疎雨夕陽中。","高樹下山鸟，平蕪飞草蟲。","唯應待明月，千里與君同。"]', '诗', 'shi', '', NULL, '秋霽寄遠 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0cb521b-e9a6-495e-8d79-137ead276e48', '聞范秀才自蜀遊江湖', '闻范秀才自蜀游江湖', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["蜀道下湘渚，客帆應不迷。","江分三峽響，山並九華齊。","秋泊鴈初宿，夜吟猨乍啼。","歸時慎行李，莫到石城西。"]', '["蜀道下湘渚，客帆應不迷。","江分三峽响，山並九华齊。","秋泊鴈初宿，夜吟猨乍啼。","归时慎行李，莫到石城西。"]', '诗', 'shi', '', NULL, '聞范秀才自蜀遊江湖 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfff9164-145b-4853-ac0f-1388ddbb95ab', '惜春', '惜春', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["花開又花落，時節暗中遷。","無計延春日，可能留少年。","小藂初散蝶，高柳即聞蟬。","繁豔歸何處，滿山啼杜鵑。"]', '["花开又花落，时節暗中遷。","無計延春日，可能留少年。","小藂初散蝶，高柳即闻蟬。","繁豔归何处，满山啼杜鵑。"]', '诗', 'shi', '', NULL, '惜春 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f42d1dec-f5ef-49ca-9457-6b9eca0dba16', '題愁', '題愁', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["聚散竟無形，迴腸百結成。","古今銷不得，離別覺潛生。","降虜將軍思，窮秋遠客情。","何人更憔悴，落第泣秦京。"]', '["聚散竟無形，迴腸百結成。","古今銷不得，離別覺潛生。","降虜將軍思，窮秋远客情。","何人更憔悴，落第泣秦京。"]', '诗', 'shi', '', NULL, '題愁 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba0d782-e195-4bbc-b490-c82a72f57c23', '鴛鴦', '鴛鴦', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["兩兩戲沙汀，長疑畫不成。","錦機爭織樣，歌曲愛呼名。","好□顧栖息，堪憐泛淺情。","鳧鷗皆爾類，唯羨獨含情。"]', '["兩兩戲沙汀，长疑畫不成。","錦機爭织樣，歌曲愛呼名。","好□顧栖息，堪怜泛淺情。","鳧鷗皆爾類，唯羨独含情。"]', '诗', 'shi', '', NULL, '鴛鴦 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fbfe40e-2275-4b4c-9e80-76cb9579615c', '聞鴈', '闻鴈', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["帶霜南去鴈，夜好宿汀沙。","驚起向何處，高飛極海涯。","入雲聲漸遠，離岳路猶賒。","歸夢當時斷，參差欲到家。"]', '["带霜南去鴈，夜好宿汀沙。","驚起向何处，高飞極海涯。","入云声漸远，離岳路猶賒。","归梦當时斷，參差欲到家。"]', '诗', 'shi', '', NULL, '聞鴈 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a04775-5bbd-4432-bec9-bd7b74d713c0', '不寢', '不寢', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["到曉不成夢，思量堪白頭。","多無百年命，長有萬般愁。","世事應難盡，營生卒未休。","莫言名與利，名利是身讐。"]', '["到晓不成梦，思量堪白头。","多無百年命，长有万般愁。","世事應难尽，營生卒未休。","莫言名與利，名利是身讐。"]', '诗', 'shi', '', NULL, '不寢 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc982de-af2c-42c1-91c1-cc961e43726a', '宿東橫山', '宿东橫山', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["孤舟路漸賒，時見碧桃花。","溪雨灘聲急，巖風樹勢斜。","獼猴垂弱蔓，鸛鶴[睡]橫槎。","謾向仙林宿，無人[識]阮家。"]', '["孤舟路漸賒，时见碧桃花。","溪雨灘声急，巖风樹勢斜。","獼猴垂弱蔓，鸛鹤[睡]橫槎。","謾向仙林宿，無人[識]阮家。"]', '诗', 'shi', '', NULL, '宿東橫山 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2536a51-596f-48d2-ab0c-bbf89ad63d8f', '早行', '早行', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["失枕驚先起，人家半夢中。","聞雞憑早晏，占斗認西東。","轡濕知行露，衣單覺曉風。","秋陽弄光影，忽吐半林紅。"]', '["失枕驚先起，人家半梦中。","闻雞憑早晏，占斗認西东。","轡濕知行露，衣單覺晓风。","秋陽弄光影，忽吐半林紅。"]', '诗', 'shi', '', NULL, '早行 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b655e14-26ee-4390-9e54-a890202b1194', '陪鄭史君泛舟晚歸', '陪鄭史君泛舟晚归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南郭望歸處，郡樓高卷簾。","平橋低皂蓋，曲岸轉彤襜。","江晚笙歌促，山晴鼓角嚴。","羊公莫先醉，清曉月纖纖。"]', '["南郭望归处，郡楼高卷簾。","平橋低皂蓋，曲岸轉彤襜。","江晚笙歌促，山晴鼓角嚴。","羊公莫先醉，清晓月纖纖。"]', '诗', 'shi', '', NULL, '陪鄭史君泛舟晚歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f06c7d03-cb39-43df-aa4d-012ecae0504f', '詶殷堯藩', '詶殷堯藩', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["相如愧許詢，寥落向溪濱。","竹馬兒猶小，荆釵婦慣貧。","獨愁憂過日，多病不如人。","莫怪青袍選，長安隱舊春。"]', '["相如愧許詢，寥落向溪濱。","竹马兒猶小，荆釵婦慣貧。","独愁憂過日，多病不如人。","莫怪青袍選，长安隐旧春。"]', '诗', 'shi', '', NULL, '詶殷堯藩 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49031c97-ebf6-4985-96b6-c29aa3b200ff', '贈遷客', '贈遷客', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["無機還得罪，直道不傷情。","微雨昏山色，疎籠閉鶴聲。","閑居多野客，高枕見江城。","門外長谿水，憐君又濯纓。"]', '["無機還得罪，直道不傷情。","微雨昏山色，疎籠閉鹤声。","闲居多野客，高枕见江城。","门外长谿水，怜君又濯纓。"]', '诗', 'shi', '', NULL, '贈遷客 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4400596-1ff0-48eb-b424-0c5fb8db9fe7', '征西舊卒', '征西旧卒', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["少年乘勇氣，百戰過烏孫。","力盡邊城難，功加上將恩。","曉風聽戍角，殘月倚營門。","自說輕生處，金瘡有舊痕。"]', '["少年乘勇氣，百戰過烏孫。","力尽邊城难，功加上將恩。","晓风听戍角，殘月倚營门。","自说轻生处，金瘡有旧痕。"]', '诗', 'shi', '', NULL, '征西舊卒 許渾 shi');
